/* Câu hỏi các đề Hoá học lớp 12 có sẵn. Danh mục (tên, khối, môn, số phút, số câu): data/banks/index.js.
   App chỉ tải file này khi mở một đề trong đó. Dạng câu hỏi: xem đầu data/banks/index.js. */
window.ONTAP_SEED_QUESTIONS = Object.assign(window.ONTAP_SEED_QUESTIONS || {}, {
  /* ---------- Hoá học 12 · Kiểm tra cuối học kì I (Kết nối tri thức, Hoá học 12, Bài 1–15; Phiên N12-ck1-vatli-hoahoc) ----------
     Phạm vi theo nguồn đa số tra được (ma trận cuối kì I theo Công văn 7991, đề cương và đề học kì I sách Kết nối tri thức; nguồn
     ghi ở Pull Request của phiên): Chương 1 Ester – Lipid, Chương 2 Carbohydrate, Chương 3 Hợp chất chứa nitrogen, Chương 4 Polymer
     và Bài 15 Thế điện cực và nguồn điện hoá học của Chương 5, trọng tâm Chương 3–5. Bài 16 Điện phân để sang kho giữa kì II; trường
     đã học Bài 16 thì đối chiếu đề cương. Hai đề cố định 25 câu (9 câu Chương 1–2, 12 câu Chương 3–4, 4 câu Bài 15), chia đúng ma trận
     10 Biết, 8 Hiểu, 7 Vận dụng trên 11 chủ đề theo tên bài của sách (ma trận ở data/banks/index.js; các bài ôn tập chương không ra
     câu riêng). Hai đề là kho của đề ngẫu nhiên "hoahoc12-ck1-ngau-nhien" (không có câu riêng nên không ghi vào file này), nên ô (chủ
     đề, mức) nào cũng có đúng gấp đôi số câu ô đó rút. Dạng câu theo khung Công văn 7991: nhiều lựa chọn, đúng/sai 4 ý (mỗi đề 3 câu,
     kiểu Đ/S không lặp), trả lời ngắn bằng số, mỗi đề 1 câu tự luận tự chấm ở hai ô Vận dụng khác nhau (Tinh bột và cellulose;
     Ester – Lipid). Sách không dạy định luật Faraday (Bài 16 chỉ nêu thứ tự điện phân và ứng dụng), nên kho không có câu tính theo
     định luật này. Tên chất theo sách (IUPAC), công thức viết bằng chữ số dưới dòng, dấu thanh kiểu sách (hoá, thuỷ); nguyên tử khối
     cho trong đề; tests/vatli-hoahoc12-ck1.js tính lại mọi câu có số, kiểm tra mọi phương trình hoá học cân bằng (cả điện tích) và đọc
     lại hoá trị trong hình công thức cấu tạo. Câu tự soạn, đối chiếu với sách in năm 2026; không dùng bối cảnh, số liệu của ví dụ, bài
     tập trong sách và không hỏi lại ví dụ đời sống của kho KHTN 9. Cách xếp mức: nhận biết chất, tên gọi, khái niệm, ứng dụng là Biết;
     giải thích tính chất, so sánh, dự đoán phản ứng, tính theo một bước là Hiểu; tính nhiều bước theo phương trình, hiệu suất, dung
     dịch, ghép pin là Vận dụng. */
  "hoahoc12-ck1-de1": {
    note: "Sách Kết nối tri thức, Hoá học 12. Phạm vi cuối học kì I: Chương 1 Ester – Lipid, Chương 2 Carbohydrate (Bài 1–7) 9 câu; Chương 3 Hợp chất chứa nitrogen, Chương 4 Polymer (Bài 8–14) 12 câu; Bài 15 Thế điện cực và nguồn điện hoá học 4 câu. Trường đã học thêm Bài 16 (Điện phân) trước khi kiểm tra thì phụ huynh đối chiếu với đề cương của trường. Một số câu cần máy tính cầm tay. Có lời giải từng câu. Từ năm học 2026–2027 Sở GD&ĐT ra đề chung cuối kì một số môn lớp 12; xem thông báo của Sở về môn và cấu trúc đề.",
    questions: [
      { topic: "Ester – Lipid", type: "mc", q: "Công thức cấu tạo của một ester được vẽ ở hình bên. Ester này có tên là", o: ["methyl propanoate", "propyl methanoate", "ethyl acetate", "methyl acetate"],
        x: "Nguyên tử carbon của nhóm C=O nối với –CH₂–CH₃ ở bên trái, nên gốc acid có 3 nguyên tử carbon (gốc propanoate); nguyên tử oxygen bên phải nối với –CH₃ (gốc methyl). Ester là CH₃CH₂COOCH₃: methyl propanoate (methyl propionate). Ethyl acetate CH₃COOC₂H₅ là đồng phân của ester này: công thức phân tử như nhau, cấu tạo khác.",
        svg: '<svg viewBox="0 0 320 190" width="320"><title>Công thức cấu tạo của một ester</title><line x1="30" y1="104" x2="48" y2="104" stroke="ink" stroke-width="1.5"/><line x1="72" y1="104" x2="98" y2="104" stroke="ink" stroke-width="1.5"/><line x1="122" y1="104" x2="148" y2="104" stroke="ink" stroke-width="1.5"/><line x1="172" y1="104" x2="198" y2="104" stroke="ink" stroke-width="1.5"/><line x1="222" y1="104" x2="246" y2="104" stroke="ink" stroke-width="1.5"/><line x1="270" y1="104" x2="288" y2="104" stroke="ink" stroke-width="1.5"/><line x1="60" y1="92" x2="60" y2="66" stroke="ink" stroke-width="1.5"/><line x1="60" y1="116" x2="60" y2="142" stroke="ink" stroke-width="1.5"/><line x1="110" y1="92" x2="110" y2="66" stroke="ink" stroke-width="1.5"/><line x1="110" y1="116" x2="110" y2="142" stroke="ink" stroke-width="1.5"/><line x1="156.5" y1="92" x2="156.5" y2="62" stroke="ink" stroke-width="1.5"/><line x1="163.5" y1="92" x2="163.5" y2="62" stroke="ink" stroke-width="1.5"/><line x1="258" y1="92" x2="258" y2="66" stroke="ink" stroke-width="1.5"/><line x1="258" y1="116" x2="258" y2="142" stroke="ink" stroke-width="1.5"/><text x="18" y="109" text-anchor="middle" font-weight="bold">H</text><text x="60" y="109" text-anchor="middle" font-weight="bold">C</text><text x="110" y="109" text-anchor="middle" font-weight="bold">C</text><text x="160" y="109" text-anchor="middle" font-weight="bold">C</text><text x="210" y="109" text-anchor="middle" font-weight="bold">O</text><text x="258" y="109" text-anchor="middle" font-weight="bold">C</text><text x="300" y="109" text-anchor="middle" font-weight="bold">H</text><text x="60" y="59" text-anchor="middle" font-weight="bold">H</text><text x="60" y="159" text-anchor="middle" font-weight="bold">H</text><text x="110" y="59" text-anchor="middle" font-weight="bold">H</text><text x="110" y="159" text-anchor="middle" font-weight="bold">H</text><text x="160" y="55" text-anchor="middle" font-weight="bold">O</text><text x="258" y="59" text-anchor="middle" font-weight="bold">H</text><text x="258" y="159" text-anchor="middle" font-weight="bold">H</text></svg>', lv: 1 },
      { topic: "Ester – Lipid", type: "tf4", q: "Mỗi ý sau về ester và chất béo đúng hay sai?",
        o: ["Ethyl acetate (phân tử khối 88) sôi ở nhiệt độ thấp hơn pentan-1-ol (phân tử khối 88) vì giữa các phân tử ester không có liên kết hydrogen.", "Đun nóng ethyl propanoate với dung dịch NaOH là phản ứng thuận nghịch.", "Dầu ăn để lâu trong không khí bị ôi do các gốc acid béo không no bị oxygen oxi hoá chậm.", "Trong công thức RCOOR′ của ester đơn chức, R′ có thể là nguyên tử hydrogen."], a: [true, false, true, false],
        x: "a) Đúng: hai chất có phân tử khối bằng nhau, nhưng các phân tử pentan-1-ol liên kết hydrogen với nhau còn các phân tử ester thì không, nên ester sôi ở nhiệt độ thấp hơn nhiều. b) Sai: khi đun với dung dịch NaOH, ester bị thuỷ phân hết (phản ứng xà phòng hoá xảy ra một chiều); thuỷ phân ester trong dung dịch acid mới thường là phản ứng thuận nghịch. c) Đúng: oxygen trong không khí oxi hoá chậm các gốc acid béo không no, tạo ra các chất có mùi khó chịu. d) Sai: trong RCOOR′, R là gốc hydrocarbon hoặc H, còn R′ phải là gốc hydrocarbon; nếu thay R′ bằng H thì được carboxylic acid chứ không phải ester.", lv: 2 },
      { topic: "Ester – Lipid", type: "num", q: "Đun nóng 15 g acetic acid với 14,8 g butan-1-ol (xúc tác H₂SO₄ đặc), thu được 17,4 g butyl acetate (CH₃COOC₄H₉), một chất dùng làm dung môi pha sơn. Hiệu suất của phản ứng là bao nhiêu phần trăm? (Cho H = 1, C = 12, O = 16.)", ans: 75, unit: "%",
        x: "CH₃COOH + C₄H₉OH ⇌ CH₃COOC₄H₉ + H₂O. n(CH₃COOH) = 15 : 60 = 0,25 (mol); n(C₄H₉OH) = 14,8 : 74 = 0,2 (mol). Butan-1-ol hết trước nên tính theo butan-1-ol: lượng ester tối đa là 0,2 mol, tức 0,2 · 116 = 23,2 (g). Hiệu suất: 17,4 : 23,2 · 100% = 75%.", lv: 3 },
      { topic: "Xà phòng và chất giặt rửa", type: "mc", q: "Phần kị nước (“đuôi” kị nước) trong phân tử xà phòng và chất giặt rửa tổng hợp là", o: ["gốc hydrocarbon mạch dài", "nhóm carboxylate –COO⁻ ở đầu phân tử", "nhóm sulfonate –SO₃⁻", "ion Na⁺ hoặc ion K⁺"],
        x: "Phân tử xà phòng và chất giặt rửa gồm đầu ưa nước (nhóm carboxylate, sulfate hoặc sulfonate mang điện) và đuôi kị nước là gốc hydrocarbon mạch dài. Đuôi kị nước len vào vết bẩn dầu mỡ, đầu ưa nước quay ra ngoài, giúp vết bẩn bị chia nhỏ và trôi theo nước.", lv: 1 },
      { topic: "Giới thiệu về carbohydrate. Glucose và fructose", type: "mc", q: "Ở dạng mạch hở, phân tử fructose chứa", o: ["năm nhóm hydroxy và một nhóm ketone", "năm nhóm hydroxy và một nhóm aldehyde", "bốn nhóm hydroxy và một nhóm carboxyl", "một nhóm hydroxy và một nhóm ester"],
        x: "Fructose (C₆H₁₂O₆) ở dạng mạch hở có năm nhóm –OH và một nhóm ketone (>C=O), nên vừa thể hiện tính chất của một polyalcohol, vừa thể hiện tính chất của ketone. Glucose mạch hở mới có nhóm aldehyde.", lv: 1 },
      { topic: "Giới thiệu về carbohydrate. Glucose và fructose", type: "num", q: "Cho 180 g dung dịch glucose 5% (loại dùng để truyền tĩnh mạch) tác dụng hoàn toàn với lượng dư thuốc thử Tollens, đun nóng nhẹ. Khối lượng bạc thu được là bao nhiêu gam? (Cho H = 1, C = 12, O = 16, Ag = 108.)", ans: 10.8, unit: "g",
        x: "Khối lượng glucose: 180 · 5% = 9 (g); n(C₆H₁₂O₆) = 9 : 180 = 0,05 (mol). Nhóm aldehyde của mỗi phân tử glucose khử ion bạc thành 2 nguyên tử Ag: n(Ag) = 2 · 0,05 = 0,1 (mol), m(Ag) = 0,1 · 108 = 10,8 (g).", lv: 3 },
      { topic: "Saccharose và maltose", type: "tf4", q: "Đường kính (saccharose) làm từ mía và mạch nha (chứa nhiều maltose) làm từ hạt ngũ cốc nảy mầm. Mỗi ý sau đúng hay sai?",
        o: ["Phân tử maltose được tạo thành từ một đơn vị glucose liên kết với một đơn vị fructose.", "Công thức phân tử của saccharose và của maltose đều là C₁₂H₂₂O₁₁.", "Cho Cu(OH)₂ vào dung dịch saccharose có NaOH, lắc đều thì Cu(OH)₂ tan, dung dịch có màu xanh lam.", "Phân tử saccharose mở vòng được nên dung dịch saccharose tạo kết tủa bạc với thuốc thử Tollens."], a: [false, true, true, false],
        x: "a) Sai: phân tử maltose gồm hai đơn vị glucose nối với nhau qua liên kết α-1,4-glycoside. b) Đúng: cả hai đều là disaccharide C₁₂H₂₂O₁₁. c) Đúng: saccharose là một polyalcohol (có các nhóm –OH liền kề) nên phản ứng với Cu(OH)₂, cho dung dịch xanh lam. d) Sai: saccharose chỉ có dạng mạch vòng, không mở vòng tạo nhóm aldehyde nên không tạo kết tủa bạc với thuốc thử Tollens.", lv: 2 },
      { topic: "Tinh bột và cellulose", type: "mc", q: "Phân tử cellulose được cấu tạo từ", o: ["các đơn vị β-glucose, tạo thành mạch không phân nhánh", "các đơn vị α-glucose, tạo thành mạch có nhiều chỗ phân nhánh", "các đơn vị α-glucose và β-fructose xen kẽ nhau", "các đơn vị fructose, tạo thành mạch xoắn lò xo"],
        x: "Cellulose gồm rất nhiều đơn vị β-glucose nối với nhau qua liên kết β-1,4-glycoside, tạo thành chuỗi dài không phân nhánh. Mạch có phân nhánh gồm các đơn vị α-glucose là amylopectin trong tinh bột.", lv: 1 },
      { topic: "Tinh bột và cellulose", type: "essay", q: "Trình bày lời giải. Một nhà máy sản xuất ethanol từ ngô hạt chứa 72% tinh bột về khối lượng. Tinh bột được thuỷ phân hoàn toàn thành glucose, rồi lên men glucose thành ethanol; hiệu suất của cả quá trình là 60%. Từ 450 kg ngô hạt: a) Viết phương trình hoá học của hai giai đoạn. b) Tính khối lượng ethanol thu được. c) Tính khối lượng khí carbon dioxide sinh ra ở giai đoạn lên men. (Cho H = 1, C = 12, O = 16.)",
        rubric: [{ c: "Viết đúng hai phương trình: (C₆H₁₀O₅)ₙ + nH₂O → nC₆H₁₂O₆ (xúc tác enzyme hoặc acid) và C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂ (enzyme)", p: 0.5 }, { c: "Tính được khối lượng tinh bột 324 kg, ứng với 324 000 : 162 = 2 000 (mol) mắt xích C₆H₁₀O₅", p: 0.5 }, { c: "Theo sơ đồ, 1 mắt xích C₆H₁₀O₅ cho 2 phân tử C₂H₅OH; với hiệu suất 60% thu được 2 · 2 000 · 0,6 = 2 400 (mol) ethanol, tức 110,4 kg", p: 0.5 }, { c: "Số mol CO₂ bằng số mol ethanol thu được (2 400 mol), khối lượng CO₂ là 105,6 kg", p: 0.5 }],
        x: "a) (C₆H₁₀O₅)ₙ + nH₂O → nC₆H₁₂O₆; C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂. b) Khối lượng tinh bột: 450 · 72% = 324 (kg) = 324 000 g, ứng với 324 000 : 162 = 2 000 (mol) mắt xích C₆H₁₀O₅. Lượng ethanol thu được: 2 · 2 000 · 60% = 2 400 (mol), khối lượng 2 400 · 46 = 110 400 (g) = 110,4 kg. c) n(CO₂) = n(C₂H₅OH) = 2 400 mol, khối lượng 2 400 · 44 = 105 600 (g) = 105,6 kg.\nĐáp số: b) 110,4 kg; c) 105,6 kg.", lv: 3 },
      { topic: "Amine", type: "mc", q: "Amine nào sau đây là amine bậc hai?", o: ["CH₃–NH–CH(CH₃)₂", "CH₃CH₂CH₂–NH₂", "(C₂H₅)₃N", "C₆H₅–NH₂"],
        x: "Đếm số gốc hydrocarbon gắn vào nguyên tử N: CH₃–NH–CH(CH₃)₂ có hai gốc (methyl và isopropyl) nên là amine bậc hai; CH₃CH₂CH₂–NH₂ và C₆H₅–NH₂ có một gốc (bậc một); (C₂H₅)₃N có ba gốc (bậc ba).", lv: 1 },
      { topic: "Amine", type: "mc", q: "Ở nhiệt độ phòng, propylamine (CH₃CH₂CH₂NH₂, phân tử khối 59) là chất lỏng, còn butane (C₄H₁₀, phân tử khối 58) là chất khí. Nguyên nhân chủ yếu là", o: ["giữa các phân tử propylamine có liên kết hydrogen", "phân tử propylamine có nhiều nguyên tử carbon hơn", "propylamine có tính base nên khó bay hơi", "phân tử butane có liên kết đôi trong mạch carbon"],
        x: "Nhóm –NH₂ giúp các phân tử propylamine tạo liên kết hydrogen với nhau, nên propylamine sôi ở nhiệt độ cao hơn nhiều so với butane có phân tử khối gần bằng. Butane chỉ có liên kết đơn và có nhiều nguyên tử carbon hơn propylamine; tính base không quyết định nhiệt độ sôi.", lv: 2 },
      { topic: "Amine", type: "num", q: "Để trung hoà vừa hết 50 g dung dịch methylamine 6,2% cần bao nhiêu mililít dung dịch HCl 1 M? (Cho H = 1, C = 12, N = 14.)", ans: 100, unit: "mL",
        x: "m(CH₃NH₂) = 50 · 6,2% = 3,1 (g); n(CH₃NH₂) = 3,1 : 31 = 0,1 (mol). CH₃NH₂ + HCl → CH₃NH₃Cl, nên n(HCl) = 0,1 mol; thể tích dung dịch HCl: 0,1 : 1 = 0,1 (L) = 100 mL.", lv: 3 },
      { topic: "Amino acid và peptide", type: "mc", q: "Hợp chất nào sau đây là một α-amino acid?", o: ["H₂N–CH(CH₃)–COOH", "H₂N–[CH₂]₅–COOH", "CH₃–NH–CH₂–CH₃", "H₂N–CH₂–CH₂–NH₂"],
        x: "Ở α-amino acid, nhóm amino gắn vào nguyên tử carbon ở vị trí α (liền kề nhóm carboxyl): H₂N–CH(CH₃)–COOH (alanine). H₂N–[CH₂]₅–COOH có nhóm amino ở vị trí ε; hai chất còn lại không có nhóm carboxyl.", lv: 1 },
      { topic: "Amino acid và peptide", type: "mc", q: "Nhỏ dung dịch glycine có pH = 10 lên một dải giấy tẩm dung dịch điện li rồi đặt dải giấy vào điện trường. Glycine sẽ", o: ["mang điện âm và di chuyển về phía cực dương", "mang điện dương và di chuyển về phía cực âm", "trung hoà về điện, hầu như không di chuyển", "bị phân huỷ hoàn toàn thành NH₃ và CO₂"],
        x: "Ở pH khoảng 6, glycine tồn tại phần lớn dưới dạng ion lưỡng cực, trung hoà về điện. Ở pH = 10 (môi trường kiềm), nhóm –NH₃⁺ nhường proton, glycine chuyển thành anion H₂N–CH₂–COO⁻ nên di chuyển về phía cực dương. Ở pH thấp, glycine mới thành cation và di chuyển về phía cực âm.", lv: 2 },
      { topic: "Amino acid và peptide", type: "num", q: "Cho 7,5 g glycine (H₂NCH₂COOH) vào 150 mL dung dịch HCl 1 M, thu được dung dịch X. Để phản ứng vừa đủ với các chất trong X cần bao nhiêu mililít dung dịch NaOH 1 M? (Cho H = 1, C = 12, N = 14, O = 16.)", ans: 250, unit: "mL",
        x: "n(glycine) = 7,5 : 75 = 0,1 (mol); n(HCl) = 0,15 mol. H₂NCH₂COOH + HCl → ClH₃NCH₂COOH, nên trong X có 0,1 mol ClH₃NCH₂COOH và 0,05 mol HCl dư. Với NaOH: ClH₃NCH₂COOH + 2NaOH → H₂NCH₂COONa + NaCl + 2H₂O và HCl + NaOH → NaCl + H₂O. n(NaOH) = 2 · 0,1 + 0,05 = 0,25 (mol), thể tích 0,25 L = 250 mL.", lv: 3 },
      { topic: "Protein và enzyme", type: "mc", q: "Trong nước, protein nào sau đây tạo được dung dịch keo?", o: ["Albumin", "Keratin", "Collagen", "Myosin"],
        x: "Albumin (có nhiều trong lòng trắng trứng) là protein dạng hình cầu, hoà tan trong nước thành dung dịch keo. Keratin (trong tóc, móng), collagen (trong da, sụn) và myosin (trong cơ bắp) đều là protein dạng sợi, nước không hoà tan được chúng.", lv: 1 },
      { topic: "Protein và enzyme", type: "mc", q: "Khi lỡ nuốt phải muối của kim loại nặng (như muối chì), người ta thường cho người bệnh uống ngay sữa hoặc lòng trắng trứng sống rồi đưa đi cấp cứu. Cách làm này dựa trên tính chất nào của protein?", o: ["Bị ion kim loại nặng làm đông tụ, nhờ đó giữ bớt các ion này lại", "Bị thuỷ phân ngay thành amino acid để trung hoà muối kim loại", "Tạo màu tím với ion kim loại nặng nên dễ phát hiện", "Tan tốt trong nước nên pha loãng được muối kim loại nặng"],
        x: "Ion kim loại nặng làm protein trong sữa, lòng trắng trứng đông tụ. Protein đông tụ giữ lại một phần ion kim loại nặng, nên lượng ion đi vào cơ thể và gây hại ít hơn; người bệnh vẫn cần được cấp cứu.", lv: 2 },
      { topic: "Đại cương về polymer", type: "mc", q: "Polymer nào sau đây được tổng hợp bằng phản ứng trùng ngưng?", o: ["Poly(phenol formaldehyde)", "Polypropylene", "Poly(methyl methacrylate)", "Polybuta-1,3-diene"],
        x: "Poly(phenol formaldehyde) (PPF) tạo thành từ phenol và formaldehyde, đồng thời giải phóng nước: đó là phản ứng trùng ngưng. Polypropylene, poly(methyl methacrylate), polybuta-1,3-diene đều điều chế từ monomer có liên kết đôi bằng phản ứng trùng hợp.", lv: 1 },
      { topic: "Đại cương về polymer", type: "mc", q: "Đun nóng cao su tự nhiên với lưu huỳnh, các mạch polymer được nối với nhau bởi các cầu nối disulfide (–S–S–). Phản ứng này thuộc loại", o: ["phản ứng tăng mạch polymer", "phản ứng cắt mạch polymer", "phản ứng giữ nguyên mạch polymer", "phản ứng trùng ngưng"],
        x: "Các cầu nối –S–S– nối nhiều mạch polymer với nhau thành mạng lưới, nên lưu hoá cao su là phản ứng tăng mạch polymer; cao su lưu hoá bền hơn cao su chưa lưu hoá.", lv: 2 },
      { topic: "Vật liệu polymer", type: "mc", q: "Gỗ nhựa là vật liệu composite làm từ bột gỗ trộn với nhựa polymer rồi ép thành tấm. Trong vật liệu này, nhựa polymer đóng vai trò", o: ["vật liệu nền", "vật liệu cốt", "chất xúc tác", "monomer"],
        x: "Trong composite, vật liệu cốt (ở đây là bột gỗ, dạng cốt hạt) giúp vật liệu chịu lực, còn vật liệu nền (nhựa polymer) gắn kết các hạt cốt với nhau thành một khối thống nhất.", lv: 1 },
      { topic: "Vật liệu polymer", type: "mc", q: "Áo khoác mùa đông thường được may bằng vải dệt từ tơ nitron (olon). Lí do chủ yếu là tơ nitron", o: ["giữ nhiệt tốt, dai và bền với nhiệt", "thấm hút mồ hôi tốt như sợi bông", "có tính đàn hồi tốt như cao su", "dẫn nhiệt tốt nên làm ấm cơ thể nhanh"],
        x: "Tơ nitron (polyacrylonitrile) giữ ấm tốt, lại dai và chịu được nhiệt nên hợp với áo ấm. Tơ nitron không thấm hút mồ hôi tốt như sợi bông, không đàn hồi như cao su; vải dẫn nhiệt tốt lại làm cơ thể mất nhiệt nhanh.", lv: 2 },
      { topic: "Thế điện cực và nguồn điện hoá học", type: "mc", q: "Trong một pin Galvani, hai dung dịch được nối với nhau bằng cầu muối. Cầu muối có tác dụng", o: ["đóng kín mạch và giữ hai dung dịch trung hoà về điện", "cung cấp electron cho điện cực dương của pin", "ngăn không cho ion nào đi qua lại giữa hai cốc đựng dung dịch", "làm tăng thế điện cực chuẩn của điện cực âm"],
        x: "Cầu muối cho các ion di chuyển qua giữa hai dung dịch, nhờ đó mạch điện được đóng kín và mỗi dung dịch luôn trung hoà về điện khi pin hoạt động. Electron đi từ cực âm sang cực dương qua dây dẫn bên ngoài, không qua cầu muối.", lv: 1 },
      { topic: "Thế điện cực và nguồn điện hoá học", type: "tf4", q: "Cho thế điện cực chuẩn: E°(Mg²⁺/Mg) = −2,356 V; E°(Ni²⁺/Ni) = −0,257 V; E°(Ag⁺/Ag) = +0,799 V. Mỗi ý sau đúng hay sai (ở điều kiện chuẩn)?",
        o: ["Trong ba ion Mg²⁺, Ni²⁺, Ag⁺, ion Ag⁺ có tính oxi hoá mạnh nhất.", "Kim loại Ni khử được ion Mg²⁺ trong dung dịch thành Mg.", "Kim loại Mg khử được ion Ni²⁺ trong dung dịch thành Ni.", "Kim loại Ni tác dụng được với dung dịch acid (ion H⁺), giải phóng khí H₂."], a: [true, false, true, true],
        x: "So sánh thế điện cực chuẩn: cặp nào có E° lớn hơn thì ion của nó oxi hoá mạnh hơn, kim loại của nó khử yếu hơn. a) Đúng: E°(Ag⁺/Ag) lớn nhất. b) Sai: E°(Mg²⁺/Mg) < E°(Ni²⁺/Ni) nên Ni không khử được Mg²⁺. c) Đúng: vì E°(Mg²⁺/Mg) < E°(Ni²⁺/Ni) nên Mg khử được Ni²⁺: Mg + Ni²⁺ → Mg²⁺ + Ni. d) Đúng: E°(Ni²⁺/Ni) = −0,257 V < E°(2H⁺/H₂) = 0 V nên Ni + 2H⁺ → Ni²⁺ + H₂.", lv: 2 },
      { topic: "Thế điện cực và nguồn điện hoá học", type: "num", q: "Một pin Galvani gồm điện cực Ni nhúng trong dung dịch muối Ni²⁺ và điện cực Ag nhúng trong dung dịch muối Ag⁺ (E°(Ni²⁺/Ni) = −0,257 V; E°(Ag⁺/Ag) = +0,799 V). Sau một thời gian pin hoạt động, khối lượng điện cực Ag tăng 2,16 g. Khối lượng điện cực Ni giảm bao nhiêu gam? (Cho Ni = 59, Ag = 108.)", ans: 0.59, unit: "g",
        x: "Ni có thế điện cực chuẩn nhỏ hơn nên là anode (cực âm), bị oxi hoá; ion Ag⁺ bị khử thành Ag bám vào cathode. Phản ứng trong pin: Ni + 2Ag⁺ → Ni²⁺ + 2Ag. n(Ag) = 2,16 : 108 = 0,02 (mol) ⇒ n(Ni) = 0,01 mol; khối lượng điện cực Ni giảm 0,01 · 59 = 0,59 (g).", lv: 3 },
      { topic: "Thế điện cực và nguồn điện hoá học", type: "num", q: "Cho E°(Pb²⁺/Pb) = −0,126 V; E°(Ag⁺/Ag) = +0,799 V. Mắc nối tiếp các pin Galvani Pb – Ag giống nhau (ở điều kiện chuẩn) để có hiệu điện thế ít nhất 3 V. Coi hiệu điện thế của bộ pin bằng tổng sức điện động chuẩn của các pin. Cần ít nhất bao nhiêu pin?", ans: 4, unit: "pin",
        x: "Sức điện động chuẩn của mỗi pin: E°pin = E°cathode − E°anode = 0,799 − (−0,126) = 0,925 (V). Ba pin cho 3 · 0,925 = 2,775 (V), chưa đủ 3 V; bốn pin cho 4 · 0,925 = 3,7 (V). Vậy cần ít nhất 4 pin.", lv: 3 }
    ]
  },

  /* Đề 2 (Phiên N12-ck1-vatli-hoahoc): cùng phạm vi, cùng phân bố chủ đề và mức như Đề 1; các câu hỏi điều khác Đề 1. */
  "hoahoc12-ck1-de2": {
    note: "Sách Kết nối tri thức, Hoá học 12. Phạm vi cuối học kì I: Chương 1 Ester – Lipid, Chương 2 Carbohydrate (Bài 1–7) 9 câu; Chương 3 Hợp chất chứa nitrogen, Chương 4 Polymer (Bài 8–14) 12 câu; Bài 15 Thế điện cực và nguồn điện hoá học 4 câu. Trường đã học thêm Bài 16 (Điện phân) trước khi kiểm tra thì phụ huynh đối chiếu với đề cương của trường. Một số câu cần máy tính cầm tay. Có lời giải từng câu. Từ năm học 2026–2027 Sở GD&ĐT ra đề chung cuối kì một số môn lớp 12; xem thông báo của Sở về môn và cấu trúc đề.",
    questions: [
      { topic: "Ester – Lipid", type: "mc", q: "Ở điều kiện thường, các ester có phân tử khối nhỏ như methyl formate, ethyl acetate thường", o: ["là chất lỏng, khó tan trong nước và nổi trên mặt nước", "là chất rắn kết tinh, tan tốt trong nước và có vị ngọt", "là chất khí, không có mùi", "là chất lỏng, tan tốt trong nước và chìm xuống đáy"],
        x: "Các ester có phân tử khối nhỏ và trung bình thường ở thể lỏng ở nhiệt độ phòng, khó tan trong nước và nhẹ hơn nước nên nổi lên trên; nhiều ester có mùi thơm dễ chịu như mùi hoa, mùi quả chín.", lv: 1 },
      { topic: "Ester – Lipid", type: "mc", q: "Ở nhiệt độ phòng, mỡ bò ở thể rắn còn dầu hướng dương ở thể lỏng. Nguyên nhân chủ yếu là", o: ["mỡ bò có nhiều gốc acid béo no hơn dầu hướng dương", "mỡ bò có phân tử khối nhỏ hơn dầu hướng dương", "dầu hướng dương có lẫn nhiều nước hơn mỡ bò", "mỡ bò là ester, còn dầu hướng dương không phải ester"],
        x: "Gốc acid béo no làm chất béo dễ đông rắn: mỡ bò giàu gốc no nên ở thể rắn; dầu hướng dương giàu gốc không no nên ở thể lỏng. Cả hai đều là triester của glycerol với acid béo.", lv: 2 },
      { topic: "Ester – Lipid", type: "essay", q: "Trình bày lời giải. Một loại dầu thực vật chứa 88,4% triolein ((C₁₇H₃₃COO)₃C₃H₅) về khối lượng, phần còn lại là tạp chất không phản ứng với NaOH. Đun 1 kg dầu này với dung dịch NaOH dư để triolein bị xà phòng hoá hoàn toàn. (Cho H = 1, C = 12, O = 16, Na = 23.) a) Viết phương trình hoá học của phản ứng. b) Tính khối lượng glycerol và khối lượng sodium oleate (C₁₇H₃₃COONa) thu được. c) Biết sodium oleate chiếm 76% khối lượng xà phòng bánh, tính khối lượng xà phòng bánh làm được.",
        rubric: [{ c: "Viết đúng phương trình: (C₁₇H₃₃COO)₃C₃H₅ + 3NaOH → 3C₁₇H₃₃COONa + C₃H₅(OH)₃", p: 0.5 }, { c: "Tính được khối lượng triolein 884 g, tức 884 : 884 = 1 (mol) triolein", p: 0.5 }, { c: "Tính được khối lượng glycerol 1 · 92 = 92 (g) và sodium oleate 3 · 304 = 912 (g)", p: 0.5 }, { c: "Tính được khối lượng xà phòng bánh 912 : 76% = 1 200 (g), tức 1,2 kg", p: 0.5 }],
        x: "a) (C₁₇H₃₃COO)₃C₃H₅ + 3NaOH → 3C₁₇H₃₃COONa + C₃H₅(OH)₃. b) Khối lượng triolein: 1 000 · 88,4% = 884 (g); triolein có phân tử khối 884 nên có 1 mol triolein. Thu được 1 mol glycerol (92 g) và 3 mol sodium oleate (3 · 304 = 912 g). c) Khối lượng xà phòng bánh: 912 : 0,76 = 1 200 (g) = 1,2 kg.\nĐáp số: b) 92 g glycerol, 912 g sodium oleate; c) 1,2 kg.", lv: 3 },
      { topic: "Xà phòng và chất giặt rửa", type: "mc", q: "So với xà phòng, chất giặt rửa tổng hợp có ưu điểm là", o: ["vẫn dùng được với nước cứng", "dễ bị vi sinh vật phân huỷ hơn", "được sản xuất từ mỡ động vật", "không có phần kị nước trong phân tử"],
        x: "Chất giặt rửa tổng hợp dễ tan trong nước hơn và vẫn có tác dụng trong nước cứng, môi trường acid, còn xà phòng kém tác dụng trong các môi trường này. Nhược điểm của một số chất giặt rửa tổng hợp là khó bị phân huỷ sinh học; chúng được sản xuất từ dầu mỏ.", lv: 1 },
      { topic: "Giới thiệu về carbohydrate. Glucose và fructose", type: "mc", q: "Thực phẩm nào sau đây chứa nhiều fructose nhất?", o: ["Mật ong", "Gạo tẻ", "Thịt nạc", "Lòng trắng trứng"],
        x: "Fructose có nhiều trong mật ong và trong nhiều loại quả ngọt. Gạo tẻ chứa chủ yếu tinh bột; thịt nạc và lòng trắng trứng chứa nhiều protein.", lv: 1 },
      { topic: "Giới thiệu về carbohydrate. Glucose và fructose", type: "num", q: "Nồng độ glucose trong máu của một người lúc đói là 5,5 mmol/L. Coi cơ thể người này có 5 lít máu. Khối lượng glucose có trong máu của người này là bao nhiêu gam? (Cho H = 1, C = 12, O = 16.)", ans: 4.95, unit: "g",
        x: "Số mol glucose: 5,5 · 5 = 27,5 (mmol) = 0,0275 mol. Glucose C₆H₁₂O₆ có phân tử khối 180. Khối lượng glucose: 0,0275 · 180 = 4,95 (g).", lv: 3 },
      { topic: "Saccharose và maltose", type: "mc", q: "Thuỷ phân hoàn toàn 34,2 g saccharose trong môi trường acid. Khối lượng glucose thu được là (Cho H = 1, C = 12, O = 16.)", o: ["18 g", "36 g", "9 g", "34,2 g"],
        x: "n(C₁₂H₂₂O₁₁) = 34,2 : 342 = 0,1 (mol). C₁₂H₂₂O₁₁ + H₂O → C₆H₁₂O₆ + C₆H₁₂O₆ (một phân tử glucose, một phân tử fructose), nên thu được 0,1 mol glucose, tức 0,1 · 180 = 18 (g), cùng 18 g fructose.", lv: 2 },
      { topic: "Tinh bột và cellulose", type: "mc", q: "Cellulose không tan trong nước kể cả khi đun nóng, nhưng tan được trong", o: ["nước Schweizer", "ethanol", "dung dịch NaCl", "benzene"],
        x: "Nước Schweizer là dung dịch tạo thành khi cho Cu(OH)₂ tan trong ammonia; cellulose tan được trong dung dịch này. Cellulose không tan trong nước, trong dung dịch muối ăn, cũng không tan trong ethanol hay benzene.", lv: 1 },
      { topic: "Tinh bột và cellulose", type: "num", q: "Thuỷ phân tinh bột có trong 1 kg gạo (chứa 81% tinh bột về khối lượng) với hiệu suất 75%, xúc tác enzyme. Khối lượng glucose thu được là bao nhiêu gam? (Cho H = 1, C = 12, O = 16.)", ans: 675, unit: "g",
        x: "Khối lượng tinh bột: 1 000 · 81% = 810 (g), ứng với 810 : 162 = 5 (mol) mắt xích C₆H₁₀O₅. (C₆H₁₀O₅)ₙ + nH₂O → nC₆H₁₂O₆: mỗi mắt xích cho một phân tử glucose. Với hiệu suất 75%: n(glucose) = 5 · 0,75 = 3,75 (mol), khối lượng 3,75 · 180 = 675 (g).", lv: 3 },
      { topic: "Amine", type: "mc", q: "Dung dịch chất nào sau đây không làm quỳ tím đổi màu?", o: ["Aniline", "Methylamine", "Ethylamine", "Dimethylamine"],
        x: "Aniline có tính base rất yếu nên dung dịch aniline không làm quỳ tím đổi màu. Dung dịch methylamine, ethylamine, dimethylamine làm quỳ tím chuyển màu xanh.", lv: 1 },
      { topic: "Amine", type: "tf4", q: "Mỗi ý sau về ethylamine (C₂H₅NH₂) và aniline (C₆H₅NH₂) đúng hay sai?",
        o: ["Ở nhiệt độ phòng, ethylamine là chất khí, tan tốt trong nước.", "Dung dịch ethylamine làm dung dịch phenolphthalein chuyển sang màu hồng.", "Nhỏ nước bromine vào dung dịch aniline thấy xuất hiện kết tủa màu vàng.", "Ethylamine tác dụng với dung dịch HCl tạo muối ethylammonium chloride."], a: [true, true, false, true],
        x: "a) Đúng: ethylamine sôi ở khoảng 17 °C nên là chất khí ở nhiệt độ phòng; amine có ít nguyên tử carbon tan tốt trong nước. b) Đúng: dung dịch ethylamine có môi trường base nên phenolphthalein hoá hồng. c) Sai: aniline phản ứng thế với nước bromine tạo 2,4,6-tribromoaniline là kết tủa màu trắng. d) Đúng: C₂H₅NH₂ + HCl → C₂H₅NH₃Cl (ethylammonium chloride).", lv: 2 },
      { topic: "Amine", type: "num", q: "Khử 24,6 g nitrobenzene (C₆H₅NO₂) bằng sắt trong dung dịch HCl, hiệu suất 80%. Khối lượng aniline thu được là bao nhiêu gam? (Cho H = 1, C = 12, N = 14, O = 16.)", ans: 14.88, unit: "g",
        x: "n(C₆H₅NO₂) = 24,6 : 123 = 0,2 (mol). C₆H₅NO₂ + 6[H] → C₆H₅NH₂ + 2H₂O, nên với hiệu suất 80% thu được 0,2 · 0,8 = 0,16 (mol) aniline, khối lượng 0,16 · 93 = 14,88 (g).", lv: 3 },
      { topic: "Amino acid và peptide", type: "mc", q: "Ở điều kiện thường, các amino acid", o: ["là chất rắn, dễ tan trong nước, nóng chảy ở nhiệt độ cao", "là chất lỏng sánh, không tan trong nước, sôi ở nhiệt độ thấp", "là chất khí, có mùi khai như ammonia", "là chất rắn, không tan trong nước, dễ bay hơi"],
        x: "Phân tử amino acid thường ở dạng ion lưỡng cực, giống như muối, nên amino acid là chất rắn kết tinh không màu, nóng chảy ở nhiệt độ cao, thường dễ tan trong nước.", lv: 1 },
      { topic: "Amino acid và peptide", type: "mc", q: "Chất nào sau đây không có phản ứng màu biuret?", o: ["Gly-Ala", "Gly-Ala-Val", "Ala-Gly-Val-Gly", "Lòng trắng trứng"],
        x: "Thuốc thử biuret (Cu(OH)₂ trong môi trường kiềm) cho màu tím với protein và với những peptide chứa ít nhất hai liên kết peptide. Gly-Ala là dipeptide, chỉ có một liên kết peptide nên không có phản ứng này.", lv: 2 },
      { topic: "Amino acid và peptide", type: "num", q: "Thuỷ phân hoàn toàn 20,3 g tripeptide Gly-Ala-Gly bằng dung dịch NaOH dư, đun nóng. Khối lượng muối thu được là bao nhiêu gam? (Cho H = 1, C = 12, N = 14, O = 16, Na = 23.)", ans: 30.5, unit: "g",
        x: "Gly-Ala-Gly (H₂NCH₂CONHCH(CH₃)CONHCH₂COOH, phân tử khối 203) có n = 20,3 : 203 = 0,1 (mol). H₂NCH₂CONHCH(CH₃)CONHCH₂COOH + 3NaOH → 2H₂NCH₂COONa + H₂NCH(CH₃)COONa + H₂O. Muối gồm 0,2 mol H₂NCH₂COONa (97 g/mol) và 0,1 mol H₂NCH(CH₃)COONa (111 g/mol): 0,2 · 97 + 0,1 · 111 = 30,5 (g).", lv: 3 },
      { topic: "Protein và enzyme", type: "mc", q: "Phát biểu nào sau đây đúng về enzyme?", o: ["Mỗi loại enzyme thường chỉ xúc tác một hay vài phản ứng", "Enzyme làm các phản ứng sinh hoá xảy ra chậm hơn", "Enzyme là chất béo có trong tế bào sống, dự trữ năng lượng", "Một loại enzyme xúc tác được cho mọi phản ứng sinh hoá"],
        x: "Enzyme (phần lớn có bản chất protein) làm tăng tốc độ phản ứng sinh hoá lên rất nhiều lần. Enzyme có tính chọn lọc cao: mỗi loại thường chỉ xúc tác cho một hay vài phản ứng.", lv: 1 },
      { topic: "Protein và enzyme", type: "tf4", q: "Mỗi ý sau về protein trong thực phẩm và trong cơ thể đúng hay sai?",
        o: ["Thịt, cá, trứng, sữa là những thực phẩm giàu protein.", "Thuỷ phân hoàn toàn một protein đơn giản chỉ thu được glucose.", "Nhỏ vài giọt dung dịch HNO₃ đặc vào dung dịch lòng trắng trứng thấy xuất hiện chất rắn màu xanh lam.", "Protein cung cấp cho cơ thể người các amino acid thiết yếu mà cơ thể không tự tổng hợp được."], a: [true, false, false, true],
        x: "a) Đúng: thịt, cá, trứng, sữa chứa nhiều protein. b) Sai: thuỷ phân hoàn toàn protein đơn giản thu được hỗn hợp các α-amino acid. c) Sai: nitric acid đặc tạo với lòng trắng trứng sản phẩm rắn màu vàng. d) Đúng: các amino acid thiết yếu phải lấy từ thức ăn, chủ yếu từ protein trong thức ăn.", lv: 2 },
      { topic: "Đại cương về polymer", type: "mc", q: "Polymer nào sau đây có tính đàn hồi?", o: ["Polyisoprene", "Poly(vinyl chloride)", "Polystyrene", "Nylon-6,6"],
        x: "Polyisoprene (cũng như polybuta-1,3-diene) có tính đàn hồi, dùng làm cao su. Poly(vinyl chloride), polystyrene là chất dẻo; nylon-6,6 dai, bền, dùng kéo sợi.", lv: 1 },
      { topic: "Đại cương về polymer", type: "mc", q: "Cho hydrogen cộng vào các liên kết đôi C=C trong mạch polybuta-1,3-diene (có xúc tác, đun nóng). Phản ứng này thuộc loại", o: ["phản ứng giữ nguyên mạch polymer", "phản ứng cắt mạch polymer", "phản ứng tăng mạch polymer", "phản ứng trùng ngưng"],
        x: "Hydrogen chỉ cộng vào các liên kết đôi có sẵn trong mạch; số mắt xích và độ dài mạch polymer không đổi, mạch không bị cắt và không nối thêm với mạch khác. Đây là phản ứng giữ nguyên mạch polymer.", lv: 2 },
      { topic: "Vật liệu polymer", type: "mc", q: "Tơ nào sau đây thuộc loại tơ bán tổng hợp?", o: ["Tơ visco", "Tơ tằm", "Tơ nylon-6,6", "Tơ nitron"],
        x: "Tơ visco được chế biến từ cellulose (polymer thiên nhiên) bằng phương pháp hoá học nên là tơ bán tổng hợp. Tơ tằm là tơ thiên nhiên; nylon-6,6 và nitron là tơ tổng hợp.", lv: 1 },
      { topic: "Vật liệu polymer", type: "tf4", q: "Một đôi ủng cao su, một tấm kính chắn gió của máy bay và một cuộn chỉ nylon-6,6 đều được làm từ vật liệu polymer. Mỗi ý sau đúng hay sai?",
        o: ["Nylon-6,6 là sản phẩm trùng hợp ethylene.", "Chỉ nylon-6,6 thấm nước nhiều nên không dùng để đan lưới đánh cá.", "Kính chắn gió của máy bay có thể làm từ poly(methyl methacrylate) (thuỷ tinh hữu cơ).", "Cao su không dẫn điện nên thợ điện thường đi ủng cao su khi làm việc."], a: [false, false, true, true],
        x: "a) Sai: nylon-6,6 điều chế bằng cách trùng ngưng hexamethylenediamine với adipic acid. b) Sai: sợi nylon-6,6 bền, dai, hút nước rất ít, vì thế thường dùng để bện dây cáp, đan lưới đánh cá. c) Đúng: poly(methyl methacrylate) trong suốt, bền, dùng sản xuất thuỷ tinh hữu cơ làm kính máy bay. d) Đúng: ủng, găng tay cao su giúp thợ điện tránh bị điện giật.", lv: 2 },
      { topic: "Thế điện cực và nguồn điện hoá học", type: "mc", q: "Loại pin nào sau đây chuyển đổi quang năng thành điện năng?", o: ["Pin Mặt Trời", "Pin nhiên liệu hydrogen – oxygen", "Acquy chì", "Pin khô"],
        x: "Pin Mặt Trời gồm các tấm vật liệu bán dẫn biến quang năng thành điện năng. Pin nhiên liệu, acquy, pin khô đều biến hoá năng của phản ứng oxi hoá – khử thành điện năng.", lv: 1 },
      { topic: "Thế điện cực và nguồn điện hoá học", type: "mc", q: "Cho thế điện cực chuẩn: E°(Zn²⁺/Zn) = −0,762 V; E°(Ni²⁺/Ni) = −0,257 V; E°(Sn²⁺/Sn) = −0,137 V; E°(Cu²⁺/Cu) = +0,340 V. Ở điều kiện chuẩn, phản ứng nào sau đây xảy ra?", o: ["Sn + Cu²⁺ → Sn²⁺ + Cu", "Cu + Ni²⁺ → Cu²⁺ + Ni", "Sn + Zn²⁺ → Sn²⁺ + Zn", "Ni + Zn²⁺ → Ni²⁺ + Zn"],
        x: "Chất khử của cặp có thế điện cực chuẩn nhỏ hơn phản ứng với chất oxi hoá của cặp có thế điện cực chuẩn lớn hơn. E°(Sn²⁺/Sn) < E°(Cu²⁺/Cu) nên Sn khử được Cu²⁺. Ở ba phản ứng còn lại, kim loại thuộc cặp có thế điện cực lớn hơn, ion thuộc cặp có thế điện cực nhỏ hơn, nên phản ứng không xảy ra.", lv: 2 },
      { topic: "Thế điện cực và nguồn điện hoá học", type: "num", q: "Ở điều kiện chuẩn, pin Galvani tạo bởi hai cặp Mg²⁺/Mg và Ni²⁺/Ni có sức điện động 2,099 V; pin tạo bởi hai cặp Ni²⁺/Ni và Cu²⁺/Cu có sức điện động 0,597 V. Không dùng bảng thế điện cực chuẩn, hãy tính sức điện động chuẩn (V) của pin tạo bởi hai cặp Mg²⁺/Mg và Cu²⁺/Cu. Làm tròn kết quả đến chữ số thập phân thứ hai.", ans: 2.7, tol: 0.005, unit: "V",
        x: "Trong pin Mg – Ni, Mg là anode: E°(Ni²⁺/Ni) − E°(Mg²⁺/Mg) = 2,099 V. Trong pin Ni – Cu, Ni là anode: E°(Cu²⁺/Cu) − E°(Ni²⁺/Ni) = 0,597 V. Cộng hai đẳng thức: E°(Cu²⁺/Cu) − E°(Mg²⁺/Mg) = 2,696 V ≈ 2,70 V; đó là sức điện động chuẩn của pin Mg – Cu (Mg là anode).", lv: 3 },
      { topic: "Thế điện cực và nguồn điện hoá học", type: "num", q: "Một pin nhiên liệu hydrogen – oxygen hoạt động theo phản ứng 2H₂ + O₂ → 2H₂O và mỗi phút tiêu thụ 2 g khí hydrogen. Sau 1 giờ hoạt động, pin tạo ra bao nhiêu kilôgam nước? (Cho H = 1, O = 16.)", ans: 1.08, unit: "kg",
        x: "Trong 1 giờ (60 phút), pin tiêu thụ 2 · 60 = 120 (g) H₂, tức 120 : 2 = 60 (mol). Theo phương trình, n(H₂O) = n(H₂) = 60 mol; khối lượng nước 60 · 18 = 1 080 (g) = 1,08 kg.", lv: 3 }
    ]
  },
  /* ---------- Hoá học 12 · Kiểm tra giữa học kì II (Kết nối tri thức, Hoá học 12, Bài 16, Chương 6 Bài 18–23, Bài 24; Phiên N12-gk2-vatli-hoahoc) ----------
     Phạm vi theo nguồn đa số (đề cương, ma trận giữa kì II tra được, ghi ở Pull Request của phiên): Bài 16 Điện phân (kho cuối kì I dừng
     ở Bài 15), Chương 6 Đại cương về kim loại (Bài 18–22; Bài 23 ôn tập không ra chủ đề riêng) là trọng tâm, Chương 7 đến Bài 24 Nguyên
     tố nhóm IA. Cả hai nguồn không có Bài 25 (Nguyên tố nhóm IIA), nên bài này để sang kho cuối năm. Hai đề cố định 25 câu, mỗi đề 4 câu
     Bài 16, 17 câu Chương 6, 4 câu Bài 24, chia đúng ma trận 10 Biết, 8 Hiểu, 7 Vận dụng trên 7 chủ đề theo tên bài của sách (ma trận ở
     data/banks/index.js). Hai đề là kho của đề ngẫu nhiên "hoahoc12-gk2-ngau-nhien" (không có câu riêng), nên ô (chủ đề, mức) nào cũng có
     đúng gấp đôi số câu ô đó rút. Dạng câu theo khung Công văn 7991: nhiều lựa chọn, đúng/sai 4 ý (mỗi đề 3 câu, kiểu Đ/S không lặp), trả
     lời ngắn bằng số, mỗi đề 1 câu tự luận tự chấm ở hai ô Vận dụng khác nhau (Kim loại trong tự nhiên và phương pháp tách kim loại;
     Nguyên tố nhóm IA). Sách in năm 2026 không dạy định luật Faraday nên câu điện phân chỉ tính theo phương trình hoá học. Nguyên tử khối,
     thế điện cực chuẩn đề cho như sách (Bảng 15.1); phương trình hoá học cân bằng; tests/vatli-hoahoc12-gk2.js tính lại mọi câu có số.
     Câu tự soạn, đối chiếu với sách in năm 2026; không dùng bối cảnh, số liệu của ví dụ, bài tập, thí nghiệm trong sách. */
  "hoahoc12-gk2-de1": {
    note: "Sách Kết nối tri thức, Hoá học 12. Phạm vi giữa học kì II: Bài 16 Điện phân 4 câu; Chương 6 Đại cương về kim loại (Bài 18–23) 17 câu; Bài 24 Nguyên tố nhóm IA 4 câu. Trường đã kiểm tra Bài 16 ở cuối học kì I thì bỏ qua các câu Bài 16; trường mới học đến hết Chương 6 thì bỏ qua các câu Bài 24; trường đã học thêm Bài 25 (Nguyên tố nhóm IIA) thì phụ huynh đối chiếu với đề cương của trường. Một số câu cần máy tính cầm tay. Có lời giải từng câu.",
    questions: [
      { topic: "Điện phân", type: "mc", q: "Để thực hiện quá trình điện phân một chất điện li (nóng chảy hoặc trong dung dịch), cần cho đi qua chất điện li đó", o: ["dòng điện một chiều có hiệu điện thế đủ lớn", "dòng điện xoay chiều có tần số đủ lớn", "một luồng ánh sáng mặt trời mạnh", "một luồng khí oxygen nóng"],
        x: "Phải dùng nguồn điện một chiều, hiệu điện thế đủ lớn. Mỗi điện cực giữ nguyên một vai trò (một cực luôn là anode, một cực luôn là cathode). Dòng điện xoay chiều luôn đổi chiều nên không dùng để điện phân.", lv: 1 },
      { topic: "Điện phân", type: "tf4", q: "Mạ bạc cho một chiếc thìa bằng đồng: dùng dung dịch AgNO₃, một thanh bạc làm anode, chiếc thìa làm cathode. Mỗi ý sau đúng hay sai?",
        o: ["Chiếc thìa cần mạ được nối với cực âm của nguồn điện.", "Ở anode, nước bị oxi hoá tạo ra khí oxygen.", "Nồng độ ion Ag⁺ trong dung dịch gần như không đổi trong suốt quá trình mạ.", "Với cùng cường độ dòng điện, thời gian mạ càng ngắn thì lớp bạc càng dày."], a: [true, false, true, false],
        x: "a) Đúng: vật cần mạ đóng vai trò cathode, nối với cực âm; ion Ag⁺ bị khử thành bạc bám lên thìa: Ag⁺ + e → Ag. b) Sai: anode bằng bạc tan dần: Ag → Ag⁺ + e. c) Đúng: lượng Ag⁺ do anode tan ra bằng lượng Ag⁺ bị khử ở cathode. d) Sai: dòng điện càng mạnh và mạ càng lâu thì lớp bạc càng dày; mạ trong thời gian ngắn hơn thì lớp bạc mỏng hơn.", lv: 2 },
      { topic: "Điện phân", type: "mc", q: "Điện phân với điện cực trơ một dung dịch chứa đồng thời AgNO₃ và Cu(NO₃)₂ cho đến khi ở cathode bắt đầu có khí thoát ra. Thứ tự các chất sinh ra ở cathode là", o: ["Ag, rồi đến Cu, sau cùng là khí H₂", "Cu, rồi đến Ag, sau cùng là khí H₂", "Cu và Ag sinh ra cùng lúc, sau cùng là khí H₂", "khí H₂, rồi đến Cu, sau cùng là Ag"],
        x: "Chất oxi hoá mạnh nhất có mặt trong dung dịch nhận electron ở cathode trước. Theo thứ tự Ag⁺ > Cu²⁺ > H₂O, ion Ag⁺ bị khử trước (Ag⁺ + e → Ag), hết Ag⁺ mới đến Cu²⁺ (Cu²⁺ + 2e → Cu), hết Cu²⁺ thì nước bị khử (2H₂O + 2e → H₂ + 2OH⁻).", lv: 2 },
      { topic: "Điện phân", type: "num", q: "Ở nhà máy, người ta điện phân Al₂O₃ nóng chảy (trộn với cryolite) để sản xuất nhôm theo phương trình 2Al₂O₃ → 4Al + 3O₂. Điện phân 10,2 tấn Al₂O₃ với hiệu suất 90% thì thu được bao nhiêu tấn nhôm? (Cho O = 16, Al = 27.)", ans: 4.86, unit: "tấn",
        x: "n(Al₂O₃) = 10,2 · 10⁶/102 = 10⁵ (mol). Theo phương trình, n(Al) = 2 · n(Al₂O₃) = 2 · 10⁵ mol, khối lượng nhôm theo lí thuyết là 2 · 10⁵ · 27 = 5,4 · 10⁶ (g) = 5,4 tấn. Với hiệu suất 90%: m = 5,4 · 0,9 = 4,86 (tấn).", lv: 3 },
      { topic: "Cấu tạo và liên kết trong tinh thể kim loại", type: "mc", q: "Trong tinh thể kim loại, các phần tử nằm ở các nút mạng tinh thể là", o: ["các ion dương kim loại", "các electron hoá trị của kim loại", "các ion âm của nguyên tố phi kim", "các nguyên tử phi kim trung hoà"],
        x: "Mạng tinh thể kim loại gồm các ion dương ở nút mạng; các electron hoá trị không thuộc riêng nguyên tử nào mà chuyển động khắp mạng tinh thể.", lv: 1 },
      { topic: "Cấu tạo và liên kết trong tinh thể kim loại", type: "mc", q: "So với nguyên tử của nguyên tố phi kim thuộc cùng một chu kì, nguyên tử của nguyên tố kim loại thường có", o: ["bán kính lớn hơn và độ âm điện nhỏ hơn", "bán kính nhỏ hơn và độ âm điện lớn hơn", "bán kính lớn hơn và độ âm điện lớn hơn", "điện tích hạt nhân lớn hơn và dễ nhận electron hơn"],
        x: "Đi từ đầu đến cuối một chu kì, điện tích hạt nhân tăng và bán kính nguyên tử giảm. Kim loại đứng ở đầu chu kì nên bán kính lớn hơn, hút electron hoá trị yếu hơn; độ âm điện của kim loại nhỏ hơn của phi kim cùng chu kì.", lv: 2 },
      { topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "mc", q: "Các kim loại có vẻ sáng lấp lánh (ánh kim) là do", o: ["các electron tự do trong kim loại phản xạ hầu hết ánh sáng", "các nguyên tử kim loại tự phát ra ánh sáng ở nhiệt độ thường", "bề mặt kim loại luôn được phủ một lớp oxide trong suốt", "các electron tự do hấp thụ hết ánh sáng chiếu tới"],
        x: "Ánh sáng chiếu tới bị các electron tự do của kim loại phản xạ gần như hoàn toàn, nên bề mặt kim loại sáng lấp lánh. Nhiều đồ vật kim loại để lâu bị phủ lớp oxide nên không còn thấy ánh kim.", lv: 1 },
      { topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "mc", q: "Trong các kim loại sau, kim loại dẫn điện tốt nhất là", o: ["bạc (Ag)", "đồng (Cu)", "thiếc (Sn)", "nhôm (Al)"],
        x: "Bạc dẫn điện tốt nhất, tiếp theo là đồng, vàng, nhôm. Dây dẫn điện thường làm bằng đồng hoặc nhôm vì rẻ hơn bạc nhiều (nhôm còn nhẹ).", lv: 1 },
      { topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "tf4", q: "Cho thế điện cực chuẩn: E°(K⁺/K) = −2,924 V; E°(Zn²⁺/Zn) = −0,762 V; E°(Cu²⁺/Cu) = +0,340 V; E°(Ag⁺/Ag) = +0,799 V. Ở pH = 7, thế điện cực của cặp 2H₂O/(H₂ + 2OH⁻) là −0,414 V. Mỗi ý sau đúng hay sai?",
        o: ["Potassium tác dụng mạnh với nước ở điều kiện thường, tạo ra khí hydrogen.", "Kẽm tan trong dung dịch HCl, tạo ra khí hydrogen.", "Bạc tan trong dung dịch H₂SO₄ loãng, tạo ra khí hydrogen.", "Cả bốn kim loại K, Zn, Cu, Ag đều tan trong dung dịch HCl."], a: [true, true, false, false],
        x: "a) Đúng: E°(K⁺/K) = −2,924 V nhỏ hơn −0,414 V nên potassium khử được nước, giải phóng H₂. b) Đúng: E°(Zn²⁺/Zn) < 0 nên kẽm khử được ion H⁺: Zn + 2HCl → ZnCl₂ + H₂. c) Sai: E°(Ag⁺/Ag) > 0, bạc không khử được ion H⁺ của acid loãng. d) Sai: Cu và Ag có thế điện cực chuẩn dương nên không phản ứng với dung dịch HCl.", lv: 2 },
      { topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "mc", q: "Khi nhiệt kế thuỷ ngân bị vỡ, người ta thường rắc bột lưu huỳnh lên chỗ thuỷ ngân rơi vãi rồi mới thu gom. Làm như vậy vì", o: ["lưu huỳnh tác dụng với thuỷ ngân ngay ở nhiệt độ thường tạo HgS", "lưu huỳnh hút ẩm làm các giọt thuỷ ngân khô lại và đông cứng", "lưu huỳnh xúc tác làm thuỷ ngân bay hơi hết, không còn gì để thu gom", "lưu huỳnh chỉ phản ứng với thuỷ ngân khi đun nóng ở nhiệt độ cao"],
        x: "Thuỷ ngân là kim loại lỏng, dễ bay hơi và hơi thuỷ ngân rất độc. Khác với nhiều kim loại chỉ phản ứng với lưu huỳnh khi đun nóng, thuỷ ngân phản ứng với lưu huỳnh ngay ở nhiệt độ thường: Hg + S → HgS, tạo chất rắn dễ thu gom, hạn chế hơi thuỷ ngân.", lv: 2 },
      { topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "num", q: "Hỗn hợp X gồm Fe và Cu có khối lượng 17,6 g. Cho X vào dung dịch H₂SO₄ loãng, dư thì thu được 4,958 L khí H₂. Nếu cho cùng lượng X đó tác dụng hết với dung dịch H₂SO₄ đặc, nóng, dư thì thu được bao nhiêu lít khí SO₂ (sản phẩm khử duy nhất)? Thể tích các khí đo ở điều kiện chuẩn (thể tích mol khí 24,79 L/mol). Làm tròn kết quả đến chữ số thập phân thứ hai. (Cho Fe = 56, Cu = 64.)", ans: 9.92, tol: 0.005, unit: "L",
        x: "Với H₂SO₄ loãng chỉ Fe phản ứng: Fe + H₂SO₄ → FeSO₄ + H₂; n(Fe) = n(H₂) = 4,958/24,79 = 0,2 (mol), m(Fe) = 11,2 g, nên m(Cu) = 6,4 g, n(Cu) = 0,1 mol. Với H₂SO₄ đặc, nóng, dư: 2Fe + 6H₂SO₄ → Fe₂(SO₄)₃ + 3SO₂ + 6H₂O và Cu + 2H₂SO₄ → CuSO₄ + SO₂ + 2H₂O. n(SO₂) = 1,5 · 0,2 + 0,1 = 0,4 (mol); V = 0,4 · 24,79 ≈ 9,92 (L).", lv: 3 },
      { topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "num", q: "Cho 2,4 g bột Mg vào 100 mL dung dịch chứa CuSO₄ 0,3 M và FeSO₄ 0,4 M. Khi các phản ứng kết thúc, chất rắn thu được nặng bao nhiêu gam? (Cho Mg = 24, Fe = 56, Cu = 64.)", ans: 4.88, unit: "g",
        x: "n(Mg) = 0,1 mol; n(Cu²⁺) = 0,03 mol; n(Fe²⁺) = 0,04 mol. Ion Cu²⁺ có tính oxi hoá mạnh hơn Fe²⁺ nên phản ứng trước: Mg + Cu²⁺ → Mg²⁺ + Cu, dùng hết 0,03 mol Mg. Còn 0,07 mol Mg khử hết 0,04 mol Fe²⁺: Mg + Fe²⁺ → Mg²⁺ + Fe; dư 0,03 mol Mg. Chất rắn gồm 0,03 mol Cu, 0,04 mol Fe và 0,03 mol Mg: m = 1,92 + 2,24 + 0,72 = 4,88 (g).", lv: 3 },
      { topic: "Kim loại trong tự nhiên và phương pháp tách kim loại", type: "mc", q: "Kim loại nào sau đây thường gặp trong tự nhiên ở dạng đơn chất?", o: ["Vàng (Au)", "Nhôm (Al)", "Sắt (Fe)", "Kẽm (Zn)"],
        x: "Vàng, bạc, platinum là những kim loại kém hoạt động nên có thể gặp ở dạng đơn chất trong tự nhiên (như vàng cốm, vàng sa khoáng). Nhôm, sắt, kẽm hoạt động hoá học mạnh hơn nên được khai thác từ quặng.", lv: 1 },
      { topic: "Kim loại trong tự nhiên và phương pháp tách kim loại", type: "mc", q: "Nguyên tắc chung của các phương pháp tách kim loại từ hợp chất của chúng là", o: ["khử ion kim loại thành nguyên tử kim loại", "oxi hoá ion kim loại thành nguyên tử kim loại", "oxi hoá nguyên tử kim loại thành ion kim loại", "hoà tan kim loại vào dung dịch acid"],
        x: "Trong hợp chất, kim loại tồn tại ở dạng ion dương Mⁿ⁺; muốn thu được kim loại phải khử ion đó, tức là ion Mⁿ⁺ nhận n electron để trở thành nguyên tử M. Các phương pháp chỉ khác nhau ở chất khử hoặc cách khử.", lv: 1 },
      { topic: "Kim loại trong tự nhiên và phương pháp tách kim loại", type: "mc", q: "Ở nhiệt độ cao, khí CO khử được oxide của nhiều kim loại. Oxide nào sau đây KHÔNG bị CO khử thành kim loại?", o: ["MgO", "Fe₂O₃", "CuO", "ZnO"],
        x: "Nhiệt luyện (dùng C, CO khử oxide ở nhiệt độ cao) chỉ tách được những kim loại không quá mạnh như Zn, Fe, Cu. Magnesium hoạt động hoá học mạnh, CO không khử được MgO.", lv: 2 },
      { topic: "Kim loại trong tự nhiên và phương pháp tách kim loại", type: "essay", q: "Trình bày lời giải. Một cơ sở tái chế nấu chảy 600 kg vỏ lon nhôm để đúc thành thỏi. Trong vỏ lon, nhôm chiếm 95% khối lượng; sơn và nhựa chiếm phần còn lại, bị cháy hết khi nấu. Trong lúc nấu chảy, 3% lượng nhôm bị oxygen của không khí oxi hoá thành aluminium oxide. (Cho O = 16, Al = 27.) a) Viết phương trình hoá học của phản ứng oxi hoá nhôm. b) Tính khối lượng nhôm thu được. c) Khối lượng aluminium oxide tạo thành là bao nhiêu?",
        rubric: [{ c: "Viết đúng phương trình 4Al + 3O₂ → 2Al₂O₃", p: 0.5 }, { c: "Khối lượng nhôm trong vỏ lon 600 · 95% = 570 kg; nhôm bị oxi hoá 570 · 3% = 17,1 kg", p: 0.5 }, { c: "Khối lượng nhôm thu được 570 − 17,1 = 552,9 kg", p: 0.5 }, { c: "Khối lượng aluminium oxide 17,1 · 204/108 ≈ 32,3 kg", p: 0.5 }],
        x: "a) 4Al + 3O₂ → 2Al₂O₃. b) Nhôm trong vỏ lon: 600 · 0,95 = 570 (kg); nhôm bị oxi hoá: 570 · 0,03 = 17,1 (kg); nhôm thu được: 570 − 17,1 = 552,9 (kg). c) Theo phương trình, 4 mol Al (108 g) tạo 2 mol Al₂O₃ (204 g), nên 17,1 kg Al tạo 17,1 · 204/108 ≈ 32,3 (kg) Al₂O₃.\nĐáp số: b) 552,9 kg; c) ≈ 32,3 kg.", lv: 3 },
      { topic: "Hợp kim", type: "mc", q: "Gang là hợp kim của sắt chứa khoảng 2% – 5% carbon. So với sắt nguyên chất, gang", o: ["cứng hơn nhưng giòn hơn", "mềm hơn và dễ dát mỏng", "cứng hơn và dẻo hơn", "mềm hơn nhưng giòn hơn"],
        x: "Gang có hàm lượng carbon cao nên cứng hơn sắt nhưng giòn, dễ vỡ khi bị va đập mạnh; gang dùng làm nguyên liệu luyện thép, đúc nồi, chảo và các chi tiết máy.", lv: 1 },
      { topic: "Hợp kim", type: "num", q: "Một mẫu hợp kim nhôm – đồng nặng 3 g tác dụng với dung dịch HCl dư, thu được 3,7185 L khí H₂ (điều kiện chuẩn, thể tích mol khí 24,79 L/mol). Phần trăm khối lượng của đồng trong hợp kim bằng bao nhiêu? (Cho Al = 27, Cu = 64.)", ans: 10, unit: "%",
        x: "Chỉ nhôm phản ứng với HCl: 2Al + 6HCl → 2AlCl₃ + 3H₂. n(H₂) = 3,7185/24,79 = 0,15 (mol) nên n(Al) = 0,1 mol, m(Al) = 2,7 g. m(Cu) = 3 − 2,7 = 0,3 (g); %Cu = 0,3/3 · 100% = 10%.", lv: 3 },
      { topic: "Sự ăn mòn kim loại", type: "mc", q: "Tượng, chuông bằng đồng để lâu ngoài trời bị ăn mòn, tạo thành lớp gỉ. Lớp gỉ đồng thường có màu", o: ["xanh", "nâu đỏ", "đen bóng", "trắng bạc"],
        x: "Gỉ đồng thường có màu xanh, còn gỉ sắt có màu nâu đỏ.", lv: 1 },
      { topic: "Sự ăn mòn kim loại", type: "tf4", q: "Một ống gang (hợp kim của sắt với carbon) để lâu ngoài trời, trong không khí ẩm thì bị gỉ. Mỗi ý sau đúng hay sai?",
        o: ["Sắt đóng vai trò cathode, carbon đóng vai trò anode.", "Ống gang bị ăn mòn điện hoá.", "Ở cathode, oxygen hoà tan trong lớp nước trên bề mặt bị khử.", "Nếu ống gang thường xuyên tiếp xúc với nước biển thì bị ăn mòn nhanh hơn."], a: [false, true, true, true],
        x: "a) Sai: sắt hoạt động hơn carbon nên sắt là anode và bị oxi hoá: Fe → Fe²⁺ + 2e; carbon là cathode. b) Đúng: sắt và carbon tiếp xúc nhau, cùng tiếp xúc với lớp nước có hoà tan khí, tạo ra vô số pin điện rất nhỏ. c) Đúng: ở cathode, O₂ bị khử: O₂ + 2H₂O + 4e → 4OH⁻. d) Đúng: nước biển chứa nhiều muối, dẫn điện tốt hơn nên ăn mòn điện hoá xảy ra nhanh hơn.", lv: 2 },
      { topic: "Sự ăn mòn kim loại", type: "mc", q: "Một đường ống dẫn nước bằng thép chôn dưới đất ẩm được nối bằng dây dẫn với một thanh kim loại để chống ăn mòn theo phương pháp điện hoá. Cho thế điện cực chuẩn: E°(Mg²⁺/Mg) = −2,356 V; E°(Al³⁺/Al) = −1,676 V; E°(Zn²⁺/Zn) = −0,762 V; E°(Fe²⁺/Fe) = −0,44 V; E°(Cu²⁺/Cu) = +0,340 V. Thanh kim loại nào sau đây KHÔNG dùng được cho mục đích này?", o: ["Thanh đồng (Cu)", "Thanh kẽm (Zn)", "Thanh magnesium (Mg)", "Thanh nhôm (Al)"],
        x: "Theo phương pháp điện hoá, thanh kim loại nối với thép phải hoạt động hoá học mạnh hơn sắt (thế điện cực chuẩn nhỏ hơn −0,44 V) để nó bị ăn mòn thay cho sắt. Mg, Al, Zn thoả mãn; đồng có thế điện cực chuẩn lớn hơn của sắt, khi nối với thép thì sắt trở thành anode và bị ăn mòn nhanh hơn.", lv: 3 },
      { topic: "Nguyên tố nhóm IA", type: "mc", q: "Các nguyên tố nhóm IA có mặt trong tự nhiên ở dạng nào?", o: ["Chỉ ở dạng hợp chất, chủ yếu là muối", "Chủ yếu ở dạng đơn chất", "Ở dạng đơn chất và hợp chất với lượng như nhau", "Chỉ ở dạng đơn chất hoà tan trong nước biển"],
        x: "Kim loại nhóm IA có tính khử rất mạnh nên trong tự nhiên không gặp chúng ở dạng đơn chất; chúng có trong các muối như NaCl của nước biển, mỏ muối.", lv: 1 },
      { topic: "Nguyên tố nhóm IA", type: "mc", q: "Khi nấu canh, vài giọt nước canh mặn trào xuống ngọn lửa của bếp ga làm ngọn lửa ánh lên một màu đặc trưng. Màu đó là", o: ["màu vàng", "màu đỏ tía", "màu tím nhạt", "màu trắng"],
        x: "Nước canh mặn chứa muối ăn NaCl; ion Na⁺ làm ngọn lửa có màu vàng đặc trưng.", lv: 1 },
      { topic: "Nguyên tố nhóm IA", type: "mc", q: "Có thể dùng dao cắt dễ dàng một mẩu sodium. Nguyên nhân chính khiến các kim loại nhóm IA mềm là", o: ["liên kết kim loại trong tinh thể của chúng yếu", "chúng có khối lượng riêng lớn hơn các kim loại khác", "chúng có nhiệt độ nóng chảy rất cao", "nguyên tử của chúng có nhiều electron hoá trị"],
        x: "Kim loại nhóm IA có bán kính nguyên tử lớn, mạng tinh thể kém đặc khít nên liên kết kim loại trong tinh thể yếu; vì vậy chúng mềm, cắt được bằng dao.", lv: 2 },
      { topic: "Nguyên tố nhóm IA", type: "num", q: "Cho 4,6 g sodium vào 95,6 g nước, phản ứng xảy ra hoàn toàn. Nồng độ phần trăm của dung dịch NaOH thu được bằng bao nhiêu? (Cho H = 1, O = 16, Na = 23.)", ans: 8, unit: "%",
        x: "2Na + 2H₂O → 2NaOH + H₂. n(Na) = 0,2 mol nên n(NaOH) = 0,2 mol (8 g) và n(H₂) = 0,1 mol (0,2 g). Khối lượng dung dịch: 4,6 + 95,6 − 0,2 = 100 (g). C% = 8/100 · 100% = 8%.", lv: 3 }
    ]
  },
  "hoahoc12-gk2-de2": {
    note: "Sách Kết nối tri thức, Hoá học 12. Phạm vi giữa học kì II: Bài 16 Điện phân 4 câu; Chương 6 Đại cương về kim loại (Bài 18–23) 17 câu; Bài 24 Nguyên tố nhóm IA 4 câu. Trường đã kiểm tra Bài 16 ở cuối học kì I thì bỏ qua các câu Bài 16; trường mới học đến hết Chương 6 thì bỏ qua các câu Bài 24; trường đã học thêm Bài 25 (Nguyên tố nhóm IIA) thì phụ huynh đối chiếu với đề cương của trường. Một số câu cần máy tính cầm tay. Có lời giải từng câu.",
    questions: [
      { topic: "Điện phân", type: "mc", q: "Điện phân với điện cực trơ một dung dịch chứa đồng thời KCl, KBr và KI. Thứ tự các anion bị oxi hoá ở anode là", o: ["I⁻, rồi Br⁻, rồi Cl⁻", "Cl⁻, rồi Br⁻, rồi I⁻", "Br⁻, rồi I⁻, rồi Cl⁻", "Cl⁻, rồi I⁻, rồi Br⁻"],
        x: "Chất có tính khử mạnh nhất nhường electron ở anode trước. Tính khử của các anion giảm theo thứ tự I⁻ > Br⁻ > Cl⁻, nên I⁻ bị oxi hoá trước, rồi đến Br⁻, sau cùng là Cl⁻.", lv: 1 },
      { topic: "Điện phân", type: "tf4", q: "Điện phân dung dịch KBr với hai điện cực trơ, có màng ngăn. Mỗi ý sau đúng hay sai?",
        o: ["Ở anode thu được bromine.", "Ở cathode, ion K⁺ bị khử thành kim loại K.", "Dung dịch ở khu vực cathode sau điện phân có môi trường base.", "Phương trình điện phân là 2KBr + 2H₂O → 2KOH + H₂ + Br₂."], a: [true, false, true, true],
        x: "a) Đúng: Br⁻ có tính khử mạnh hơn H₂O: 2Br⁻ → Br₂ + 2e. b) Sai: ion K⁺ có tính oxi hoá rất yếu; ở cathode, H₂O bị khử: 2H₂O + 2e → H₂ + 2OH⁻. c) Đúng: ở cathode sinh ra ion OH⁻. d) Đúng: phương trình cân bằng cả nguyên tố và điện tích.", lv: 2 },
      { topic: "Điện phân", type: "mc", q: "Điểm khác nhau cơ bản giữa phản ứng hoá học xảy ra trong pin điện hoá và trong bình điện phân là", o: ["trong bình điện phân, phản ứng oxi hoá – khử vốn không tự diễn ra, phải nhờ điện năng", "trong pin điện hoá, phản ứng chỉ xảy ra khi pin được nối với một nguồn điện bên ngoài", "trong bình điện phân không có quá trình oxi hoá, chỉ có quá trình khử", "trong pin điện hoá, cathode luôn là cực âm"],
        x: "Pin điện hoá tạo ra điện năng từ một phản ứng oxi hoá – khử tự diễn ra; bình điện phân thì tiêu thụ điện năng để buộc một phản ứng oxi hoá – khử vốn không tự diễn ra phải xảy ra. Trong cả hai, anode là nơi xảy ra sự oxi hoá, cathode là nơi xảy ra sự khử.", lv: 2 },
      { topic: "Điện phân", type: "num", q: "Điện phân dung dịch Cu(NO₃)₂ với hai điện cực trơ đến khi khối lượng cathode tăng 9,6 g thì dừng (chưa có khí thoát ra ở cathode). Thể tích khí thoát ra ở anode (điều kiện chuẩn, thể tích mol khí 24,79 L/mol) bằng bao nhiêu lít? Làm tròn kết quả đến chữ số thập phân thứ hai. (Cho Cu = 64.)", ans: 1.86, tol: 0.005, unit: "L",
        x: "Cathode: Cu²⁺ + 2e → Cu; anode: 2H₂O → O₂ + 4H⁺ + 4e. Phương trình điện phân: 2Cu(NO₃)₂ + 2H₂O → 2Cu + O₂ + 4HNO₃. n(Cu) = 9,6/64 = 0,15 (mol) nên n(O₂) = 0,075 mol; V = 0,075 · 24,79 ≈ 1,86 (L).", lv: 3 },
      { topic: "Cấu tạo và liên kết trong tinh thể kim loại", type: "mc", q: "Nguyên tử của hầu hết các nguyên tố kim loại có số electron ở lớp ngoài cùng là", o: ["từ 1 đến 3", "từ 4 đến 6", "từ 5 đến 7", "đúng 8"],
        x: "Hầu hết nguyên tử kim loại có ít electron ở lớp ngoài cùng (1, 2 hoặc 3 electron) nên dễ nhường các electron này.", lv: 1 },
      { topic: "Cấu tạo và liên kết trong tinh thể kim loại", type: "mc", q: "Liên kết ion có điểm chung với liên kết kim loại là", o: ["đều hình thành nhờ sự hút tĩnh điện giữa các phần tử mang điện trái dấu", "đều hình thành nhờ các cặp electron dùng chung của hai nguyên tử cạnh nhau", "đều chỉ có trong hợp chất của kim loại với phi kim", "đều có các electron chuyển động tự do trong toàn tinh thể"],
        x: "Cả hai loại liên kết đều do sự hút tĩnh điện giữa các phần tử mang điện trái dấu. Khác nhau: trong liên kết ion, electron chuyển hẳn từ nguyên tử này sang nguyên tử kia, tạo các ion trái dấu; trong liên kết kim loại, electron hoá trị di chuyển tự do khắp tinh thể.", lv: 2 },
      { topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "mc", q: "Kim loại nào sau đây có nhiệt độ nóng chảy cao nhất?", o: ["Tungsten (W)", "Chromium (Cr)", "Thuỷ ngân (Hg)", "Platinum (Pt)"],
        x: "Tungsten (vonfram, W) nóng chảy ở khoảng 3 410 °C, cao nhất trong các kim loại; chromium là kim loại cứng nhất, còn thuỷ ngân ở thể lỏng trong điều kiện thường.", lv: 1 },
      { topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "mc", q: "Kim loại nào sau đây có khối lượng riêng nhỏ nhất?", o: ["Lithium (Li)", "Nhôm (Al)", "Sodium (Na)", "Magnesium (Mg)"],
        x: "Lithium là kim loại nhẹ nhất (khối lượng riêng khoảng 0,53 g/cm³). Những kim loại mà khối lượng riêng dưới 5 g/cm³ được gọi là kim loại nhẹ.", lv: 1 },
      { topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "tf4", q: "Mỗi ý sau về các tính chất vật lí của kim loại đúng hay sai?",
        o: ["Hầu hết phi kim cũng dẫn điện tốt như kim loại.", "Khi bị rèn, các lớp mạng tinh thể trượt lên nhau nhưng không tách rời nhau nhờ các electron tự do.", "Kim loại dẫn điện càng tốt thì thường dẫn nhiệt càng kém.", "Đốt nóng một đầu thanh kim loại, nhiệt được truyền đi nhờ các electron tự do va chạm với các hạt khác trong mạng tinh thể."], a: [false, true, false, true],
        x: "a) Sai: hầu hết phi kim không dẫn điện vì không có electron tự do. b) Đúng: đó là nguyên nhân của tính dẻo. c) Sai: các kim loại dẫn điện tốt thường cũng dẫn nhiệt tốt. d) Đúng: các electron tự do ở đầu nóng có động năng lớn, truyền năng lượng cho các hạt khác qua va chạm.", lv: 2 },
      { topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "mc", q: "Người ta có thể dùng thùng bằng sắt để chứa và chuyên chở dung dịch H₂SO₄ đặc, nguội vì", o: ["sắt bị thụ động hoá trong H₂SO₄ đặc, nguội", "sắt không phản ứng với bất kì dung dịch acid nào", "H₂SO₄ đặc không có tính oxi hoá", "sắt đứng sau hydrogen trong dãy thế điện cực chuẩn"],
        x: "Trong H₂SO₄ đặc, nguội, sắt (cũng như nhôm, chromium) bị thụ động hoá: bề mặt kim loại được phủ một lớp màng bảo vệ, kim loại không tan tiếp. Khi đun nóng, H₂SO₄ đặc lại oxi hoá được sắt.", lv: 2 },
      { topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "num", q: "Đốt cháy hết 6,5 g kim loại M (hoá trị II) trong khí chlorine dư, thu được 13,6 g muối chloride. Nguyên tử khối của M bằng bao nhiêu? (Cho Cl = 35,5.)", ans: 65,
        x: "M + Cl₂ → MCl₂. Khối lượng chlorine đã phản ứng: 13,6 − 6,5 = 7,1 (g), n(Cl₂) = 7,1/71 = 0,1 (mol) nên n(M) = 0,1 mol. Nguyên tử khối của M = 6,5/0,1 = 65 (M là kẽm).", lv: 3 },
      { topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "num", q: "Nung nóng hỗn hợp gồm 5,6 g bột sắt và 4,8 g bột lưu huỳnh trong bình kín không có không khí đến khi phản ứng xảy ra hoàn toàn. Khối lượng iron(II) sulfide (FeS) thu được bằng bao nhiêu gam? (Cho S = 32, Fe = 56.)", ans: 8.8, unit: "g",
        x: "Fe + S → FeS. n(Fe) = 0,1 mol, n(S) = 0,15 mol nên lưu huỳnh dư, sắt phản ứng hết. n(FeS) = n(Fe) = 0,1 mol, m(FeS) = 0,1 · 88 = 8,8 (g).", lv: 3 },
      { topic: "Kim loại trong tự nhiên và phương pháp tách kim loại", type: "mc", q: "Tái chế kim loại ngày càng cần thiết. Lí do nào sau đây đúng?", o: ["Trữ lượng quặng ngày càng cạn kiệt, còn nhu cầu dùng kim loại tăng", "Kim loại tái chế luôn rẻ hơn mọi vật liệu khác", "Kim loại chỉ dùng được một lần rồi mất hết tính chất", "Quặng kim loại trong tự nhiên ngày càng nhiều nhưng ngày càng khó khai thác"],
        x: "Trữ lượng các mỏ quặng ngày càng giảm trong khi nhu cầu dùng kim loại và lượng phế thải kim loại ngày càng tăng; tái chế vừa bảo đảm nguồn cung, vừa tiết kiệm năng lượng và giảm ô nhiễm. Sắt, nhôm, đồng tái chế được nhiều lần.", lv: 1 },
      { topic: "Kim loại trong tự nhiên và phương pháp tách kim loại", type: "mc", q: "Thành phần chính của quặng hematite là", o: ["Fe₂O₃", "Al₂O₃·2H₂O", "ZnS", "FeS₂"],
        x: "Quặng hematite chứa chủ yếu iron(III) oxide Fe₂O₃, là nguyên liệu để sản xuất gang. Quặng bauxite chứa Al₂O₃·2H₂O, zinc blende chứa ZnS, pyrite chứa FeS₂.", lv: 1 },
      { topic: "Kim loại trong tự nhiên và phương pháp tách kim loại", type: "mc", q: "Trong phương pháp thuỷ luyện, ion kim loại trong dung dịch được khử bằng một kim loại có tính khử mạnh hơn. Kim loại nào sau đây KHÔNG dùng được để thu hồi đồng từ dung dịch CuSO₄ theo cách này?", o: ["Bạc (Ag)", "Sắt (Fe)", "Kẽm (Zn)", "Nhôm (Al)"],
        x: "Kim loại dùng để khử ion Cu²⁺ phải có tính khử mạnh hơn đồng (thế điện cực chuẩn nhỏ hơn +0,340 V). Fe, Zn, Al thoả mãn; bạc có tính khử yếu hơn đồng (E°(Ag⁺/Ag) = +0,799 V) nên không khử được ion Cu²⁺.", lv: 2 },
      { topic: "Kim loại trong tự nhiên và phương pháp tách kim loại", type: "num", q: "Thiếc được tách từ quặng cassiterite bằng phương pháp nhiệt luyện theo phương trình SnO₂ + 2C → Sn + 2CO. Từ 1 tấn quặng chứa 75,5% SnO₂ (theo khối lượng), hiệu suất cả quá trình là 80%, thu được bao nhiêu kilôgam thiếc? (Cho O = 16, Sn = 119.)", ans: 476, unit: "kg",
        x: "Khối lượng SnO₂: 1 000 · 75,5% = 755 (kg); n(SnO₂) = 755 000/151 = 5 000 (mol). Theo phương trình n(Sn) = n(SnO₂) = 5 000 mol, khối lượng thiếc theo lí thuyết là 5 000 · 119 = 595 000 (g) = 595 kg. Với hiệu suất 80%: m = 595 · 0,8 = 476 (kg).", lv: 3 },
      { topic: "Hợp kim", type: "mc", q: "So với đồng nguyên chất, hợp kim của đồng thường", o: ["dẫn điện kém hơn", "dẫn điện tốt hơn", "mềm hơn và dẻo hơn", "không còn ánh kim"],
        x: "Thường thì độ dẫn điện, dẫn nhiệt của hợp kim kém hơn kim loại chính trong hợp kim; vì vậy dây dẫn điện làm bằng đồng tinh khiết chứ không dùng hợp kim đồng.", lv: 1 },
      { topic: "Hợp kim", type: "num", q: "Luyện 10 tấn gang (coi chỉ gồm sắt và 4% carbon về khối lượng) thành thép chứa 0,8% carbon bằng cách đốt cháy bớt carbon; lượng sắt không đổi. Khối lượng thép thu được bằng bao nhiêu tấn? Làm tròn kết quả đến chữ số thập phân thứ hai.", ans: 9.68, tol: 0.005, unit: "tấn",
        x: "Khối lượng sắt: 10 · 96% = 9,6 (tấn), không đổi. Trong thép, sắt chiếm 100% − 0,8% = 99,2% nên khối lượng thép là 9,6/0,992 ≈ 9,68 (tấn).", lv: 3 },
      { topic: "Sự ăn mòn kim loại", type: "mc", q: "Trường hợp nào sau đây kim loại bị ăn mòn hoá học?", o: ["Ghi lò bằng thép bị oxygen oxi hoá ở nhiệt độ cao", "Đinh sắt quấn dây đồng ngâm trong nước muối", "Tấm tôn bị xước sâu tới lớp thép, để ngoài mưa", "Lá kẽm và lá đồng nối với nhau, nhúng vào dung dịch muối"],
        x: "Ăn mòn hoá học là do kim loại phản ứng oxi hoá – khử trực tiếp với chất oxi hoá trong môi trường, không tạo thành pin điện; thường gặp ở các thiết bị tiếp xúc với khí nóng như ghi lò. Ba trường hợp còn lại là ăn mòn điện hoá.", lv: 1 },
      { topic: "Sự ăn mòn kim loại", type: "tf4", q: "Khung xe đạp bằng thép được sơn kín. Sau một lần va chạm, lớp sơn ở một chỗ bị bong, để lộ thép. Mỗi ý sau đúng hay sai?",
        o: ["Chỗ bong sơn không bị gỉ vì thép là hợp kim.", "Lớp sơn còn nguyên ngăn thép tiếp xúc với không khí ẩm nên bảo vệ được phần thép bên dưới.", "Tra dầu mỡ lên xích xe là một cách phủ bề mặt để chống gỉ.", "Phần thép đã bị gỉ ở chỗ bong sơn vẫn giữ nguyên độ bền như thép chưa gỉ."], a: [false, true, true, false],
        x: "a) Sai: thép (hợp kim của sắt) vẫn bị ăn mòn khi tiếp xúc với không khí ẩm. b) Đúng: lớp sơn ngăn thép tiếp xúc với không khí ẩm. c) Đúng: dầu mỡ cũng là lớp phủ ngăn kim loại tiếp xúc với không khí ẩm. d) Sai: gỉ sắt xốp, bong ra dần làm thép mỏng và yếu đi.", lv: 2 },
      { topic: "Sự ăn mòn kim loại", type: "num", q: "Một thanh sắt nặng 1,12 kg bị gỉ hoàn toàn sau thời gian dài ở nơi ẩm ướt. Coi gỉ sắt có công thức Fe₂O₃·H₂O. Khối lượng gỉ sắt tạo thành bằng bao nhiêu kilôgam? (Cho H = 1, O = 16, Fe = 56.)", ans: 1.78, unit: "kg",
        x: "n(Fe) = 1 120/56 = 20 (mol). Bảo toàn nguyên tố sắt: 2 mol Fe tạo 1 mol Fe₂O₃·H₂O, nên n(gỉ sắt) = 10 mol. Khối lượng mol của Fe₂O₃·H₂O là 2 · 56 + 3 · 16 + 18 = 178 (g/mol); m = 10 · 178 = 1 780 (g) = 1,78 kg.", lv: 3 },
      { topic: "Nguyên tố nhóm IA", type: "mc", q: "Nguyên tử các kim loại nhóm IA có cấu hình electron lớp ngoài cùng dạng", o: ["ns¹", "ns²", "ns²np¹", "ns²np⁵"],
        x: "Nguyên tố nhóm IA là nguyên tố s: lớp ngoài cùng của nguyên tử chỉ có một electron, nằm ở phân lớp ns. Nguyên tử dễ nhường electron này nên có số oxi hoá +1 trong hợp chất.", lv: 1 },
      { topic: "Nguyên tố nhóm IA", type: "mc", q: "Trong phòng thí nghiệm, kim loại sodium và potassium thường được bảo quản bằng cách", o: ["ngâm chìm trong dầu hoả khan", "ngâm trong nước cất", "ngâm trong ethanol", "để trong lọ thuỷ tinh hở"],
        x: "Dầu hoả khan không phản ứng với sodium, potassium và ngăn chúng tiếp xúc với hơi nước, oxygen trong không khí; nước cất, ethanol đều phản ứng với hai kim loại này.", lv: 1 },
      { topic: "Nguyên tố nhóm IA", type: "mc", q: "Trong công nghiệp, khi điện phân dung dịch NaCl bão hoà để sản xuất NaOH và khí Cl₂, giữa hai điện cực phải có màng ngăn xốp. Màng ngăn có tác dụng", o: ["ngăn không cho khí Cl₂ sinh ra ở anode tác dụng với NaOH ở khu vực cathode", "giữ cho dung dịch NaCl không bị bay hơi và không bị bắn ra ngoài khi điện phân", "làm tăng nhiệt độ của dung dịch để phản ứng xảy ra nhanh hơn", "ngăn không cho ion Na⁺ đi về phía cathode"],
        x: "Ở anode sinh ra khí Cl₂, ở cathode sinh ra H₂ và NaOH. Nếu không có màng ngăn, Cl₂ tác dụng với NaOH tạo nước Javel (chứa NaClO); có màng ngăn mới thu được riêng NaOH và Cl₂.", lv: 2 },
      { topic: "Nguyên tố nhóm IA", type: "essay", q: "Trình bày lời giải. Trong quá trình Solvay, sục khí ammonia và carbon dioxide vào dung dịch NaCl bão hoà để tạo NaHCO₃ ít tan, lọc lấy NaHCO₃ rồi nung để thu được soda (Na₂CO₃). Từ 1,17 tấn NaCl, hiệu suất giai đoạn tạo NaHCO₃ là 75%, giai đoạn nung NaHCO₃ đạt 100%. (Cho H = 1, C = 12, O = 16, Na = 23, Cl = 35,5.) a) Viết các phương trình hoá học của quá trình. b) Tính khối lượng soda thu được. c) Tính thể tích khí CO₂ (điều kiện chuẩn, thể tích mol khí 24,79 L/mol) sinh ra ở giai đoạn nung, có thể đưa trở lại quy trình.",
        rubric: [{ c: "Viết đúng hai phương trình: NaCl + NH₃ + CO₂ + H₂O → NaHCO₃ + NH₄Cl; 2NaHCO₃ → Na₂CO₃ + CO₂ + H₂O", p: 0.5 }, { c: "Tính được n(NaCl) = 20 000 mol và lượng NaHCO₃ thu được 20 000 · 75% = 15 000 mol", p: 0.5 }, { c: "Tính được n(Na₂CO₃) = 7 500 mol, khối lượng soda 795 kg", p: 0.5 }, { c: "Tính được n(CO₂) = 7 500 mol, thể tích 185 925 L ≈ 185,9 m³", p: 0.5 }],
        x: "a) NaCl + NH₃ + CO₂ + H₂O → NaHCO₃ + NH₄Cl; 2NaHCO₃ → Na₂CO₃ + CO₂ + H₂O. b) n(NaCl) = 1 170 000/58,5 = 20 000 (mol); n(NaHCO₃) = 20 000 · 75% = 15 000 (mol); n(Na₂CO₃) = 15 000/2 = 7 500 (mol); m = 7 500 · 106 = 795 000 (g) = 795 kg. c) n(CO₂) = n(Na₂CO₃) = 7 500 mol; V = 7 500 · 24,79 = 185 925 (L) ≈ 185,9 m³.\nĐáp số: b) 795 kg; c) ≈ 185,9 m³.", lv: 3 }
    ]
  },
  /* ---------- Hoá học 12 · Kiểm tra cuối năm học (Kết nối tri thức, Hoá học 12, Chương 6–8, Bài 18–30; Phiên N12-ck2-vatli-hoahoc) ----------
     Phạm vi theo ma trận cuối học kì II, khung kế hoạch dạy học tra được (nguồn ghi ở Pull Request của phiên): Chương 6 Đại cương về kim loại
     và Bài 24 (ôn, chữ chủ đề như kho giữa kì II), Bài 25 Nguyên tố nhóm IIA, Chương 8 Sơ lược về dãy kim loại chuyển tiếp thứ nhất và phức
     chất (Bài 27–29), trọng tâm Chương 8 (12/25 câu); Bài 23, 26, 30 ôn tập không ra chủ đề riêng. Câu ôn không trùng đề bài, đáp án câu
     cùng chủ đề của kho giữa kì II. Hai đề cố định 25 câu chia đúng ma trận 10 Biết, 8 Hiểu, 7 Vận dụng trên 10 chủ đề theo tên bài của
     sách (ma trận ở data/banks/index.js). Hai đề là kho của đề ngẫu nhiên "hoahoc12-ck2-ngau-nhien" (không có câu riêng nên không ghi vào
     file này), nên ô (chủ đề, mức) nào cũng có đúng gấp đôi số câu ô đó rút. Dạng câu theo khung Công văn 7991: nhiều lựa chọn, đúng/sai
     4 ý (mỗi đề 3 câu, kiểu Đ/S không lặp), trả lời ngắn bằng số, mỗi đề 1 câu tự luận tự chấm ở hai ô Vận dụng khác nhau (Đại cương về kim
     loại chuyển tiếp dãy thứ nhất; Sơ lược về phức chất), nên mỗi lần rút nhiều nhất 2 câu tự luận. tests/vatli-hoahoc12-ck2.js tính lại
     mọi câu có số, cấu hình electron, số oxi hoá, điện tích của phức chất và kiểm tra mọi phương trình hoá học cân bằng (cả phương trình
     tạo phức, phản ứng chuẩn độ). Câu tự soạn, đối chiếu với sách in năm 2026; không dùng bối cảnh, số liệu của ví dụ, bài tập, thí
     nghiệm trong sách (chuẩn độ 5 mL FeSO₄ bằng KMnO₄ 0,02 M, các phức chất của ví dụ, phản ứng [PtCl₄]²⁻ + 2NH₃). Sách dùng “số lượng
     phối tử”, không dùng “số phối trí”. Cách xếp mức như kho cuối kì I. */
  "hoahoc12-ck2-de1": {
    note: "Sách Kết nối tri thức, Hoá học 12. Phạm vi cuối năm học: Chương 6–8 (Bài 18–30), trọng tâm Chương 8. Chương 6 Đại cương về kim loại (Bài 18–22) và Bài 24 Nguyên tố nhóm IA (ôn) 8 câu; Bài 25 Nguyên tố nhóm IIA 5 câu; Chương 8 Sơ lược về dãy kim loại chuyển tiếp thứ nhất và phức chất (Bài 27–29) 12 câu. Trường kiểm tra cả Bài 15–16 (pin điện, điện phân) thì ôn thêm các đề giữa kì II và phụ huynh đối chiếu với đề cương của trường. Một số câu cần máy tính cầm tay. Có lời giải từng câu. Từ năm học 2026–2027 Sở GD&ĐT ra đề chung cuối kì một số môn lớp 12; xem thông báo của Sở về môn và cấu trúc đề.",
    questions: [
      { topic: "Cấu tạo và liên kết trong tinh thể kim loại", type: "mc", q: "Ở nhiệt độ phòng, đơn chất kim loại nào sau đây tồn tại ở thể lỏng?", o: ["Thuỷ ngân (Hg)", "Sodium (Na)", "Thiếc (Sn)", "Chì (Pb)"],
        x: "Trừ thuỷ ngân là chất lỏng, các kim loại khác đều là chất rắn có cấu tạo tinh thể ở nhiệt độ phòng.", lv: 1 },
      { topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "mc", q: "Kim loại nào sau đây dẻo nhất, có thể dát thành những lá rất mỏng để thếp lên bề mặt đồ thờ, tượng?", o: ["Vàng (Au)", "Nickel (Ni)", "Sắt (Fe)", "Manganese (Mn)"],
        x: "Vàng là kim loại dẻo nhất, dát được thành lá rất mỏng; bạc, nhôm, đồng, thiếc cũng dẻo, còn sắt, manganese, nickel kém dẻo hơn vàng nhiều.", lv: 1 },
      { topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "mc", q: "Nung đỏ một đoạn dây sắt rồi cho vào bình chứa khí chlorine dư, dây sắt cháy sáng, sinh ra nhiều khói. Sản phẩm của phản ứng là", o: ["FeCl₃", "FeCl₂", "Fe₂O₃", "FeCl₂ và FeCl₃"],
        x: "Chlorine là chất oxi hoá mạnh, oxi hoá sắt lên số oxi hoá +3: 2Fe + 3Cl₂ → 2FeCl₃.", lv: 2 },
      { topic: "Kim loại trong tự nhiên và phương pháp tách kim loại", type: "mc", q: "Không thể điều chế sodium bằng cách cho kim loại potassium vào dung dịch NaCl. Nguyên nhân là", o: ["potassium tác dụng với nước có trong dung dịch", "potassium có tính khử yếu hơn sodium", "dung dịch NaCl có tính acid mạnh", "ion Cl⁻ trong dung dịch phản ứng với potassium trước"],
        x: "Potassium hoạt động hoá học rất mạnh: khi cho vào dung dịch, nó tác dụng ngay với nước, 2K + 2H₂O → 2KOH + H₂, nên không đẩy được sodium ra khỏi dung dịch NaCl.", lv: 2 },
      { topic: "Kim loại trong tự nhiên và phương pháp tách kim loại", type: "num", q: "Dùng khí H₂ dư khử hoàn toàn 24 g hỗn hợp CuO và Fe₂O₃ ở nhiệt độ cao, thu được 17,6 g hỗn hợp kim loại. Khối lượng CuO trong hỗn hợp ban đầu bằng bao nhiêu gam? (Cho H = 1, O = 16, Fe = 56, Cu = 64.)", ans: 8, unit: "g",
        x: "CuO + H₂ → Cu + H₂O; Fe₂O₃ + 3H₂ → 2Fe + 3H₂O. Khối lượng oxygen bị lấy đi: 24 − 17,6 = 6,4 (g), tức 0,4 mol O. Gọi x, y là số mol CuO, Fe₂O₃: 80x + 160y = 24 và x + 3y = 0,4, nên x = 0,1; y = 0,1. Khối lượng CuO: 0,1 · 80 = 8 (g).", lv: 3 },
      { topic: "Hợp kim", type: "mc", q: "Nhiều dụng cụ y tế và đồ dùng nhà bếp được làm bằng thép không gỉ. Lí do chính là so với sắt nguyên chất, thép không gỉ", o: ["chống ăn mòn tốt hơn nhiều", "nhẹ hơn nhiều, dễ mang theo", "dẫn điện tốt hơn nhiều", "mềm hơn, dễ uốn thành hình"],
        x: "Thép không gỉ có chứa chromium (ít nhất khoảng 10% khối lượng) nên chống ăn mòn tốt hơn sắt nguyên chất rất nhiều; vì vậy dụng cụ y tế, đồ dùng nhà bếp làm bằng thép không gỉ dùng được lâu mà không bị gỉ.", lv: 1 },
      { topic: "Sự ăn mòn kim loại", type: "mc", q: "Sắt tây là sắt được tráng một lớp thiếc mỏng. Một vỏ hộp bằng sắt tây bị xước sâu tới lớp sắt rồi để trong không khí ẩm. Nhận xét nào sau đây đúng?", o: ["Sắt bị ăn mòn nhanh, vì sắt hoạt động hoá học mạnh hơn thiếc", "Thiếc bị ăn mòn trước, vì thiếc hoạt động hoá học mạnh hơn sắt", "Không kim loại nào bị ăn mòn, vì thiếc đã che phủ sắt", "Thiếc và sắt bị ăn mòn chậm như nhau"],
        x: "Ở chỗ xước, sắt và thiếc tiếp xúc với nhau và cùng tiếp xúc với lớp nước ẩm, tạo thành pin điện. Sắt hoạt động hoá học mạnh hơn thiếc nên sắt là anode, bị ăn mòn điện hoá nhanh.", lv: 2 },
      { topic: "Nguyên tố nhóm IA", type: "mc", q: "Phần lớn hợp chất của kim loại nhóm IA như NaCl, KNO₃, Na₂SO₄", o: ["dễ tan, tạo dung dịch chất điện li mạnh", "tan trong nước nhưng không phân li ra ion", "chỉ tan được trong ethanol", "hầu như không tan trong nước"],
        x: "Phần lớn muối, hydroxide của kim loại kiềm tan tốt trong nước; khi tan chúng phân li hoàn toàn thành ion nên tạo dung dịch chất điện li mạnh.", lv: 1 },
      { topic: "Nguyên tố nhóm IIA", type: "mc", q: "Kim loại nhóm IIA nào sau đây KHÔNG phản ứng với nước, dù ở nhiệt độ thường hay khi đun nóng?", o: ["Beryllium (Be)", "Magnesium (Mg)", "Calcium (Ca)", "Barium (Ba)"],
        x: "Beryllium không tác dụng với nước; magnesium tác dụng chậm ở nhiệt độ thường và nhanh hơn khi đun nóng; calcium, barium tác dụng mạnh ngay ở nhiệt độ thường.", lv: 1 },
      { topic: "Nguyên tố nhóm IIA", type: "mc", q: "Một cách làm mềm nước là cho nước cứng đi qua cột nhựa cationite (nhựa trao đổi cation). Khi đó các ion Ca²⁺, Mg²⁺ ở lại trên cột, còn cột nhả vào nước các cation như", o: ["Na⁺ hoặc H⁺", "Ca²⁺ hoặc Ba²⁺", "Fe³⁺ hoặc Al³⁺", "Cu²⁺ hoặc Zn²⁺"],
        x: "Nhựa cationite giữ lại Ca²⁺, Mg²⁺ có trong nước và đổi lại bằng các cation Na⁺ hoặc H⁺ đi vào nước, nên nước sau khi qua cột trở thành nước mềm.", lv: 1 },
      { topic: "Nguyên tố nhóm IIA", type: "tf4", q: "Mỗi ý sau về các kim loại nhóm IIA từ magnesium đến barium đúng hay sai?",
        o: ["Trong hợp chất, các nguyên tố này có số oxi hoá đặc trưng là +2.", "Độ tan trong nước của các hydroxide giảm dần từ Mg(OH)₂ đến Ba(OH)₂.", "Mức độ phản ứng với nước tăng dần từ Mg đến Ba.", "Tính khử của các kim loại giảm dần từ Mg đến Ba."], a: [true, false, true, false],
        x: "a) Đúng: nguyên tử nhóm IIA có 2 electron hoá trị (ns²), dễ nhường để tạo ion M²⁺. b) Sai: độ tan của hydroxide tăng dần từ Mg(OH)₂ đến Ba(OH)₂. c) Đúng: hydroxide sinh ra càng dễ tan thì càng dễ rời khỏi bề mặt kim loại để kim loại tiếp tục phản ứng, nên mức độ phản ứng với nước tăng dần từ Mg đến Ba. d) Sai: từ Mg đến Ba bán kính nguyên tử tăng, kim loại dễ nhường electron hơn nên tính khử tăng dần.", lv: 2 },
      { topic: "Nguyên tố nhóm IIA", type: "num", q: "Một mẫu nước cứng chứa các ion Ca²⁺ (0,003 mol/L), Mg²⁺ (0,001 mol/L) cùng các anion Cl⁻, SO₄²⁻. Để làm mềm 25 L nước này bằng phương pháp kết tủa, người ta thêm dung dịch Na₂CO₃; coi các ion Ca²⁺, Mg²⁺ đều bị kết tủa hết dưới dạng muối carbonate. Khối lượng Na₂CO₃ tối thiểu cần dùng bằng bao nhiêu gam? (Cho C = 12, O = 16, Na = 23.)", ans: 10.6, unit: "g",
        x: "Số mol ion cần loại: (0,003 + 0,001) · 25 = 0,1 (mol). Ca²⁺ + CO₃²⁻ → CaCO₃; Mg²⁺ + CO₃²⁻ → MgCO₃, nên cần 0,1 mol Na₂CO₃: m = 0,1 · 106 = 10,6 (g).", lv: 3 },
      { topic: "Nguyên tố nhóm IIA", type: "num", q: "Hoà tan hết 18,4 g quặng dolomite (MgCO₃·CaCO₃, coi là tinh khiết) bằng dung dịch HCl dư. Biết ở điều kiện chuẩn, mỗi mol khí chiếm thể tích 24,79 L. Thể tích khí CO₂ thu được ở điều kiện chuẩn bằng bao nhiêu lít? Làm tròn kết quả đến chữ số thập phân thứ hai. (Cho C = 12, O = 16, Mg = 24, Ca = 40.)", ans: 4.96, tol: 0.005, unit: "L",
        x: "M(MgCO₃·CaCO₃) = 84 + 100 = 184 (g/mol), số mol dolomite: 18,4/184 = 0,1 (mol). MgCO₃ + 2HCl → MgCl₂ + CO₂ + H₂O; CaCO₃ + 2HCl → CaCl₂ + CO₂ + H₂O. Số mol CO₂: 2 · 0,1 = 0,2 (mol), thể tích V = 0,2 · 24,79 ≈ 4,96 (L).", lv: 3 },
      { topic: "Đại cương về kim loại chuyển tiếp dãy thứ nhất", type: "mc", q: "Các nguyên tố kim loại chuyển tiếp dãy thứ nhất thuộc chu kì 4, gồm các nguyên tố từ", o: ["Sc (Z = 21) đến Cu (Z = 29)", "K (Z = 19) đến Ca (Z = 20)", "Sc (Z = 21) đến Zn (Z = 30)", "Ti (Z = 22) đến Ga (Z = 31)"],
        x: "Dãy này có 9 nguyên tố ở chu kì 4, bắt đầu từ Sc (Z = 21) và kết thúc ở Cu (Z = 29); Zn (Z = 30) không thuộc dãy.", lv: 1 },
      { topic: "Đại cương về kim loại chuyển tiếp dãy thứ nhất", type: "mc", q: "Các số oxi hoá thường gặp của chromium (Cr) trong hợp chất là", o: ["+3 và +6", "+2, +4 và +7", "+2 và +3", "+1 và +2"],
        x: "Chromium có 6 electron hoá trị (3d⁵4s¹) nên có thể có nhiều số oxi hoá; trong hợp chất thường gặp nhất là +3 (như Cr₂O₃) và +6 (như CrO₃).", lv: 1 },
      { topic: "Đại cương về kim loại chuyển tiếp dãy thứ nhất", type: "mc", q: "Nguyên tử cobalt (Z = 27) có cấu hình electron [Ar]3d⁷4s². Cấu hình electron của ion Co²⁺ là", o: ["[Ar]3d⁷", "[Ar]3d⁵4s²", "[Ar]3d⁶4s¹", "[Ar]3d⁷4s²"],
        x: "Khi tạo ion, nguyên tử kim loại chuyển tiếp dãy thứ nhất mất electron 4s trước, sau đó mới mất electron 3d. Co nhường 2 electron 4s: Co → Co²⁺ + 2e, ion Co²⁺ có cấu hình [Ar]3d⁷.", lv: 2 },
      { topic: "Đại cương về kim loại chuyển tiếp dãy thứ nhất", type: "num", q: "Hợp chất V₂O₅ được dùng làm chất xúc tác trong công nghiệp. Số oxi hoá của vanadium trong V₂O₅ bằng bao nhiêu?", ans: 5,
        x: "Trong hợp chất, oxygen có số oxi hoá −2. Gọi số oxi hoá của V là x: 2x + 5 · (−2) = 0, nên x = +5.", lv: 2 },
      { topic: "Đại cương về kim loại chuyển tiếp dãy thứ nhất", type: "essay", q: "Trình bày lời giải. Để kiểm tra lượng sắt trong một loại viên uống bổ sung sắt (chứa FeSO₄), người ta hoà tan 5 viên vào nước có thêm dung dịch H₂SO₄ loãng, được 100 mL dung dịch X. Lấy 10,0 mL dung dịch X đem chuẩn độ bằng dung dịch KMnO₄ 0,01 M thì dùng vừa hết 12,0 mL. Phản ứng chuẩn độ: 10FeSO₄ + 2KMnO₄ + 8H₂SO₄ → 5Fe₂(SO₄)₃ + K₂SO₄ + 2MnSO₄ + 8H₂O. a) Trong phản ứng trên, chất nào là chất oxi hoá, chất nào là chất khử? b) Tính nồng độ mol của FeSO₄ trong dung dịch X. c) Tính khối lượng sắt có trong mỗi viên. (Cho Fe = 56.)",
        rubric: [{ c: "Chất oxi hoá là KMnO₄ (manganese nhận electron); chất khử là FeSO₄ (Fe²⁺ nhường electron thành Fe³⁺)", p: 0.5 }, { c: "n(KMnO₄) = 0,01 · 0,012 = 1,2 · 10⁻⁴ mol; n(FeSO₄) = 5 · 1,2 · 10⁻⁴ = 6,0 · 10⁻⁴ mol; nồng độ FeSO₄ = 6,0 · 10⁻⁴/0,010 = 0,06 M", p: 0.75 }, { c: "Số mol Fe trong 100 mL dung dịch X: 0,06 · 0,1 = 6,0 · 10⁻³ mol; mỗi viên chứa 1,2 · 10⁻³ mol Fe, tức 1,2 · 10⁻³ · 56 ≈ 0,0672 g = 67,2 mg", p: 0.75 }],
        x: "a) KMnO₄ là chất oxi hoá (manganese nhận electron), FeSO₄ là chất khử (Fe²⁺ nhường electron thành Fe³⁺). b) n(KMnO₄) = 0,01 · 0,012 = 1,2 · 10⁻⁴ (mol). Theo phương trình, n(FeSO₄) = 5 · n(KMnO₄) = 6,0 · 10⁻⁴ (mol) trong 10,0 mL, nên nồng độ FeSO₄ là 6,0 · 10⁻⁴/0,010 = 0,06 (M). c) 100 mL dung dịch X chứa 0,06 · 0,1 = 6,0 · 10⁻³ (mol) Fe của 5 viên; mỗi viên chứa 1,2 · 10⁻³ mol Fe, khối lượng 1,2 · 10⁻³ · 56 ≈ 0,0672 (g) = 67,2 mg.\nĐáp số: a) Chất oxi hoá KMnO₄, chất khử FeSO₄; b) 0,06 M; c) khoảng 67,2 mg.", lv: 3 },
      { topic: "Sơ lược về phức chất", type: "mc", q: "Trong phức chất, liên kết giữa nguyên tử trung tâm M và phối tử L được hình thành do", o: ["L cho cặp electron chưa liên kết vào orbital trống của M", "M cho cặp electron chưa liên kết vào orbital trống của L", "M và L cùng góp chung hai electron độc thân", "lực hút tĩnh điện giữa ion M và ion L"],
        x: "Đây là liên kết cho – nhận: mỗi phối tử L góp một cặp electron chưa liên kết vào một orbital trống của M.", lv: 1 },
      { topic: "Sơ lược về phức chất", type: "tf4", q: "Xét phức chất [Fe(CN)₆]³⁻, trong đó mỗi phối tử là một ion CN⁻. Mỗi ý sau đúng hay sai?",
        o: ["Nguyên tử trung tâm của phức chất là ion Fe³⁺.", "Phức chất có 6 phối tử nên thường có dạng hình học bát diện.", "Phức chất này không mang điện tích.", "Phức chất này có 3 phối tử CN⁻."], a: [true, true, false, false],
        x: "a) Đúng: gọi điện tích của nguyên tử trung tâm là x, ta có x + 6 · (−1) = −3, x = +3: ion Fe³⁺. b) Đúng: phức chất dạng [ML₆] thường có dạng hình học bát diện. c) Sai: phức chất mang điện tích −3. d) Sai: chỉ số 6 trong công thức cho biết phức chất có 6 phối tử CN⁻.", lv: 2 },
      { topic: "Sơ lược về phức chất", type: "num", q: "Phức chất [PtCl₄(NH₃)₂] không mang điện tích, trong đó mỗi phối tử Cl⁻ mang điện tích −1, phối tử NH₃ trung hoà điện. Số oxi hoá của nguyên tử trung tâm Pt trong phức chất này bằng bao nhiêu?", ans: 4,
        x: "Gọi số oxi hoá của Pt là x: x + 4 · (−1) + 2 · 0 = 0, nên x = +4. Nguyên tử trung tâm là ion Pt⁴⁺.", lv: 3 },
      { topic: "Một số tính chất và ứng dụng của phức chất", type: "mc", q: "Thuốc thử Tollens chứa phức chất [Ag(NH₃)₂]⁺, thường được dùng trong hoá học hữu cơ để", o: ["phân biệt aldehyde với ketone", "phân biệt alcohol với phenol", "nhận biết tinh bột", "nhận biết ion Cl⁻"],
        x: "Aldehyde khử được phức chất [Ag(NH₃)₂]⁺ của thuốc thử Tollens, tạo lớp bạc sáng; ketone không có phản ứng này. Nhờ đó thuốc thử Tollens giúp nhận ra aldehyde khi có lẫn ketone.", lv: 1 },
      { topic: "Một số tính chất và ứng dụng của phức chất", type: "tf4", q: "Nhỏ từ từ dung dịch NH₃ vào ống nghiệm chứa dung dịch Cu(NO₃)₂ loãng cho đến dư. Mỗi ý sau đúng hay sai?",
        o: ["Lúc đầu xuất hiện kết tủa màu xanh nhạt.", "Khi NH₃ dư, kết tủa tan và dung dịch có màu xanh lam.", "Màu xanh lam của dung dịch cuối cùng là do phức chất [Cu(NH₃)₄(H₂O)₂]²⁺.", "Trong phức chất tạo thành, nguyên tử trung tâm là ion Cu⁺."], a: [true, true, true, false],
        x: "a) Đúng: lúc đầu tạo kết tủa màu xanh nhạt. b) Đúng: NH₃ dư hoà tan kết tủa, dung dịch có màu xanh lam. c) Đúng: màu xanh lam là màu của phức chất [Cu(NH₃)₄(H₂O)₂]²⁺. d) Sai: phức chất mang điện tích +2, các phối tử NH₃, H₂O trung hoà điện nên nguyên tử trung tâm là ion Cu²⁺.", lv: 2 },
      { topic: "Một số tính chất và ứng dụng của phức chất", type: "num", q: "Hoà tan hết 2,87 g AgCl bằng dung dịch NH₃ theo phản ứng AgCl + 2NH₃ → [Ag(NH₃)₂]⁺ + Cl⁻. Thể tích dung dịch NH₃ 1 M tối thiểu cần dùng bằng bao nhiêu mililít? (Cho Cl = 35,5, Ag = 108.)", ans: 40, unit: "mL",
        x: "n(AgCl) = 2,87/143,5 = 0,02 (mol). Theo phương trình, n(NH₃) = 2 · 0,02 = 0,04 (mol), thể tích dung dịch NH₃ 1 M: 0,04 L = 40 mL.", lv: 3 },
      { topic: "Một số tính chất và ứng dụng của phức chất", type: "num", q: "Cho từ từ dung dịch NaOH 1 M vào 50 mL dung dịch ZnSO₄ 0,1 M. Lúc đầu xuất hiện kết tủa trắng Zn(OH)₂, sau đó kết tủa tan dần do tạo thành phức chất [Zn(OH)₄]²⁻ theo các phản ứng Zn²⁺ + 2OH⁻ → Zn(OH)₂ và Zn(OH)₂ + 2OH⁻ → [Zn(OH)₄]²⁻. Thể tích dung dịch NaOH tối thiểu để kết tủa vừa tan hết bằng bao nhiêu mililít?", ans: 20, unit: "mL",
        x: "n(Zn²⁺) = 0,05 · 0,1 = 0,005 (mol). Tạo kết tủa cần 2 · 0,005 = 0,01 (mol) OH⁻, hoà tan kết tủa cần thêm 0,01 mol OH⁻; tổng 0,02 mol NaOH, thể tích 0,02 L = 20 mL.", lv: 3 }
    ]
  },
  "hoahoc12-ck2-de2": {
    note: "Sách Kết nối tri thức, Hoá học 12. Phạm vi cuối năm học: Chương 6–8 (Bài 18–30), trọng tâm Chương 8. Chương 6 Đại cương về kim loại (Bài 18–22) và Bài 24 Nguyên tố nhóm IA (ôn) 8 câu; Bài 25 Nguyên tố nhóm IIA 5 câu; Chương 8 Sơ lược về dãy kim loại chuyển tiếp thứ nhất và phức chất (Bài 27–29) 12 câu. Trường kiểm tra cả Bài 15–16 (pin điện, điện phân) thì ôn thêm các đề giữa kì II và phụ huynh đối chiếu với đề cương của trường. Một số câu cần máy tính cầm tay. Có lời giải từng câu. Từ năm học 2026–2027 Sở GD&ĐT ra đề chung cuối kì một số môn lớp 12; xem thông báo của Sở về môn và cấu trúc đề.",
    questions: [
      { topic: "Cấu tạo và liên kết trong tinh thể kim loại", type: "mc", q: "Nguyên tử gallium (Z = 31) có 3 electron ở lớp ngoài cùng (4s²4p¹). Trong tinh thể gallium, mỗi nguyên tử đã nhường hết các electron lớp ngoài cùng. Ion tạo thành là", o: ["Ga³⁺", "Ga⁺", "Ga³⁻", "Ga⁵⁺"],
        x: "Nguyên tử kim loại dễ nhường các electron lớp ngoài cùng để tạo ion dương. Gallium nhường 3 electron lớp ngoài cùng: Ga → Ga³⁺ + 3e.", lv: 1 },
      { topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "mc", q: "Kim loại nặng nhất, tức là có khối lượng riêng lớn nhất, là kim loại nào sau đây?", o: ["Osmium (Os)", "Chì (Pb)", "Đồng (Cu)", "Sắt (Fe)"],
        x: "Osmium có khối lượng riêng khoảng 22,6 g/cm³, lớn nhất trong các kim loại; chì khoảng 11,3 g/cm³, đồng khoảng 9,0 g/cm³, sắt khoảng 7,9 g/cm³.", lv: 1 },
      { topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "mc", q: "Cho bột sắt vào dung dịch HCl dư, phản ứng xảy ra hoàn toàn. Muối sắt thu được là", o: ["FeCl₂", "FeCl₃", "FeCl₂ và FeCl₃", "Không có muối, vì sắt không tan"],
        x: "Fe + 2HCl → FeCl₂ + H₂. Ion H⁺ của dung dịch HCl chỉ oxi hoá sắt lên số oxi hoá +2.", lv: 2 },
      { topic: "Kim loại trong tự nhiên và phương pháp tách kim loại", type: "mc", q: "Nhôm được sản xuất trong công nghiệp bằng phương pháp điện phân nóng chảy Al₂O₃, chứ không điện phân dung dịch AlCl₃. Nguyên nhân là khi điện phân dung dịch AlCl₃ thì", o: ["ở cathode nước bị khử trước, không thu được nhôm", "AlCl₃ không tan trong nước nên không điện phân được", "dung dịch AlCl₃ không dẫn điện", "nhôm sinh ra bị khí chlorine oxi hoá ngay"],
        x: "Trong dung dịch, nước dễ bị khử hơn ion Al³⁺, nên ở cathode nước bị khử tạo khí H₂, không thu được nhôm. Vì vậy phải điện phân Al₂O₃ nóng chảy (không có nước).", lv: 2 },
      { topic: "Kim loại trong tự nhiên và phương pháp tách kim loại", type: "num", q: "Một xưởng mạ điện thu hồi đồng từ 500 L nước thải chứa CuSO₄ nồng độ 0,04 mol/L bằng cách cho sắt vụn dư vào. Coi phản ứng Fe + CuSO₄ → FeSO₄ + Cu xảy ra hoàn toàn. Khối lượng đồng thu được bằng bao nhiêu gam? (Cho Cu = 64.)", ans: 1280, unit: "g",
        x: "n(CuSO₄) = 500 · 0,04 = 20 (mol). Theo phương trình, n(Cu) = n(CuSO₄) = 20 mol, khối lượng đồng: 20 · 64 = 1 280 (g).", lv: 3 },
      { topic: "Hợp kim", type: "mc", q: "Duralumin nhẹ mà cứng, bền, nên được dùng nhiều để chế tạo thân và cánh máy bay. Kim loại cơ bản, chiếm trên 90% khối lượng của duralumin, là", o: ["nhôm (Al)", "sắt (Fe)", "đồng (Cu)", "magnesium (Mg)"],
        x: "Duralumin là hợp kim của nhôm (trên 90% khối lượng) có thêm khoảng 4% đồng cùng một ít manganese, magnesium, silicon.", lv: 1 },
      { topic: "Sự ăn mòn kim loại", type: "mc", q: "Cho một viên kẽm vào dung dịch HCl, khí H₂ thoát ra chậm. Nhỏ thêm vài giọt dung dịch CuSO₄ vào thì khí thoát ra nhanh hơn hẳn. Nguyên nhân là", o: ["Cu sinh ra bám vào Zn tạo pin điện, Zn bị ăn mòn điện hoá", "ion Cu²⁺ làm tăng nồng độ ion H⁺ trong dung dịch", "CuSO₄ tác dụng với HCl sinh ra thêm khí H₂", "kẽm bị ăn mòn hoá học nhanh hơn khi có thêm ion SO₄²⁻"],
        x: "Zn khử ion Cu²⁺: Zn + Cu²⁺ → Zn²⁺ + Cu. Đồng sinh ra bám vào viên kẽm; Zn và Cu tiếp xúc nhau trong dung dịch chất điện li, tạo thành pin điện, Zn là anode bị ăn mòn điện hoá nên khí H₂ thoát ra nhanh hơn.", lv: 2 },
      { topic: "Nguyên tố nhóm IA", type: "mc", q: "Khi hoà tan muối của kim loại nhóm IA vào nước, các ion như Na⁺, K⁺ trong dung dịch", o: ["đều không có màu", "đều có màu đỏ", "có màu khác nhau tuỳ theo kim loại", "đều có màu tím nhạt"],
        x: "Ion kim loại nhóm IA không có màu. Chỉ khi đưa hợp chất của chúng vào ngọn lửa đèn khí thì ngọn lửa mới có màu đặc trưng của từng kim loại.", lv: 1 },
      { topic: "Nguyên tố nhóm IIA", type: "mc", q: "Muối nào sau đây gần như không tan trong nước?", o: ["BaSO₄", "Ba(NO₃)₂", "MgSO₄", "CaCl₂"],
        x: "Theo bảng tính tan, BaSO₄ là chất không tan; Ba(NO₃)₂, MgSO₄, CaCl₂ đều là chất dễ tan.", lv: 1 },
      { topic: "Nguyên tố nhóm IIA", type: "mc", q: "Chất nào sau đây được dùng làm vật liệu xây dựng và làm phấn viết bảng?", o: ["Thạch cao", "Vôi sống", "Apatite", "Muối ăn"],
        x: "Thạch cao được dùng làm vật liệu xây dựng, phấn viết bảng. Vôi sống dùng để khử chua, sát trùng, hút ẩm; apatite dùng sản xuất phân lân.", lv: 1 },
      { topic: "Nguyên tố nhóm IIA", type: "tf4", q: "Mỗi ý sau về hợp chất của calcium, magnesium và barium đúng hay sai?",
        o: ["Khi nung, BaCO₃ bị phân huỷ ở nhiệt độ thấp hơn MgCO₃.", "CaCO₃ tác dụng với dung dịch acetic acid, giải phóng khí CO₂.", "Nung MgCO₃ đến khối lượng không đổi thu được MgO và khí CO₂.", "Đá vôi (thành phần chính là CaCO₃) là nguyên liệu để nung vôi sống, làm xi măng."], a: [false, true, true, true],
        x: "a) Sai: độ bền nhiệt của muối carbonate tăng dần từ Be đến Ba, nên MgCO₃ bị phân huỷ ở nhiệt độ thấp hơn BaCO₃. b) Đúng: CaCO₃ là muối của acid yếu, tác dụng với acetic acid: CaCO₃ + 2CH₃COOH → (CH₃COO)₂Ca + CO₂ + H₂O. c) Đúng: MgCO₃ → MgO + CO₂. d) Đúng: đá vôi là nguyên liệu để nung vôi, làm xi măng và làm đá xây dựng.", lv: 2 },
      { topic: "Nguyên tố nhóm IIA", type: "num", q: "Nhiệt phân hoàn toàn 26,1 g Ba(NO₃)₂ theo phản ứng 2Ba(NO₃)₂ → 2BaO + 4NO₂ + O₂. Khối lượng chất rắn BaO thu được bằng bao nhiêu gam? (Cho N = 14, O = 16, Ba = 137.)", ans: 15.3, unit: "g",
        x: "M(Ba(NO₃)₂) = 137 + 2 · 62 = 261 (g/mol), số mol: 26,1/261 = 0,1 (mol). Theo phương trình, n(BaO) = 0,1 mol, khối lượng 0,1 · 153 = 15,3 (g).", lv: 3 },
      { topic: "Nguyên tố nhóm IIA", type: "num", q: "Một mẫu nước chứa Ca(HCO₃)₂ nồng độ 0,002 mol/L. Đun sôi 50 L nước này đến khi phản ứng Ca(HCO₃)₂ → CaCO₃ + CO₂ + H₂O xảy ra hoàn toàn. Khối lượng kết tủa CaCO₃ thu được bằng bao nhiêu gam? (Cho H = 1, C = 12, O = 16, Ca = 40.)", ans: 10, unit: "g",
        x: "n(Ca(HCO₃)₂) = 0,002 · 50 = 0,1 (mol). Theo phương trình, n(CaCO₃) = 0,1 mol, khối lượng 0,1 · 100 = 10 (g).", lv: 3 },
      { topic: "Đại cương về kim loại chuyển tiếp dãy thứ nhất", type: "mc", q: "Cấu hình electron của nguyên tử chromium (Z = 24) là", o: ["[Ar]3d⁵4s¹", "[Ar]3d⁴4s²", "[Ar]3d⁶", "[Ar]3d⁵4s²"],
        x: "Theo bảng cấu hình electron của các kim loại chuyển tiếp dãy thứ nhất, chromium có cấu hình [Ar]3d⁵4s¹: phân lớp 4s chỉ có 1 electron, giống như copper ([Ar]3d¹⁰4s¹).", lv: 1 },
      { topic: "Đại cương về kim loại chuyển tiếp dãy thứ nhất", type: "mc", q: "Kim loại chuyển tiếp dãy thứ nhất nào sau đây tương đối nhẹ, thường dùng làm gọng kính và các chi tiết của máy bay?", o: ["Titanium (Ti)", "Đồng (Cu)", "Manganese (Mn)", "Cobalt (Co)"],
        x: "Titanium tương đối nhẹ, bền nên được dùng làm gọng kính, chi tiết máy bay (scandium cũng tương đối nhẹ). Các kim loại chuyển tiếp dãy thứ nhất khác đều là kim loại nặng.", lv: 1 },
      { topic: "Đại cương về kim loại chuyển tiếp dãy thứ nhất", type: "mc", q: "Nhỏ dung dịch KOH vào dung dịch Fe₂(SO₄)₃ thì xuất hiện kết tủa Fe(OH)₃. Kết tủa này có màu", o: ["nâu đỏ", "xanh lam", "trắng", "đen"],
        x: "Fe₂(SO₄)₃ + 6KOH → 2Fe(OH)₃ + 3K₂SO₄. Fe(OH)₃ là kết tủa màu nâu đỏ; nhờ màu này có thể nhận ra ion Fe³⁺ trong dung dịch.", lv: 2 },
      { topic: "Đại cương về kim loại chuyển tiếp dãy thứ nhất", type: "tf4", q: "So sánh manganese (Mn, kim loại chuyển tiếp dãy thứ nhất) với sodium (Na, kim loại nhóm IA). Mỗi ý sau đúng hay sai?",
        o: ["Nhiệt độ nóng chảy của Mn cao hơn nhiều so với của Na.", "Khối lượng riêng của Mn nhỏ hơn của Na.", "Trong hợp chất, Mn có thể có nhiều số oxi hoá, còn Na chỉ có số oxi hoá +1.", "Nguyên tử Mn có electron hoá trị ở cả phân lớp 4s và phân lớp 3d."], a: [true, false, true, true],
        x: "a) Đúng: kim loại chuyển tiếp dãy thứ nhất khó nóng chảy (Mn nóng chảy ở khoảng 1 244 °C), còn Na nóng chảy ở khoảng 98 °C. b) Sai: Mn là kim loại nặng (khoảng 7,2 g/cm³), Na rất nhẹ (khoảng 0,97 g/cm³). c) Đúng: Mn có nhiều electron hoá trị nên có nhiều số oxi hoá; Na chỉ có 1 electron hoá trị. d) Đúng: cấu hình electron của Mn là [Ar]3d⁵4s².", lv: 2 },
      { topic: "Đại cương về kim loại chuyển tiếp dãy thứ nhất", type: "num", q: "Dung dịch FeCl₃ được dùng để hoà tan lớp đồng trên bảng mạch điện tử theo phản ứng Cu + 2FeCl₃ → CuCl₂ + 2FeCl₂. Để hoà tan hết 3,2 g đồng cần tối thiểu bao nhiêu gam FeCl₃? (Cho Cl = 35,5, Fe = 56, Cu = 64.)", ans: 16.25, unit: "g",
        x: "n(Cu) = 3,2/64 = 0,05 (mol). Theo phương trình, n(FeCl₃) = 2 · 0,05 = 0,1 (mol), khối lượng 0,1 · 162,5 = 16,25 (g).", lv: 3 },
      { topic: "Sơ lược về phức chất", type: "mc", q: "Phức chất [Cr(CO)₆] không mang điện tích. Nguyên tử trung tâm và phối tử của phức chất này lần lượt là", o: ["nguyên tử Cr và phân tử CO", "ion Cr³⁺ và ion CO⁻", "nguyên tử C và nguyên tử O", "phân tử CO và nguyên tử Cr"],
        x: "Trong [Cr(CO)₆], nguyên tử trung tâm là nguyên tử kim loại Cr, 6 phối tử là các phân tử CO trung hoà điện, nên phức chất không mang điện tích.", lv: 1 },
      { topic: "Sơ lược về phức chất", type: "mc", q: "Muối CuSO₄ khan có màu trắng; khi hoà tan vào nước được dung dịch màu xanh. Màu xanh của dung dịch là do", o: ["trong dung dịch đã tạo thành phức chất aqua [Cu(H₂O)₆]²⁺", "ion SO₄²⁻ tạo với nước một phức chất màu xanh", "CuSO₄ bị nước phân huỷ thành CuO có màu xanh", "ion Cu²⁺ bị nước oxi hoá thành ion Cu³⁺ có màu xanh"],
        x: "Trong dung dịch, ion Cu²⁺ liên kết với các phân tử nước tạo phức chất aqua [Cu(H₂O)₆]²⁺ có màu xanh; CuSO₄ khan không có phức chất này nên có màu trắng.", lv: 2 },
      { topic: "Sơ lược về phức chất", type: "essay", q: "Trình bày lời giải. a) Ion Cr³⁺ liên kết với 6 phân tử NH₃ tạo thành phức chất X. Viết công thức của X và cho biết điện tích của X. b) Phức chất Y có công thức [Ni(CN)₄]²⁻, mỗi phối tử CN⁻ mang điện tích −1. Xác định số oxi hoá của nguyên tử trung tâm Ni và số lượng phối tử trong Y. c) Y có thể có những dạng hình học nào? d) Muối K₂[Ni(CN)₄] chứa ion phức chất Y. Tính phần trăm khối lượng của nickel trong muối này (làm tròn đến hàng phần mười). (Cho C = 12, N = 14, K = 39, Ni = 59.)",
        rubric: [{ c: "X là [Cr(NH₃)₆]³⁺, điện tích +3 vì các phối tử NH₃ trung hoà điện", p: 0.5 }, { c: "x + 4 · (−1) = −2 nên Ni có số oxi hoá +2; Y có 4 phối tử CN⁻", p: 0.5 }, { c: "Phức chất dạng [ML₄] có thể có dạng tứ diện hoặc vuông phẳng", p: 0.5 }, { c: "M(K₂[Ni(CN)₄]) = 2 · 39 + 59 + 4 · 26 = 241 g/mol; phần trăm khối lượng Ni = 59/241 · 100% ≈ 24,5%", p: 0.5 }],
        x: "a) X là [Cr(NH₃)₆]³⁺: nguyên tử trung tâm Cr³⁺, 6 phối tử NH₃ trung hoà điện nên X có điện tích +3. b) Gọi số oxi hoá của Ni là x: x + 4 · (−1) = −2, x = +2; Y có 4 phối tử CN⁻. c) Phức chất có 4 phối tử, dạng [ML₄], có thể có dạng tứ diện hoặc vuông phẳng. d) M(K₂[Ni(CN)₄]) = 2 · 39 + 59 + 4 · (12 + 14) = 241 (g/mol); phần trăm khối lượng Ni = 59/241 · 100% ≈ 24,5%.\nĐáp số: a) [Cr(NH₃)₆]³⁺, điện tích +3; b) Ni có số oxi hoá +2, 4 phối tử; c) tứ diện hoặc vuông phẳng; d) khoảng 24,5%.", lv: 3 },
      { topic: "Một số tính chất và ứng dụng của phức chất", type: "mc", q: "Cisplatin là một phức chất của platinum, có công thức [PtCl₂(NH₃)₂]. Trong y học, cisplatin được dùng làm thuốc điều trị bệnh", o: ["ung thư", "tiểu đường", "cảm cúm", "đau dạ dày"],
        x: "Một số phức chất được dùng làm thuốc; cisplatin là phức chất của platinum dùng trong điều trị ung thư.", lv: 1 },
      { topic: "Một số tính chất và ứng dụng của phức chất", type: "tf4", q: "Cho phản ứng [Ag(NH₃)₂]⁺ + 2CN⁻ → [Ag(CN)₂]⁻ + 2NH₃, xảy ra thuận lợi trong dung dịch. Mỗi ý sau đúng hay sai?",
        o: ["Đây là phản ứng thế phối tử của phức chất.", "Số lượng phối tử liên kết với ion Ag⁺ trước và sau phản ứng bằng nhau.", "Phức chất [Ag(CN)₂]⁻ mang điện tích +1.", "Phản ứng xảy ra thuận lợi vì phức chất [Ag(CN)₂]⁻ bền hơn phức chất [Ag(NH₃)₂]⁺."], a: [true, true, false, true],
        x: "a) Đúng: hai phối tử NH₃ trong phức chất ban đầu bị thay thế bởi hai phối tử CN⁻. b) Đúng: trước và sau phản ứng, ion Ag⁺ đều liên kết với 2 phối tử. c) Sai: Ag⁺ (+1) và hai phối tử CN⁻ (−1) cho điện tích +1 + 2 · (−1) = −1. d) Đúng: phối tử mới thay được phối tử cũ khi phức chất tạo thành bền hơn phức chất ban đầu.", lv: 2 },
      { topic: "Một số tính chất và ứng dụng của phức chất", type: "num", q: "Để chuyển hết 0,015 mol ion Cu²⁺ trong dung dịch thành phức chất theo phản ứng Cu²⁺ + 4NH₃ + 2H₂O → [Cu(NH₃)₄(H₂O)₂]²⁺, cần tối thiểu bao nhiêu mililít dung dịch NH₃ 2 M?", ans: 30, unit: "mL",
        x: "Theo phương trình, n(NH₃) = 4 · 0,015 = 0,06 (mol). Thể tích dung dịch NH₃ 2 M: 0,06/2 = 0,03 (L) = 30 mL.", lv: 3 },
      { topic: "Một số tính chất và ứng dụng của phức chất", type: "num", q: "Một liều thuốc tiêm chứa 30 mg cisplatin [PtCl₂(NH₃)₂]. Khối lượng platinum (Pt) có trong liều thuốc này bằng bao nhiêu miligam? (Cho H = 1, N = 14, Cl = 35,5, Pt = 195.)", ans: 19.5, unit: "mg",
        x: "M([PtCl₂(NH₃)₂]) = 195 + 2 · 35,5 + 2 · 17 = 300 (g/mol). Khối lượng Pt trong 30 mg cisplatin: 30 · 195/300 = 19,5 (mg).", lv: 3 }
    ]
  },
  /* ---------- Hoá học 12 · Thi thử tốt nghiệp THPT (đề tính điểm, Phiên N12-tn-hoahoc: Đề 1–4) ----------
     Khung đề tốt nghiệp THPT từ năm 2025 (Quyết định 764/QĐ-BGDĐT): 28 câu, 50 phút, 10 điểm; Phần I 18 câu nhiều lựa chọn (pt 0,25),
     Phần II 4 câu đúng/sai 4 ý (pt 1), Phần III 6 câu trả lời ngắn (pt 0,25; đáp án không quá 4 kí tự). Như đề tham khảo năm 2025 (đề
     chính thức năm 2026 giữ cấu trúc và tỉ lệ các mức; nguồn ghi ở Pull Request của phiên): mỗi đề 2 câu thuộc Hoá học 10 (một câu ở Phần
     I, một câu ở Phần III), 2 câu thuộc Hoá học 11 (Phần I), còn lại 24 câu thuộc Hoá học 12, đủ tám chương. Mức độ: Phần I 11 Biết, 5
     Hiểu, 2 Vận dụng; Phần II mỗi câu gồm ý từ Biết đến Vận dụng, bốn câu ghi mức 1, 2, 2, 3; Phần III 1 Biết, 3 Hiểu, 2 Vận dụng (Biết và
     Hiểu khoảng 80% số ý). Mỗi đề có ít nhất một câu Phần II về thí nghiệm (dụng cụ, cách làm, hiện tượng, giải thích); Phần I có nhiều
     nhất một cặp câu dùng chung một đoạn thông tin (passages). Câu lớp 12 mang đúng chữ chủ đề của ba kho Hoá học 12 (đề “Ôn chủ đề” rút
     chung câu của các kho đó); câu lớp 10, 11 ghi “Lớp 10 · ”, “Lớp 11 · ” và tên chương của sách. Câu tự soạn, không dùng bối cảnh,
     số liệu của ví dụ, bài tập, thí nghiệm trong sách; đáp án tính lại, phương trình hoá học kiểm tra cân bằng bằng tests/hoahoc12-tn.js. */
  "hoahoc12-tn-de1": {
    note: "Đề thi thử theo cấu trúc đề thi tốt nghiệp THPT từ năm 2025 (Quyết định 764/QĐ-BGDĐT). Năm 2027 thí điểm thi trên máy tính ở nơi đủ điều kiện, đề như thi giấy. Phạm vi: chương trình THPT, chủ yếu Hoá học 12 (sách Kết nối tri thức, cả năm học). Như đề tham khảo năm 2025 và đề chính thức năm 2026 (2 câu thuộc lớp 10, 2 câu thuộc lớp 11, còn lại thuộc lớp 12), đề có 24 câu Hoá học 12, 2 câu Hoá học 11 và 2 câu Hoá học 10. Đề có 28 câu, làm trong 50 phút: Phần I gồm 18 câu nhiều lựa chọn (4,5 điểm, mỗi câu 0,25 điểm), Phần II gồm 4 câu đúng/sai, mỗi câu 4 ý (4 điểm), Phần III gồm 6 câu trả lời ngắn (1,5 điểm, mỗi câu 0,25 điểm). App chấm tự động cả ba phần như đề thật: ở Phần II, đúng 1, 2, 3 hay cả 4 ý của một câu thì câu đó được 0,1; 0,25; 0,5 hay 1 điểm; ở Phần III, bạn ghi đáp số (không quá 4 kí tự), câu nào dặn làm tròn thì làm tròn đúng như dặn. Nguyên tử khối và các số liệu cần dùng được cho ngay trong câu. Đề không có câu tự chấm, nên điểm lưu ở mục Kết quả là điểm của cả đề.",
    passages: {
      "tn1-pin": { title: "Bốn cặp oxi hoá – khử", text: "Cho thế điện cực chuẩn của bốn cặp oxi hoá – khử: E°(Mg²⁺/Mg) = −2,356 V; E°(Fe²⁺/Fe) = −0,440 V; E°(Cu²⁺/Cu) = +0,340 V; E°(Ag⁺/Ag) = +0,799 V." }
    },
    questions: [
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Ester – Lipid", type: "mc", q: "Đun nóng ethyl formate (HCOOC₂H₅) với lượng dư dung dịch NaOH đến khi ester phản ứng hết. Muối thu được là", o: ["HCOONa", "CH₃COONa", "C₂H₅COONa", "C₂H₅ONa"],
        x: "HCOOC₂H₅ + NaOH → HCOONa + C₂H₅OH. Phần gốc acid HCOO– của ester chuyển thành muối sodium formate, phần gốc ethyl chuyển thành ethanol.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Xà phòng và chất giặt rửa", type: "mc", q: "Chất nào sau đây có thể là thành phần chính của một bánh xà phòng?", o: ["C₁₅H₃₁COONa", "CH₃COONa", "(C₁₅H₃₁COO)₃C₃H₅", "C₁₅H₃₁COOH"],
        x: "Chất tẩy rửa chính trong bánh xà phòng là muối của acid béo với sodium (hay potassium): một gốc hydrocarbon dài, từ khoảng 12 nguyên tử carbon trở lên, gắn với nhóm –COONa (hay –COOK). C₁₅H₃₁COONa (sodium palmitate) là muối như vậy. CH₃COONa có gốc hydrocarbon quá ngắn; (C₁₅H₃₁COO)₃C₃H₅ là một chất béo; C₁₅H₃₁COOH là acid béo, chưa phải muối.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Giới thiệu về carbohydrate. Glucose và fructose", type: "mc", q: "Đun nóng từng chất sau với dung dịch acid loãng. Chất nào không bị thuỷ phân?", o: ["Fructose", "Saccharose", "Maltose", "Tinh bột"],
        x: "Fructose là monosaccharide nên không bị thuỷ phân. Saccharose và maltose là disaccharide, tinh bột là polysaccharide; cả ba đều bị thuỷ phân khi đun với acid loãng.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Tinh bột và cellulose", type: "mc", q: "Sợi bông gần như là cellulose nguyên chất. Phân tử cellulose có rất nhiều nhóm –OH, vậy mà áo bông giặt nhiều lần vẫn không bị nước hoà tan. Nguyên nhân chủ yếu là", o: ["các mạch cellulose xếp song song, liên kết hydrogen chặt với nhau", "phân tử cellulose không tạo được liên kết hydrogen với nước", "các nhóm –OH của cellulose đã chuyển hết thành nhóm ester", "cellulose là hợp chất ion, các ion hút nhau rất mạnh"],
        x: "Mạch cellulose rất dài; các mạch xếp song song cạnh nhau, nhóm –OH của mạch này liên kết hydrogen với nhóm –OH của mạch bên cạnh, tạo thành bó sợi bền. Nước không tách được các mạch ra khỏi nhau nên sợi bông không tan.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Amine", type: "mc", q: "Nhỏ từ từ dung dịch ethylamine vào dung dịch Fe(NO₃)₃. Hiện tượng quan sát được là", o: ["xuất hiện kết tủa màu nâu đỏ", "xuất hiện kết tủa màu trắng", "xuất hiện kết tủa màu xanh lam", "có bọt khí không màu thoát ra"],
        x: "Dung dịch ethylamine có tính base như dung dịch ammonia, nên tạo kết tủa hydroxide với ion Fe³⁺: 3C₂H₅NH₂ + Fe(NO₃)₃ + 3H₂O → Fe(OH)₃ + 3C₂H₅NH₃NO₃. Fe(OH)₃ là chất rắn màu nâu đỏ.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Amino acid và peptide", type: "mc", q: "Trong dung dịch nước, amino acid nào sau đây làm quỳ tím chuyển sang màu xanh?", o: ["Lysine", "Glycine", "Alanine", "Valine"],
        x: "Phân tử lysine có hai nhóm amino (–NH₂) nhưng chỉ có một nhóm carboxyl (–COOH), nên dung dịch có môi trường base, làm quỳ tím hoá xanh. Glycine, alanine, valine có một nhóm –NH₂ và một nhóm –COOH, dung dịch gần như trung tính.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Đại cương về polymer", type: "mc", q: "Poly(vinyl chloride) (PVC), loại nhựa làm ống dẫn nước, được tổng hợp từ monomer nào sau đây?", o: ["CH₂=CHCl", "CH₂=CH₂", "CH₂=CH–CH₃", "CH₂=CCl₂"],
        x: "Trùng hợp vinyl chloride (CH₂=CHCl) thu được PVC, mỗi mắt xích là –CH₂–CHCl–. Ethylene (CH₂=CH₂) cho polyethylene, propylene (CH₂=CH–CH₃) cho polypropylene.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Vật liệu polymer", type: "mc", q: "Cao su buna-S, một loại cao su tổng hợp dùng làm lốp xe, được tạo thành khi buta-1,3-diene cùng tham gia phản ứng trùng hợp với monomer nào sau đây?", o: ["styrene", "acrylonitrile", "isoprene", "vinyl chloride"],
        x: "Mạch buna-S gồm các mắt xích của buta-1,3-diene xen với các mắt xích của styrene (C₆H₅–CH=CH₂). Khi thay styrene bằng acrylonitrile, sản phẩm là cao su buna-N.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Lớp 10 · Tốc độ phản ứng", type: "mc", q: "Khi nhóm lò than, người ta thường dùng quạt thổi thêm không khí vào lò, làm than cháy nhanh và mạnh hơn. Yếu tố chủ yếu làm tăng tốc độ phản ứng cháy trong trường hợp này là", o: ["nồng độ oxygen", "áp suất khí carbon dioxide", "diện tích bề mặt của than", "chất xúc tác"],
        x: "Quạt đưa thêm không khí vào lò, làm tăng lượng oxygen tiếp xúc với than, tức là tăng nồng độ của một chất phản ứng, nên tốc độ phản ứng cháy tăng. Kích thước các cục than không đổi và không có chất xúc tác nào được thêm vào.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Lớp 11 · Nitrogen – Sulfur", type: "mc", q: "Cách nào sau đây là đúng khi cần pha loãng dung dịch sulfuric acid đặc?", o: ["Rót từ từ acid vào nước, vừa rót vừa khuấy", "Rót từ từ nước vào acid, vừa rót vừa khuấy", "Rót nhanh nước vào acid rồi đậy kín cốc", "Rót acid vào nước đang đun sôi cho nhanh tan"],
        x: "Sulfuric acid đặc tan vào nước toả rất nhiều nhiệt. Nếu rót nước vào acid, lớp nước nổi bên trên sôi lên ngay, làm acid bắn ra ngoài. Rót từ từ acid vào lượng nước lớn hơn nhiều và khuấy đều thì nhiệt được nước hấp thụ dần, an toàn hơn.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Lớp 11 · Dẫn xuất halogen – Alcohol – Phenol", type: "mc", q: "Có hai ống nghiệm mất nhãn, một ống đựng dung dịch glycerol, ống kia đựng dung dịch ethanol. Nhỏ thuốc thử nào sau đây vào từng ống thì nhận ra được ống đựng glycerol?", o: ["Cu(OH)₂", "quỳ tím", "dung dịch NaCl", "dung dịch HCl loãng"],
        x: "Glycerol có các nhóm –OH ở những nguyên tử carbon liền kề nên hoà tan được Cu(OH)₂, tạo dung dịch xanh lam; ethanol không có phản ứng này. Với quỳ tím, dung dịch NaCl hay dung dịch HCl loãng, hai ống đều không có hiện tượng gì khác nhau.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Thế điện cực và nguồn điện hoá học", type: "mc", q: "Khi pin Galvani Zn – Cu hoạt động, quá trình xảy ra ở điện cực kẽm là", o: ["Zn bị oxi hoá thành ion Zn²⁺", "ion Zn²⁺ bị khử thành Zn", "ion Cu²⁺ bị khử thành Cu", "Cu bị oxi hoá thành ion Cu²⁺"],
        x: "E°(Zn²⁺/Zn) = −0,762 V nhỏ hơn E°(Cu²⁺/Cu) = +0,340 V, nên kẽm là anode (cực âm), tại đó Zn → Zn²⁺ + 2e. Ở cathode (cực dương), ion Cu²⁺ nhận electron: Cu²⁺ + 2e → Cu.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Thế điện cực và nguồn điện hoá học", type: "mc", p: "tn1-pin", q: "Ghép hai trong bốn điện cực chuẩn trên thành một pin Galvani. Pin nào sau đây có sức điện động chuẩn nhỏ nhất?", o: ["Pin Cu – Ag", "Pin Fe – Cu", "Pin Mg – Fe", "Pin Mg – Ag"],
        x: "E°pin = E°(cathode) − E°(anode). Pin Cu – Ag: 0,799 − 0,340 = 0,459 (V); pin Fe – Cu: 0,340 − (−0,440) = 0,780 (V); pin Mg – Fe: −0,440 − (−2,356) = 1,916 (V); pin Mg – Ag: 0,799 − (−2,356) = 3,155 (V). Hai cặp có thế điện cực chuẩn càng gần nhau thì pin có sức điện động càng nhỏ.", lv: 3, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "mc", p: "tn1-pin", q: "Cho bột sắt (lấy dư) vào dung dịch chứa đồng thời Cu(NO₃)₂ và AgNO₃. Sau khi các phản ứng xảy ra hoàn toàn, chất rắn thu được gồm", o: ["Fe, Cu và Ag", "Cu và Ag", "Fe và Ag", "Fe và Cu"],
        x: "E°(Fe²⁺/Fe) nhỏ hơn thế điện cực chuẩn của cả hai cặp Cu²⁺/Cu và Ag⁺/Ag, nên sắt khử được cả hai ion: Fe + 2Ag⁺ → Fe²⁺ + 2Ag (xảy ra trước), rồi Fe + Cu²⁺ → Fe²⁺ + Cu. Sắt lấy dư nên hai ion bị khử hết, phần sắt còn lại nằm cùng bạc và đồng trong chất rắn.", lv: 3, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "mc", q: "Nung nóng mạnh từng kim loại sau trong không khí. Kim loại nào không bị oxygen oxi hoá?", o: ["Platinum (Pt)", "Magnesium (Mg)", "Nhôm (Al)", "Sắt (Fe)"],
        x: "Khi đun nóng, phần lớn kim loại bị oxygen oxi hoá thành oxide, chẳng hạn 2Mg + O₂ → 2MgO; 4Al + 3O₂ → 2Al₂O₃; 3Fe + 2O₂ → Fe₃O₄. Platinum rất kém hoạt động, không bị oxygen oxi hoá kể cả khi nung nóng, nên bền ngoài không khí.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Kim loại trong tự nhiên và phương pháp tách kim loại", type: "mc", q: "Người ta chỉ thu được kim loại nào sau đây khi điện phân nóng chảy muối chloride của nó, chứ không dùng chất khử hoá học?", o: ["Sodium (Na)", "Sắt (Fe)", "Đồng (Cu)", "Bạc (Ag)"],
        x: "Kim loại rất mạnh như sodium chỉ tách được khỏi hợp chất bằng dòng điện: điện phân NaCl nóng chảy, 2NaCl → 2Na + Cl₂. Sắt, đồng, bạc hoạt động yếu hơn nhiều nên không cần dùng cách này.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Nguyên tố nhóm IIA", type: "mc", q: "Một số túi bánh có kèm gói nhỏ đựng vôi sống (CaO) để giữ bánh khô giòn. Vôi sống làm được việc này là vì", o: ["CaO kết hợp với hơi nước, tạo thành Ca(OH)₂", "CaO hút khí oxygen, giữ cho bánh không bị ôi", "CaO bay hơi, đẩy không khí ẩm ra khỏi túi", "CaO tác dụng với tinh bột, làm bánh cứng lại"],
        x: "Vôi sống hút hơi nước trong túi và kết hợp với nước: CaO + H₂O → Ca(OH)₂. Không khí trong túi khô đi nên bánh không bị ỉu. CaO là chất rắn khó bay hơi, không tác dụng với tinh bột và không dùng để hút oxygen.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Một số tính chất và ứng dụng của phức chất", type: "mc", q: "Hemoglobin, chất giúp máu vận chuyển oxygen, chứa phức chất có nguyên tử trung tâm là ion", o: ["Fe²⁺", "Cu²⁺", "Zn²⁺", "Co³⁺"],
        x: "Trong hemoglobin, ion Fe²⁺ là nguyên tử trung tâm, liên kết với các nguyên tử nitrogen của nhóm heme. Phân tử oxygen gắn được vào ion Fe²⁺ ở phổi rồi được giải phóng ở các mô, nhờ vậy máu vận chuyển được oxygen.", lv: 1, pt: 0.25 },
      { part: "Phần II. Trắc nghiệm đúng sai", topic: "Xà phòng và chất giặt rửa", type: "tf4", q: "Một nhóm học sinh làm thí nghiệm như sau: cho vào bát sứ một ít mỡ lợn và lượng dư dung dịch NaOH đặc, đun sôi nhẹ khoảng 10 phút, khuấy liên tục bằng đũa thuỷ tinh, thỉnh thoảng thêm vài giọt nước cất. Để nguội, rót thêm dung dịch NaCl bão hoà vào bát rồi để yên. Mỗi ý sau đúng hay sai?", o: ["Trong bát sứ, chất béo bị thuỷ phân trong môi trường kiềm, tạo thành glycerol và muối của các acid béo.", "Có thể thay dung dịch NaOH đặc bằng dung dịch Na₂SO₄ đặc mà vẫn thu được xà phòng.", "Dung dịch NaCl bão hoà làm muối của các acid béo khó tan hơn, tách ra thành lớp chất rắn màu trắng nổi lên trên.", "Nếu thay mỡ lợn bằng dầu bôi trơn máy (thành phần chính là các hydrocarbon) thì cũng thu được xà phòng."], a: [true, false, true, false],
        x: "a) Đúng: đây là phản ứng xà phòng hoá chất béo, sản phẩm là glycerol và muối sodium của các acid béo (thành phần của xà phòng). b) Sai: Na₂SO₄ là muối trung tính, không thuỷ phân được chất béo. c) Đúng: muối của acid béo ít tan trong dung dịch NaCl bão hoà, lại nhẹ hơn dung dịch nên tách ra và nổi lên. d) Sai: hydrocarbon không có nhóm chức ester nên không bị xà phòng hoá.", lv: 2, pt: 1 },
      { part: "Phần II. Trắc nghiệm đúng sai", topic: "Đại cương về polymer", type: "tf4", q: "Polyethylene (PE) được dùng làm túi đựng, màng bọc thực phẩm. Mỗi ý sau về PE đúng hay sai?", o: ["Trùng hợp ethylene (CH₂=CH₂) thu được PE.", "Mỗi mắt xích của PE có công thức –CH₂–CH₂–.", "Một mẫu PE có phân tử khối trung bình 42 000 thì hệ số polymer hoá trung bình của mẫu là 1 500.", "PE bị thuỷ phân nhanh trong nước mưa nên túi PE vứt ra môi trường tự phân huỷ sau vài ngày."], a: [true, true, true, false],
        x: "a) Đúng: khi trùng hợp, liên kết đôi C=C của các phân tử ethylene mở ra để chúng nối với nhau thành mạch dài. b) Đúng: mắt xích giữ nguyên các nguyên tử của monomer: –CH₂–CH₂–. c) Đúng: mỗi mắt xích có phân tử khối 28, nên hệ số polymer hoá trung bình bằng 42 000 : 28 = 1 500. d) Sai: PE bền với nước, acid, base loãng; túi PE tồn tại rất lâu trong môi trường, gây ô nhiễm.", lv: 1, pt: 1 },
      { part: "Phần II. Trắc nghiệm đúng sai", topic: "Sự ăn mòn kim loại", type: "tf4", q: "Để tìm hiểu điều kiện gỉ sắt, một học sinh đặt ba đinh sắt sạch giống nhau vào ba ống nghiệm: ống (1) chỉ có không khí khô (đáy ống có CaCl₂ khan để hút ẩm, nút kín); ống (2) có nước cất đã đun sôi rồi để nguội, đinh ngập hoàn toàn, trên mặt nước phủ một lớp dầu ăn; ống (3) có nước cất ngập một nửa đinh, để hở miệng ống. Sau một tuần, quan sát các đinh sắt. Mỗi ý sau đúng hay sai?", o: ["Đinh sắt ở ống (3) bị gỉ rõ nhất.", "Đinh sắt ở ống (1) gỉ nhanh hơn ở ống (3) vì không khí khô chứa nhiều oxygen hơn.", "Lớp dầu ăn ở ống (2) ngăn khí oxygen của không khí hoà tan vào nước, nên đinh sắt hầu như không bị gỉ.", "Kết quả thí nghiệm cho thấy sắt chỉ bị gỉ khi có đồng thời nước và oxygen."], a: [true, false, true, true],
        x: "a) Đúng: ở ống (3), đinh sắt tiếp xúc với cả nước và không khí. b) Sai: không khí khô có oxygen nhưng không có hơi nước nên đinh ở ống (1) hầu như không gỉ. c) Đúng: đun sôi đã đuổi khí hoà tan ra khỏi nước, lớp dầu không cho không khí tan trở lại. d) Đúng: thiếu nước (ống 1) hoặc thiếu oxygen (ống 2) thì sắt hầu như không bị gỉ.", lv: 2, pt: 1 },
      { part: "Phần II. Trắc nghiệm đúng sai", topic: "Sơ lược về phức chất", type: "tf4", q: "Muối [Co(NH₃)₆]Cl₃ tan trong nước, phân li thành ion phức [Co(NH₃)₆]³⁺ và ion Cl⁻. Mỗi ý sau đúng hay sai?", o: ["Ion phức [Co(NH₃)₆]³⁺ có nguyên tử trung tâm là ion Co²⁺.", "Phức chất [Co(NH₃)₆]³⁺ có 6 phối tử, dạng hình học bát diện.", "Khi một phối tử NH₃ trong [Co(NH₃)₆]³⁺ được thay bằng một ion Cl⁻ thì thu được phức chất [CoCl(NH₃)₅]²⁺.", "Hoà tan 0,1 mol [Co(NH₃)₆]Cl₃ vào nước thu được 0,1 mol ion Cl⁻ tự do."], a: [false, true, true, false],
        x: "a) Sai: các phối tử NH₃ không mang điện, phức chất mang điện tích +3, nên nguyên tử trung tâm là Co³⁺. b) Đúng: phức chất có 6 phối tử NH₃ nên có dạng bát diện. c) Đúng: điện tích của phức chất mới là +3 + (−1) = +2. d) Sai: [Co(NH₃)₆]Cl₃ → [Co(NH₃)₆]³⁺ + 3Cl⁻, nên 0,1 mol muối tạo ra 0,3 mol ion Cl⁻.", lv: 3, pt: 1 },
      { part: "Phần III. Trả lời ngắn", topic: "Ester – Lipid", type: "num", q: "Một ester no, đơn chức, mạch hở có công thức phân tử C₅H₁₀O₂. Đun ester này với dung dịch H₂SO₄ loãng, một trong hai sản phẩm là formic acid (HCOOH). Hỏi có bao nhiêu chất phù hợp với ester đó?", ans: 4,
        x: "Ester tạo ra formic acid có dạng HCOOR′, trong đó R′ là gốc C₄H₉–. Gốc C₄H₉– có 4 cấu tạo: CH₃CH₂CH₂CH₂–, CH₃CH₂CH(CH₃)–, (CH₃)₂CHCH₂–, (CH₃)₃C–. Vậy có 4 ester.", lv: 2, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Lớp 10 · Năng lượng hoá học", type: "num", q: "Cho nhiệt tạo thành chuẩn của các chất: C₂H₂(g) +227,0 kJ/mol; C₂H₆(g) −84,7 kJ/mol. Biến thiên enthalpy chuẩn của phản ứng C₂H₂(g) + 2H₂(g) → C₂H₆(g) bằng bao nhiêu kilojoule? (Làm tròn kết quả đến hàng đơn vị.)", ans: -312, tol: 0.5, unit: "kJ",
        x: "Nhiệt tạo thành chuẩn của đơn chất H₂(g) bằng 0. ΔrH° = ΔfH°(C₂H₆) − [ΔfH°(C₂H₂) + 2 · 0] = −84,7 − 227,0 = −311,7 (kJ) ≈ −312 kJ. Phản ứng toả nhiệt.", lv: 2, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Tinh bột và cellulose", type: "num", q: "Cho 3,24 tấn cellulose tác dụng với nitric acid (xúc tác sulfuric acid đặc) để sản xuất cellulose trinitrate (thuốc súng không khói), hiệu suất 90%. Người ta thu được bao nhiêu tấn cellulose trinitrate? (Cho H = 1, C = 12, N = 14, O = 16; làm tròn kết quả đến hàng phần trăm.)", ans: 5.35, tol: 0.005, unit: "tấn",
        x: "Mỗi mắt xích C₆H₁₀O₅ (M = 162) của cellulose chuyển thành một mắt xích C₆H₇O₂(ONO₂)₃ (M = 297). Khối lượng cellulose trinitrate: 3,24 · 297/162 · 90% = 5,346 (tấn) ≈ 5,35 tấn.", lv: 3, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Amino acid và peptide", type: "num", q: "Có bao nhiêu tripeptide mà mỗi phân tử chứa đúng một gốc glycine, một gốc alanine và một gốc valine?", ans: 6,
        x: "Ba gốc khác nhau xếp theo mọi thứ tự có thể: Gly-Ala-Val, Gly-Val-Ala, Ala-Gly-Val, Ala-Val-Gly, Val-Gly-Ala, Val-Ala-Gly. Có 3 · 2 · 1 = 6 tripeptide.", lv: 2, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Cấu tạo và liên kết trong tinh thể kim loại", type: "num", q: "Cho các nguyên tố: Na (Z = 11), Mg (Z = 12), Al (Z = 13), Si (Z = 14), P (Z = 15), K (Z = 19), Ca (Z = 20), Br (Z = 35). Có bao nhiêu nguyên tố kim loại trong các nguyên tố trên?", ans: 5,
        x: "Na, K thuộc nhóm IA; Mg, Ca thuộc nhóm IIA; Al thuộc nhóm IIIA: đều là kim loại. Si (nhóm IVA), P (nhóm VA), Br (nhóm VIIA) là phi kim. Có 5 nguyên tố kim loại.", lv: 1, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Nguyên tố nhóm IA", type: "num", q: "Một loại viên nhai chữa ợ chua chứa 0,84 g NaHCO₃ mỗi viên. Khi nhai hai viên, lượng NaHCO₃ đó trung hoà được tối đa bao nhiêu mililít dịch có HCl nồng độ 0,1 M? (Cho H = 1, C = 12, O = 16, Na = 23.)", ans: 200, unit: "mL",
        x: "NaHCO₃ + HCl → NaCl + CO₂ + H₂O. Hai viên chứa 2 · 0,84 = 1,68 (g) NaHCO₃, tức 1,68 : 84 = 0,02 (mol). Theo phương trình, n(HCl) = 0,02 mol, nên thể tích dịch là 0,02 : 0,1 = 0,2 (L) = 200 mL.", lv: 3, pt: 0.25 }
    ]
  },
  "hoahoc12-tn-de2": {
    note: "Đề thi thử theo cấu trúc đề thi tốt nghiệp THPT từ năm 2025 (Quyết định 764/QĐ-BGDĐT). Năm 2027 thí điểm thi trên máy tính ở nơi đủ điều kiện, đề như thi giấy. Phạm vi: chương trình THPT, chủ yếu Hoá học 12 (sách Kết nối tri thức, cả năm học). Như đề tham khảo năm 2025 và đề chính thức năm 2026 (2 câu thuộc lớp 10, 2 câu thuộc lớp 11, còn lại thuộc lớp 12), đề có 24 câu Hoá học 12, 2 câu Hoá học 11 và 2 câu Hoá học 10. Đề có 28 câu, làm trong 50 phút: Phần I gồm 18 câu nhiều lựa chọn (4,5 điểm, mỗi câu 0,25 điểm), Phần II gồm 4 câu đúng/sai, mỗi câu 4 ý (4 điểm), Phần III gồm 6 câu trả lời ngắn (1,5 điểm, mỗi câu 0,25 điểm). App chấm tự động cả ba phần như đề thật: ở Phần II, đúng 1, 2, 3 hay cả 4 ý của một câu thì câu đó được 0,1; 0,25; 0,5 hay 1 điểm; ở Phần III, bạn ghi đáp số (không quá 4 kí tự), câu nào dặn làm tròn thì làm tròn đúng như dặn. Nguyên tử khối và các số liệu cần dùng được cho ngay trong câu. Đề không có câu tự chấm, nên điểm lưu ở mục Kết quả là điểm của cả đề.",
    questions: [
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Ester – Lipid", type: "mc", q: "Đun nóng ester nào sau đây với dung dịch acid loãng thì một trong các sản phẩm thu được là methanol (CH₃OH)?", o: ["CH₃COOCH₃", "HCOOC₂H₅", "HCOOC₃H₇", "C₂H₅COOC₂H₅"],
        x: "Ester RCOOR′ bị thuỷ phân thành acid RCOOH và alcohol R′OH. Chỉ CH₃COOCH₃ có gốc R′ là –CH₃ nên tạo methanol: CH₃COOCH₃ + H₂O ⇌ CH₃COOH + CH₃OH. Ba ester còn lại có gốc R′ là –C₂H₅ hoặc –C₃H₇, khi thuỷ phân cho ethanol hoặc propan-1-ol.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Ester – Lipid", type: "mc", q: "Xà phòng hoá hoàn toàn 0,1 mol ester X (công thức phân tử C₄H₈O₂) bằng dung dịch NaOH vừa đủ, cô cạn dung dịch sau phản ứng thu được 8,2 g muối khan. Công thức cấu tạo của X là (Cho H = 1, C = 12, O = 16, Na = 23.)", o: ["CH₃COOC₂H₅", "C₂H₅COOCH₃", "HCOOC₃H₇", "HCOOCH(CH₃)₂"],
        x: "Mỗi mol ester đơn chức tạo một mol muối, nên n(muối) = 0,1 mol và M(muối) = 8,2 : 0,1 = 82 (g/mol), đúng với CH₃COONa. Vậy X là CH₃COOC₂H₅. Ba lựa chọn còn lại cho muối có phân tử khối khác 82.", lv: 3, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Giới thiệu về carbohydrate. Glucose và fructose", type: "mc", q: "Có hai dung dịch riêng biệt: glucose và fructose. Thuốc thử nào sau đây phân biệt được hai dung dịch đó?", o: ["Nước bromine", "Cu(OH)₂ ở nhiệt độ thường", "Thuốc thử Tollens", "Quỳ tím"],
        x: "Glucose làm nước bromine nhạt màu (nhóm –CHO bị oxi hoá), fructose thì không. Với Cu(OH)₂ ở nhiệt độ thường và với thuốc thử Tollens, hai chất cho hiện tượng giống nhau; dung dịch của cả hai chất đều không làm đổi màu quỳ tím.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Tinh bột và cellulose", type: "mc", q: "Trong cây xanh, tinh bột được tạo ra từ khí carbon dioxide và nước nhờ quá trình", o: ["quang hợp", "hô hấp", "lên men", "thuỷ phân"],
        x: "Nhờ năng lượng ánh sáng và chất diệp lục, cây xanh tổng hợp chất hữu cơ từ CO₂ và nước (quang hợp), rồi tích luỹ thành tinh bột: 6nCO₂ + 5nH₂O → (C₆H₁₀O₅)ₙ + 6nO₂.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Amine", type: "mc", q: "Cho ethylamine tác dụng với nitrous acid (HONO) ở nhiệt độ thường. Sản phẩm hữu cơ thu được là", o: ["C₂H₅OH", "C₂H₅NO₂", "CH₃CHO", "C₂H₅NH₃NO₂"],
        x: "Alkylamine bậc một phản ứng với nitrous acid ở nhiệt độ thường, nhóm –NH₂ được thay bằng nhóm –OH và có khí nitrogen thoát ra: C₂H₅NH₂ + HONO → C₂H₅OH + N₂ + H₂O. Sản phẩm hữu cơ là ethanol.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Amino acid và peptide", type: "mc", q: "Thuỷ phân hoàn toàn 1 mol pentapeptide X thu được 2 mol glycine, 2 mol alanine và 1 mol valine. Thuỷ phân không hoàn toàn X thu được tripeptide Gly-Ala-Gly và các dipeptide Gly-Val, Val-Ala. Trình tự các gốc amino acid trong X là", o: ["Gly-Ala-Gly-Val-Ala", "Ala-Gly-Ala-Gly-Val", "Gly-Val-Ala-Gly-Ala", "Val-Ala-Gly-Ala-Gly"],
        x: "X gồm 2 gốc Gly, 2 gốc Ala và 1 gốc Val. Đoạn Gly-Ala-Gly đã dùng hết 2 gốc Gly; đoạn Gly-Val cho biết Val đứng ngay sau một gốc Gly, nên Val nối vào cuối đoạn Gly-Ala-Gly; đoạn Val-Ala cho biết gốc Ala còn lại đứng sau Val. X là Gly-Ala-Gly-Val-Ala.", lv: 3, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Đại cương về polymer", type: "mc", q: "Chất nào sau đây là polymer thiên nhiên?", o: ["Cellulose", "Polyethylene", "Polypropylene", "Polystyrene"],
        x: "Cellulose có sẵn trong thành tế bào thực vật (bông, gỗ, đay…). Polyethylene, polypropylene, polystyrene đều là polymer tổng hợp, do con người điều chế trong nhà máy.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Vật liệu polymer", type: "mc", q: "Quần áo may bằng vải nylon-6,6 không nên giặt bằng xà phòng có tính kiềm mạnh trong nước nóng, cũng không nên là (ủi) ở nhiệt độ quá cao. Lí do chính là", o: ["các nhóm amide –CO–NH– trong mạch dễ bị thuỷ phân, làm sợi kém bền", "nylon-6,6 là polymer thiên nhiên nên dễ bị vi khuẩn phân huỷ", "mạch nylon-6,6 có nhiều liên kết đôi C=C dễ bị oxi hoá", "nylon-6,6 tan hoàn toàn trong nước khi nhiệt độ trên 40 °C"],
        x: "Mạch nylon-6,6 có nhiều nhóm amide –CO–NH–. Trong môi trường kiềm hay acid, nhất là khi nóng, các nhóm này bị thuỷ phân, mạch polymer đứt dần nên sợi vải yếu đi.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Lớp 10 · Phản ứng oxi hoá – khử", type: "mc", q: "Phản ứng nhiệt nhôm 2Al + Fe₂O₃ → Al₂O₃ + 2Fe toả rất nhiều nhiệt, được dùng để hàn đường ray. Trong phản ứng này, chất khử là", o: ["Al", "Fe₂O₃", "Al₂O₃", "Fe"],
        x: "Số oxi hoá của Al tăng từ 0 lên +3 (Al nhường electron), nên Al là chất khử; số oxi hoá của Fe giảm từ +3 xuống 0, nên Fe₂O₃ là chất oxi hoá. Al₂O₃ và Fe là sản phẩm.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Lớp 11 · Cân bằng hoá học", type: "mc", q: "Phản ứng N₂(g) + 3H₂(g) ⇌ 2NH₃(g), có ΔrH°298 < 0, là cơ sở của quá trình sản xuất ammonia. Thay đổi nào sau đây làm cân bằng chuyển dịch theo chiều thuận?", o: ["Tăng áp suất chung của hệ", "Tăng nhiệt độ của hệ", "Giảm áp suất chung của hệ", "Thêm chất xúc tác"],
        x: "Chiều thuận làm giảm số mol khí (4 mol khí thành 2 mol khí), nên tăng áp suất thì cân bằng chuyển dịch theo chiều thuận. Chiều thuận toả nhiệt, nên tăng nhiệt độ làm cân bằng chuyển dịch theo chiều nghịch. Chất xúc tác không làm cân bằng chuyển dịch.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Lớp 11 · Hydrocarbon", type: "mc", q: "Dẫn lần lượt từng khí sau vào nước bromine. Khí nào làm nước bromine mất màu?", o: ["Ethylene", "Methane", "Ethane", "Carbon dioxide"],
        x: "Ethylene có liên kết đôi C=C nên cộng được bromine: C₂H₄ + Br₂ → C₂H₄Br₂, làm nước bromine mất màu. Methane, ethane thuộc dãy alkane, phân tử không có liên kết đôi; chúng và CO₂ đều không phản ứng với nước bromine.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Thế điện cực và nguồn điện hoá học", type: "mc", q: "Acquy chì lắp trên xe máy, ô tô thuộc loại nguồn điện hoá học nào sau đây?", o: ["Pin sạc, nạp điện lại để dùng nhiều lần", "Pin dùng một lần, hết điện thì bỏ đi", "Pin nhiên liệu, phải cấp nhiên liệu liên tục", "Pin chỉ hoạt động khi được chiếu sáng"],
        x: "Acquy là pin thứ cấp: khi phóng điện, hoá năng chuyển thành điện năng; khi nạp điện, các chất phản ứng được tái tạo, nên acquy dùng được nhiều lần.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Điện phân", type: "mc", q: "Điện phân NaCl nóng chảy với các điện cực trơ. Quá trình xảy ra ở cathode là", o: ["Na⁺ + e → Na", "2Cl⁻ → Cl₂ + 2e", "Na → Na⁺ + e", "Cl₂ + 2e → 2Cl⁻"],
        x: "Cathode nối với cực âm của nguồn điện; tại đó ion dương nhận electron (sự khử), ion Na⁺ tạo thành sodium. Ion Cl⁻ di chuyển về anode, nhường electron tạo khí chlorine.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Cấu tạo và liên kết trong tinh thể kim loại", type: "mc", q: "Nguyên tử aluminium (Z = 13) có cấu hình electron 1s²2s²2p⁶3s²3p¹. Vị trí của aluminium trong bảng tuần hoàn là", o: ["chu kì 3, nhóm IIIA", "chu kì 3, nhóm IA", "chu kì 2, nhóm IIIA", "chu kì 4, nhóm IIIA"],
        x: "Cấu hình có 3 lớp electron, lớp ngoài cùng là lớp thứ ba, nên aluminium ở chu kì 3. Lớp này có 3 electron (3s²3p¹) thuộc các phân lớp s, p, nên aluminium ở nhóm IIIA.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "mc", q: "Thả một chiếc đinh sắt đã cạo sạch gỉ vào cốc đựng dung dịch CuSO₄ loãng. Sau khoảng 15 phút, hiện tượng quan sát được là", o: ["có lớp đồng màu đỏ bám trên đinh, dung dịch nhạt màu xanh", "đinh sắt không thay đổi, dung dịch chuyển sang màu vàng", "có nhiều khí không màu sủi lên quanh đinh sắt", "dung dịch chuyển sang màu tím, đinh sắt tan hết"],
        x: "E°(Fe²⁺/Fe) = −0,44 V nhỏ hơn E°(Cu²⁺/Cu) = +0,340 V, nên sắt khử được ion Cu²⁺: Fe + CuSO₄ → FeSO₄ + Cu. Đồng tạo thành bám lên đinh; nồng độ ion Cu²⁺ (làm dung dịch có màu xanh) giảm dần.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Nguyên tố nhóm IIA", type: "mc", q: "Nông dân thường rải vôi (CaO hoặc Ca(OH)₂) xuống ruộng trước khi cấy để", o: ["khử chua, giảm độ acid của đất", "cung cấp nitrogen cho cây lúa", "làm đất giữ nước tốt hơn", "diệt hết vi sinh vật trong đất"],
        x: "Đất chua chứa nhiều acid. Vôi có tính base nên trung hoà bớt acid, giúp đất bớt chua để cây phát triển tốt. Vôi không chứa nitrogen, không phải là phân đạm.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Nguyên tố nhóm IA", type: "mc", q: "Bột nở (thành phần chính là NaHCO₃) được trộn vào bột mì khi làm bánh. Khi nướng, bánh phồng xốp chủ yếu vì", o: ["NaHCO₃ bị nhiệt phân, giải phóng khí CO₂", "NaHCO₃ tan trong nước, toả nhiều nhiệt", "NaHCO₃ tác dụng với tinh bột tạo ra glucose", "NaHCO₃ nóng chảy, tạo lớp màng bao quanh bột"],
        x: "Khi được đun nóng, NaHCO₃ bị phân huỷ: 2NaHCO₃ → Na₂CO₃ + CO₂ + H₂O. Khí CO₂ và hơi nước sinh ra trong khối bột làm bánh phồng lên, xốp.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Đại cương về kim loại chuyển tiếp dãy thứ nhất", type: "mc", q: "Thuốc tím (KMnO₄) được dùng để sát trùng. Số oxi hoá của manganese trong KMnO₄ là", o: ["+7", "+2", "+4", "+6"],
        x: "Trong KMnO₄, K có số oxi hoá +1, O có số oxi hoá −2. Tổng số oxi hoá bằng 0: (+1) + x + 4 · (−2) = 0, nên x = +7.", lv: 1, pt: 0.25 },
      { part: "Phần II. Trắc nghiệm đúng sai", topic: "Tinh bột và cellulose", type: "tf4", q: "Để tìm hiểu sự thuỷ phân tinh bột, hai ống nghiệm được chuẩn bị như sau: ống (1) chứa 2 mL hồ tinh bột và 2 giọt dung dịch iodine; ống (2) đun 2 mL hồ tinh bột với vài giọt dung dịch H₂SO₄ loãng trong khoảng 10 phút, để nguội, trung hoà acid bằng dung dịch NaOH rồi thêm thuốc thử Tollens và ngâm ống vào cốc nước nóng. Mỗi ý sau đúng hay sai?", o: ["Ở ống (1), dung dịch có màu xanh tím.", "Ở ống (2), có bạc tạo thành, phủ lên mặt trong của ống nghiệm, vì tinh bột đã chuyển thành glucose.", "Nếu bỏ bước đun với H₂SO₄ loãng thì ở ống (2) vẫn tạo được lớp bạc như vậy.", "Phải trung hoà acid trước khi thêm thuốc thử Tollens vì thuốc thử này bị acid phá huỷ."], a: [true, true, false, true],
        x: "a) Đúng: iodine tạo với tinh bột màu xanh tím. b) Đúng: khi đun với acid loãng, tinh bột chuyển dần thành glucose; chất này khử ion bạc trong thuốc thử Tollens tạo lớp bạc. c) Sai: tinh bột không có tính khử như glucose, nên không tạo lớp bạc. d) Đúng: acid phản ứng với NH₃ trong thuốc thử, phá huỷ phức chất của bạc.", lv: 2, pt: 1 },
      { part: "Phần II. Trắc nghiệm đúng sai", topic: "Protein và enzyme", type: "tf4", q: "Mỗi ý sau về lòng trắng trứng (thành phần chính là protein) và enzyme đúng hay sai?", o: ["Đun nóng dung dịch lòng trắng trứng thì protein đông tụ lại thành chất rắn màu trắng.", "Lòng trắng trứng đã đông tụ vì nhiệt sẽ tan trở lại thành dung dịch khi để nguội.", "Cho dung dịch lòng trắng trứng vào ống nghiệm chứa Cu(OH)₂ vừa tạo thành (từ CuSO₄ và NaOH), lắc đều thì được dung dịch màu tím.", "Nhiệt độ càng cao, enzyme xúc tác càng mạnh, kể cả khi nhiệt độ lên tới 100 °C."], a: [true, false, true, false],
        x: "a) Đúng: khi đun nóng, protein trong lòng trắng trứng bị đông tụ. b) Sai: sự đông tụ vì nhiệt không trở lại như cũ khi để nguội. c) Đúng: đó là phản ứng màu biuret của protein với Cu(OH)₂ trong môi trường kiềm. d) Sai: phần lớn enzyme là protein, ở nhiệt độ cao chúng bị biến tính và mất khả năng xúc tác.", lv: 1, pt: 1 },
      { part: "Phần II. Trắc nghiệm đúng sai", topic: "Thế điện cực và nguồn điện hoá học", type: "tf4", q: "Lắp một pin Galvani: lá kẽm nhúng trong dung dịch ZnSO₄ 1 M, lá đồng nhúng trong dung dịch CuSO₄ 1 M, giữa hai cốc có cầu muối chứa KNO₃; nối hai lá kim loại với một vôn kế. Cho E°(Zn²⁺/Zn) = −0,762 V; E°(Cu²⁺/Cu) = +0,340 V; E°(Ag⁺/Ag) = +0,799 V. Thí nghiệm tiến hành ở 25 °C. Mỗi ý sau đúng hay sai?", o: ["Trong dây dẫn bên ngoài, electron di chuyển từ lá kẽm sang lá đồng.", "Khi pin đã phóng điện được một lúc, lá đồng nhẹ đi so với lúc đầu.", "Số chỉ của vôn kế (coi như sức điện động của pin) khoảng 1,10 V.", "Thay lá đồng và dung dịch CuSO₄ bằng lá bạc và dung dịch AgNO₃ 1 M thì sức điện động chuẩn của pin tăng lên."], a: [true, false, true, true],
        x: "a) Đúng: E°(Zn²⁺/Zn) nhỏ hơn nên kẽm là anode (cực âm), Zn → Zn²⁺ + 2e; electron theo dây dẫn sang lá đồng. b) Sai: ở lá đồng (cathode), Cu²⁺ + 2e → Cu, đồng bám thêm nên khối lượng lá đồng tăng. c) Đúng: E°pin = 0,340 − (−0,762) = 1,102 (V). d) Đúng: pin Zn – Ag có E°pin = 0,799 − (−0,762) = 1,561 (V), lớn hơn 1,102 V.", lv: 3, pt: 1 },
      { part: "Phần II. Trắc nghiệm đúng sai", topic: "Nguyên tố nhóm IIA", type: "tf4", q: "Mỗi ý sau về nước cứng đúng hay sai?", o: ["Nước chứa nhiều ion Na⁺ và K⁺ được gọi là nước cứng.", "Dùng nước cứng để giặt thì xà phòng khó tạo bọt và phải dùng nhiều xà phòng hơn.", "Đun sôi nước có tính cứng vĩnh cửu (chứa CaCl₂, MgSO₄) sẽ làm mất hết tính cứng của nước đó.", "Nước có tính cứng tạm thời chứa các ion Ca²⁺, Mg²⁺ cùng với anion HCO₃⁻."], a: [false, true, false, true],
        x: "a) Sai: nước cứng là nước chứa nhiều ion Ca²⁺ và Mg²⁺. b) Đúng: ion Ca²⁺, Mg²⁺ tạo với xà phòng các muối khó tan, nên xà phòng ít bọt, bị hao phí. c) Sai: khi đun, các muối chloride, sulfate của calcium và magnesium không bị phân huỷ, nên tính cứng vĩnh cửu vẫn còn. d) Đúng: tính cứng tạm thời do các muối hydrogencarbonate của calcium và magnesium gây ra.", lv: 2, pt: 1 },
      { part: "Phần III. Trả lời ngắn", topic: "Giới thiệu về carbohydrate. Glucose và fructose", type: "num", q: "Cho 45 g glucose lên men rượu với hiệu suất 80%. Có bao nhiêu gam ethanol được tạo ra? (Cho H = 1, C = 12, O = 16.)", ans: 18.4, unit: "g",
        x: "C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂. n(glucose) = 45 : 180 = 0,25 (mol), nên n(ethanol) = 2 · 0,25 · 80% = 0,4 (mol); khối lượng ethanol là 0,4 · 46 = 18,4 (g).", lv: 3, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Lớp 10 · Cấu tạo nguyên tử", type: "num", q: "Trong tự nhiên, magnesium có ba đồng vị: ²⁴Mg chiếm 79%, ²⁵Mg chiếm 10%, còn lại là ²⁶Mg (tính theo số nguyên tử). Coi nguyên tử khối của mỗi đồng vị bằng số khối của nó. Nguyên tử khối trung bình của magnesium bằng bao nhiêu? (Làm tròn kết quả đến hàng phần mười.)", ans: 24.3, tol: 0.05,
        x: "Đồng vị ²⁶Mg chiếm 100% − 79% − 10% = 11%. Nguyên tử khối trung bình: 24 · 0,79 + 25 · 0,10 + 26 · 0,11 = 24,32 ≈ 24,3.", lv: 2, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Đại cương về polymer", type: "num", q: "Một mẫu poly(vinyl chloride) có phân tử khối trung bình là 100 000. Hệ số polymer hoá trung bình của mẫu PVC này bằng bao nhiêu? (Cho H = 1, C = 12, Cl = 35,5.)", ans: 1600,
        x: "Mỗi mắt xích –CH₂–CHCl– có phân tử khối 2 · 12 + 3 · 1 + 35,5 = 62,5. Hệ số polymer hoá trung bình: 100 000 : 62,5 = 1 600.", lv: 2, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "num", q: "Hoà tan hoàn toàn 5,4 g bột nhôm trong dung dịch HCl (lấy dư). Thể tích khí H₂ sinh ra bằng bao nhiêu lít? Biết ở điều kiện chuẩn, mỗi mol khí chiếm thể tích 24,79 L. (Cho Al = 27; làm tròn kết quả đến hàng phần trăm.)", ans: 7.44, tol: 0.005, unit: "L",
        x: "2Al + 6HCl → 2AlCl₃ + 3H₂. n(Al) = 5,4 : 27 = 0,2 (mol), nên n(H₂) = 0,2 · 3 : 2 = 0,3 (mol). Thể tích khí H₂: 0,3 · 24,79 = 7,437 (L) ≈ 7,44 L.", lv: 2, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Kim loại trong tự nhiên và phương pháp tách kim loại", type: "num", q: "Một nhà máy dùng quặng magnetite có 69,6% khối lượng là Fe₃O₄, tạp chất trong quặng không chứa sắt. Với mỗi tấn quặng, lượng sắt tối đa có thể thu được là bao nhiêu kilogam? (Cho O = 16, Fe = 56.)", ans: 504, unit: "kg",
        x: "Mỗi tấn quặng chứa 1 000 · 69,6% = 696 (kg) Fe₃O₄, tức 696 : 232 = 3 (kmol). Mỗi mol Fe₃O₄ chứa 3 mol Fe, nên khối lượng sắt tối đa là 3 · 3 · 56 = 504 (kg).", lv: 3, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Sơ lược về phức chất", type: "num", q: "Trong thuốc thử Tollens, bạc tồn tại ở dạng ion phức [Ag(NH₃)₂]⁺. Ion phức này có bao nhiêu phối tử?", ans: 2,
        x: "Công thức [Ag(NH₃)₂]⁺ cho biết nguyên tử trung tâm Ag⁺ liên kết với 2 phân tử NH₃, mỗi phân tử NH₃ là một phối tử. Ion phức có 2 phối tử.", lv: 1, pt: 0.25 }
    ]
  },
  "hoahoc12-tn-de3": {
    note: "Đề thi thử theo cấu trúc đề thi tốt nghiệp THPT từ năm 2025 (Quyết định 764/QĐ-BGDĐT). Năm 2027 thí điểm thi trên máy tính ở nơi đủ điều kiện, đề như thi giấy. Phạm vi: chương trình THPT, chủ yếu Hoá học 12 (sách Kết nối tri thức, cả năm học). Như đề tham khảo năm 2025 và đề chính thức năm 2026 (2 câu thuộc lớp 10, 2 câu thuộc lớp 11, còn lại thuộc lớp 12), đề có 24 câu Hoá học 12, 2 câu Hoá học 11 và 2 câu Hoá học 10. Đề có 28 câu, làm trong 50 phút: Phần I gồm 18 câu nhiều lựa chọn (4,5 điểm, mỗi câu 0,25 điểm), Phần II gồm 4 câu đúng/sai, mỗi câu 4 ý (4 điểm), Phần III gồm 6 câu trả lời ngắn (1,5 điểm, mỗi câu 0,25 điểm). App chấm tự động cả ba phần như đề thật: ở Phần II, đúng 1, 2, 3 hay cả 4 ý của một câu thì câu đó được 0,1; 0,25; 0,5 hay 1 điểm; ở Phần III, bạn ghi đáp số (không quá 4 kí tự), câu nào dặn làm tròn thì làm tròn đúng như dặn. Nguyên tử khối và các số liệu cần dùng được cho ngay trong câu. Đề không có câu tự chấm, nên điểm lưu ở mục Kết quả là điểm của cả đề.",
    questions: [
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Ester – Lipid", type: "mc", q: "Công thức nào sau đây là công thức của một chất béo?", o: ["(C₁₇H₃₁COO)₃C₃H₅", "(CH₃COO)₃C₃H₅", "C₁₇H₃₁COOC₂H₅", "(C₁₇H₃₁COO)₂C₂H₄"],
        x: "Mỗi phân tử chất béo là một triester, tạo từ glycerol và acid béo (carboxylic acid đơn chức, mạch carbon dài). (C₁₇H₃₁COO)₃C₃H₅ tạo từ glycerol và linoleic acid (C₁₇H₃₁COOH), một acid béo. (CH₃COO)₃C₃H₅ có gốc acid quá ngắn; C₁₇H₃₁COOC₂H₅ là ester của ethanol; (C₁₇H₃₁COO)₂C₂H₄ là ester của ethylene glycol.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Giới thiệu về carbohydrate. Glucose và fructose", type: "mc", q: "Trong công nghiệp, glucose được sản xuất chủ yếu bằng cách", o: ["thuỷ phân tinh bột nhờ xúc tác acid hoặc enzyme", "cho ethanol tác dụng với khí carbon dioxide", "lên men saccharose bằng nấm men", "cộng hydrogen vào fructose (xúc tác nickel)"],
        x: "Nguồn glucose rẻ và dồi dào là tinh bột (từ ngô, sắn…): thuỷ phân tinh bột nhờ acid hoặc enzyme thu được glucose. Lên men tạo ra ethanol chứ không tạo glucose; cộng hydrogen vào fructose cho sorbitol.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Tinh bột và cellulose", type: "mc", q: "Khi nấu súp, người ta thường hoà một ít bột năng (tinh bột sắn) vào nước nguội rồi đổ vào nồi súp đang sôi, khuấy đều. Một lúc sau súp sánh lại vì", o: ["trong nước nóng, tinh bột tạo thành dung dịch keo nhớt", "tinh bột bị đông tụ bởi nhiệt giống như lòng trắng trứng", "tinh bột phản ứng với muối ăn tạo thành chất kết tủa", "nhiệt độ cao làm nước bay hơi gần hết trong vài giây"],
        x: "Tinh bột không tan trong nước nguội. Trong nước nóng, các hạt tinh bột hút nước, trương lên và tạo dung dịch keo nhớt (hồ tinh bột), làm súp sánh lại; vì vậy tinh bột được dùng làm chất làm đặc trong chế biến thực phẩm. Đông tụ bởi nhiệt là tính chất của protein; muối ăn không tạo kết tủa với tinh bột.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Amine", type: "mc", q: "Ở điều kiện thường, amine nào sau đây là chất khí?", o: ["Trimethylamine", "Aniline", "Isopropylamine", "Butylamine"],
        x: "Trimethylamine có nhiệt độ sôi khoảng 3 °C, thấp hơn nhiệt độ phòng, nên ở điều kiện thường là chất khí; chất này gây ra mùi tanh của cá. Aniline, isopropylamine và butylamine đều là chất lỏng ở điều kiện thường.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Amino acid và peptide", type: "mc", q: "Thuỷ phân hoàn toàn tetrapeptide Ala-Gly-Ala-Val thu được bao nhiêu loại amino acid khác nhau?", o: ["3", "4", "2", "1"],
        x: "Tetrapeptide gồm bốn gốc Ala, Gly, Ala, Val; gốc Ala có mặt hai lần. Thuỷ phân hoàn toàn thu được ba amino acid khác nhau: alanine, glycine và valine.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Protein và enzyme", type: "mc", q: "Một số loại bột giặt có chứa enzyme protease, giúp giặt sạch vết máu, vết sữa trên quần áo. Enzyme này có tác dụng", o: ["xúc tác thuỷ phân protein trong vết bẩn thành chất dễ tan", "xúc tác thuỷ phân chất béo thành glycerol và acid béo", "oxi hoá các chất màu trong vết bẩn thành CO₂", "làm vết bẩn đông tụ lại để dễ gỡ ra khỏi vải"],
        x: "Vết máu, vết sữa chứa nhiều protein. Protease là enzyme xúc tác cho phản ứng thuỷ phân protein thành các phân tử nhỏ hơn, dễ tan trong nước giặt, nên vết bẩn được giặt sạch. Thuỷ phân chất béo cần một enzyme khác là lipase.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Đại cương về polymer", type: "mc", q: "Khi được đun nóng, phần lớn các polymer", o: ["nóng chảy trong một khoảng nhiệt độ khá rộng", "sôi ở một nhiệt độ xác định, giống như nước tinh khiết", "bay hơi hoàn toàn ngay ở nhiệt độ phòng", "đều cháy ngay, không bao giờ mềm ra"],
        x: "Polymer là hỗn hợp các phân tử có mạch dài ngắn khác nhau, nên thường không nóng chảy ở một nhiệt độ cố định mà mềm dần, chảy ra trong một khoảng nhiệt độ. Nhiều polymer bị phân huỷ khi đun nóng mạnh.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Đại cương về polymer", type: "mc", q: "Đốt cháy hoàn toàn một polymer X (chỉ chứa C và H), thu được số mol CO₂ gấp đôi số mol H₂O. X có thể là", o: ["polystyrene", "polyethylene", "polypropylene", "polybuta-1,3-diene"],
        x: "Mắt xích của polystyrene có công thức C₈H₈ (như styrene); đốt cháy: C₈H₈ + 10O₂ → 8CO₂ + 4H₂O, số mol CO₂ gấp đôi số mol H₂O. Mắt xích của polyethylene, polypropylene có dạng CₙH₂ₙ, cho số mol CO₂ bằng số mol H₂O; với polybuta-1,3-diene (mắt xích C₄H₆), tỉ lệ là 4 : 3.", lv: 3, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Vật liệu polymer", type: "mc", q: "Vật liệu polymer nào sau đây được dùng để gắn chặt hai bề mặt gỗ, kim loại hay sứ với nhau?", o: ["Keo dán epoxy", "Tơ nitron", "Cao su buna", "Nhựa polyethylene"],
        x: "Keo dán là vật liệu polymer có khả năng kết dính bề mặt hai vật; keo epoxy dán được kim loại, gỗ, gốm, sứ… Tơ nitron dùng dệt vải, cao su buna làm lốp xe, ống dẫn; nhựa polyethylene làm túi, màng mỏng.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Lớp 10 · Liên kết hoá học", type: "mc", q: "Hợp chất nào sau đây được tạo thành nhờ liên kết ion?", o: ["NaCl", "HCl", "H₂O", "CO₂"],
        x: "Sodium là kim loại điển hình, chlorine là phi kim điển hình: mỗi nguyên tử Na chuyển 1 electron sang nguyên tử Cl, tạo ra hai ion trái dấu Na⁺ và Cl⁻ hút nhau. HCl, H₂O, CO₂ chỉ gồm các nguyên tử phi kim, các nguyên tử góp chung electron, tạo liên kết cộng hoá trị.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Lớp 11 · Nitrogen – Sulfur", type: "mc", q: "Khí SO₂ thải ra khi đốt than đá có lẫn lưu huỳnh là một nguyên nhân gây mưa acid. Quá trình chủ yếu làm nước mưa có tính acid mạnh là", o: ["SO₂ bị oxi hoá thành SO₃, rồi kết hợp với nước tạo H₂SO₄", "SO₂ tác dụng với nitrogen trong không khí tạo HNO₃", "SO₂ bị phân huỷ thành lưu huỳnh và oxygen", "SO₂ tác dụng với khí CO₂ tạo ra H₂CO₃"],
        x: "Trong không khí, có bụi và ánh sáng làm xúc tác, SO₂ bị oxi hoá chậm: 2SO₂ + O₂ → 2SO₃; SO₃ tan vào nước mưa: SO₃ + H₂O → H₂SO₄, một acid mạnh. SO₂ cũng tan vào nước tạo H₂SO₃.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Lớp 11 · Hợp chất carbonyl – Carboxylic acid", type: "mc", q: "Acetic acid (CH₃COOH, phân tử khối 60) sôi ở 118 °C, còn propan-1-ol (C₃H₇OH, phân tử khối 60) sôi ở 97 °C. Nguyên nhân chủ yếu là", o: ["liên kết hydrogen giữa các phân tử acid bền hơn", "phân tử acetic acid có nhiều nguyên tử carbon hơn", "acetic acid là một chất điện li mạnh", "phân tử propan-1-ol không có nhóm –OH"],
        x: "Cả hai chất đều có liên kết hydrogen giữa các phân tử, nhưng liên kết hydrogen giữa các phân tử carboxylic acid bền hơn (nhóm –COOH phân cực mạnh hơn nhóm –OH của alcohol), nên acid sôi ở nhiệt độ cao hơn. Acetic acid là chất điện li yếu.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Thế điện cực và nguồn điện hoá học", type: "mc", q: "Để xác định thế điện cực chuẩn của cặp Zn²⁺/Zn, người ta ghép điện cực kẽm chuẩn với một điện cực làm mốc, có thế điện cực chuẩn được quy ước bằng 0, rồi đo sức điện động của pin tạo thành. Điện cực làm mốc đó là", o: ["điện cực hydrogen chuẩn", "điện cực đồng chuẩn", "điện cực bạc chuẩn", "điện cực magnesium chuẩn"],
        x: "Không đo trực tiếp được thế của một điện cực riêng lẻ, nên người ta chọn cặp 2H⁺/H₂ làm mốc, quy ước E°(2H⁺/H₂) = 0 V. Trong điện cực hydrogen chuẩn, khí H₂ (áp suất 1 bar) được hấp phụ trên một lá platinum nhúng trong dung dịch có [H⁺] = 1 M. Sức điện động của pin ghép từ điện cực kẽm chuẩn và điện cực hydrogen chuẩn cho biết E°(Zn²⁺/Zn).", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Điện phân", type: "mc", q: "Điện phân dung dịch CuCl₂ với hai điện cực trơ. Sản phẩm thu được ở cathode và ở anode lần lượt là", o: ["Cu và khí Cl₂", "khí H₂ và khí Cl₂", "Cu và khí O₂", "khí H₂ và khí O₂"],
        x: "Ở cathode, ion Cu²⁺ nhận electron dễ hơn nước: Cu²⁺ + 2e → Cu. Ở anode, ion Cl⁻ nhường electron trước nước: 2Cl⁻ → Cl₂ + 2e. Phương trình điện phân: CuCl₂ → Cu + Cl₂.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Hợp kim", type: "mc", q: "Hợp kim thường được chế tạo bằng cách nào sau đây?", o: ["Nung chảy hỗn hợp các thành phần rồi để nguội", "Hoà tan các kim loại vào nước rồi cô cạn", "Đun các kim loại trong dầu ăn cho đến khi sôi", "Ngâm các kim loại chung trong một cốc giấm"],
        x: "Người ta nung các kim loại (và phi kim) thành phần đến nóng chảy, trộn đều rồi để nguội cho đông đặc lại thành hợp kim.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Nguyên tố nhóm IIA", type: "mc", q: "Kim loại nào sau đây cháy trong không khí với ánh sáng trắng chói, nên được dùng làm pháo sáng?", o: ["Magnesium (Mg)", "Vàng (Au)", "Chì (Pb)", "Thiếc (Sn)"],
        x: "Magnesium cháy mãnh liệt trong không khí, phát ra ánh sáng trắng rất mạnh: 2Mg + O₂ → 2MgO. Vì vậy bột magnesium được dùng làm pháo sáng, pháo hoa. Vàng, chì, thiếc không cháy sáng như vậy.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Nguyên tố nhóm IA", type: "mc", q: "Dẫn từ từ 2,479 L khí CO₂ vào 150 mL dung dịch NaOH 1 M. Biết ở điều kiện chuẩn, mỗi mol khí chiếm thể tích 24,79 L; thể tích CO₂ đo ở điều kiện chuẩn. Sau khi phản ứng hoàn toàn, chất tan trong dung dịch thu được gồm", o: ["Na₂CO₃ và NaHCO₃", "chỉ có Na₂CO₃", "chỉ có NaHCO₃", "Na₂CO₃ và NaOH"],
        x: "n(CO₂) = 2,479 : 24,79 = 0,1 (mol); n(NaOH) = 0,15 · 1 = 0,15 (mol). Tỉ lệ n(NaOH) : n(CO₂) = 1,5 nằm giữa 1 và 2, nên tạo cả hai muối: CO₂ + 2NaOH → Na₂CO₃ + H₂O và CO₂ + NaOH → NaHCO₃; NaOH hết. Giải hệ được 0,05 mol Na₂CO₃ và 0,05 mol NaHCO₃.", lv: 3, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Đại cương về kim loại chuyển tiếp dãy thứ nhất", type: "mc", q: "Kim loại chuyển tiếp nào sau đây được dùng nhiều nhất làm lõi dây dẫn điện trong nhà?", o: ["Đồng (Cu)", "Sắt (Fe)", "Chromium (Cr)", "Manganese (Mn)"],
        x: "Đồng dẫn điện rất tốt (chỉ kém bạc), dẻo, dễ kéo thành sợi và giá thành hợp lí, nên được dùng làm lõi dây điện. Sắt, chromium, manganese dẫn điện kém hơn nhiều.", lv: 1, pt: 0.25 },
      { part: "Phần II. Trắc nghiệm đúng sai", topic: "Giới thiệu về carbohydrate. Glucose và fructose", type: "tf4", q: "Mỗi ý sau về glucose đúng hay sai?", o: ["Glucose có nhiều trong quả nho chín nên còn được gọi là đường nho.", "Glucose không phản ứng với Cu(OH)₂ ở nhiệt độ thường vì phân tử không có nhóm –OH.", "Trong phản ứng tráng bạc, glucose bị khử.", "Lên men glucose nhờ enzyme thu được ethanol và khí carbon dioxide."], a: [true, false, false, true],
        x: "a) Đúng. b) Sai: phân tử glucose có năm nhóm –OH, các nhóm này gắn với những nguyên tử carbon cạnh nhau, nên ngay ở nhiệt độ thường glucose hoà tan được Cu(OH)₂, cho dung dịch màu xanh lam. c) Sai: glucose khử ion bạc thành bạc, còn bản thân glucose bị oxi hoá. d) Đúng: C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂.", lv: 2, pt: 1 },
      { part: "Phần II. Trắc nghiệm đúng sai", topic: "Vật liệu polymer", type: "tf4", q: "Mỗi ý sau về một số vật liệu polymer đúng hay sai?", o: ["Đồ nhựa dùng một lần như cốc, ống hút rất khó bị phân huỷ trong tự nhiên, nên dùng tràn lan sẽ gây ô nhiễm môi trường.", "Dây chun (dây thun) làm từ cao su, kéo dãn rồi buông tay thì trở lại gần như độ dài ban đầu.", "Sợi bông thuộc loại tơ tổng hợp.", "Nhựa PVC cách điện tốt nên được dùng làm vỏ bọc dây điện."], a: [true, true, false, true],
        x: "a) Đúng: chất dẻo rất bền, khó bị phân huỷ trong tự nhiên, có thể tồn tại rất lâu trong đất, nước, nên cần hạn chế đồ nhựa dùng một lần. b) Đúng: đó là tính đàn hồi của cao su. c) Sai: bông là tơ thiên nhiên, thành phần chính là cellulose. d) Đúng: PVC cách điện, bền, dùng làm vỏ dây điện, ống dẫn nước.", lv: 1, pt: 1 },
      { part: "Phần II. Trắc nghiệm đúng sai", topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "tf4", q: "Tiến hành ba thí nghiệm ở điều kiện thường: (1) cho lá kẽm vào dung dịch Pb(NO₃)₂; (2) cho lá đồng vào dung dịch AgNO₃; (3) cho lá bạc vào dung dịch Cu(NO₃)₂. Cho E°(Zn²⁺/Zn) = −0,762 V; E°(Pb²⁺/Pb) = −0,126 V; E°(Cu²⁺/Cu) = +0,340 V; E°(Ag⁺/Ag) = +0,799 V. Mỗi ý sau đúng hay sai?", o: ["Ở thí nghiệm (1), có kim loại chì bám lên lá kẽm.", "Ở thí nghiệm (2), dung dịch dần chuyển sang màu xanh.", "Ở thí nghiệm (3), có kim loại đồng bám lên lá bạc.", "Theo các giá trị E° đã cho, ion Pb²⁺ có tính oxi hoá mạnh hơn ion Cu²⁺."], a: [true, true, false, false],
        x: "a) Đúng: E°(Zn²⁺/Zn) < E°(Pb²⁺/Pb) nên Zn + Pb²⁺ → Zn²⁺ + Pb. b) Đúng: Cu + 2Ag⁺ → Cu²⁺ + 2Ag; ion Cu²⁺ tạo ra làm dung dịch có màu xanh. c) Sai: E°(Ag⁺/Ag) > E°(Cu²⁺/Cu) nên bạc không khử được ion Cu²⁺. d) Sai: E°(Pb²⁺/Pb) < E°(Cu²⁺/Cu) nên ion Pb²⁺ có tính oxi hoá yếu hơn ion Cu²⁺.", lv: 2, pt: 1 },
      { part: "Phần II. Trắc nghiệm đúng sai", topic: "Một số tính chất và ứng dụng của phức chất", type: "tf4", q: "Dung dịch CuSO₄ loãng có màu xanh lam do chứa ion phức [Cu(H₂O)₆]²⁺. Thêm từ từ dung dịch HCl đặc vào thì dung dịch chuyển dần sang màu vàng lục do tạo thành ion phức [CuCl₄]²⁻. Mỗi ý sau đúng hay sai?", o: ["Phản ứng [Cu(H₂O)₆]²⁺ + 4Cl⁻ ⇌ [CuCl₄]²⁻ + 6H₂O là phản ứng thế phối tử.", "Trong [CuCl₄]²⁻, nguyên tử trung tâm mang điện tích +4.", "Phức chất [CuCl₄]²⁻ có ít phối tử hơn phức chất [Cu(H₂O)₆]²⁺.", "Pha loãng dung dịch màu vàng lục bằng nhiều nước thì màu xanh lam có thể xuất hiện trở lại."], a: [true, false, true, true],
        x: "a) Đúng: các phối tử H₂O được thay bằng các phối tử Cl⁻. b) Sai: phức chất mang điện tích −2, bốn phối tử Cl⁻ mang tổng điện tích −4, nên nguyên tử trung tâm là Cu²⁺ (điện tích +2). c) Đúng: 4 phối tử so với 6 phối tử. d) Đúng: thêm nhiều nước làm cân bằng chuyển dịch theo chiều tạo lại [Cu(H₂O)₆]²⁺.", lv: 3, pt: 1 },
      { part: "Phần III. Trả lời ngắn", topic: "Ester – Lipid", type: "num", q: "Một mẫu chất béo có 80% khối lượng là tristearin ((C₁₇H₃₅COO)₃C₃H₅), tạp chất không tham gia phản ứng. Đun 1 tấn chất béo này với lượng dư kiềm (NaOH) để nấu xà phòng thì thu được bao nhiêu kilogam glycerol? (Cho H = 1, C = 12, O = 16; làm tròn kết quả đến hàng phần mười.)", ans: 82.7, tol: 0.05, unit: "kg",
        x: "(C₁₇H₃₅COO)₃C₃H₅ + 3NaOH → 3C₁₇H₃₅COONa + C₃H₅(OH)₃. 1 tấn chất béo chứa 800 kg tristearin (M = 890). Số mol glycerol bằng số mol chất béo, nên khối lượng glycerol (M = 92) là 800 · 92 : 890 = 82,69 (kg) ≈ 82,7 kg.", lv: 3, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Lớp 10 · Tốc độ phản ứng", type: "num", q: "Xét phản ứng Mg + 2HCl → MgCl₂ + H₂ trong dung dịch. Sau 3 phút, nồng độ HCl giảm từ 0,80 M xuống 0,56 M. Tốc độ trung bình của phản ứng trong khoảng thời gian này bằng bao nhiêu M/phút?", ans: 0.04,
        x: "Tốc độ trung bình tính theo HCl (hệ số 2 trong phương trình): v = (1/2) · (0,80 − 0,56) : 3 = 0,04 (M/phút).", lv: 2, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Amine", type: "num", q: "Cho 9 g ethylamine (C₂H₅NH₂) tác dụng vừa đủ với dung dịch HCl. Khối lượng muối thu được bằng bao nhiêu gam? (Cho H = 1, C = 12, N = 14, Cl = 35,5.)", ans: 16.3, unit: "g",
        x: "C₂H₅NH₂ + HCl → C₂H₅NH₃Cl. n(C₂H₅NH₂) = 9 : 45 = 0,2 (mol) = n(muối); khối lượng muối là 0,2 · 81,5 = 16,3 (g).", lv: 2, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Kim loại trong tự nhiên và phương pháp tách kim loại", type: "num", q: "Magnesium được sản xuất bằng cách điện phân MgCl₂ nóng chảy: MgCl₂ → Mg + Cl₂. Từ 19 tấn MgCl₂, với hiệu suất 80%, thu được bao nhiêu tấn magnesium? (Cho Mg = 24, Cl = 35,5.)", ans: 3.84, unit: "tấn",
        x: "n(MgCl₂) = 19 : 95 = 0,2 (triệu mol) = n(Mg) theo lí thuyết. Khối lượng magnesium: 0,2 · 24 · 80% = 3,84 (tấn).", lv: 3, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Nguyên tố nhóm IIA", type: "num", q: "Cho các kim loại: Na, Mg, Al, Ca, K, Ba. Có bao nhiêu kim loại thuộc nhóm IIA?", ans: 3,
        x: "Magnesium, calcium và barium thuộc nhóm IIA (2 electron hoá trị). Sodium và potassium thuộc nhóm IA, aluminium thuộc nhóm IIIA.", lv: 1, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Đại cương về kim loại chuyển tiếp dãy thứ nhất", type: "num", q: "Nguyên tử đồng có 10 electron ở phân lớp 3d và 1 electron ở phân lớp 4s. Ion Cu²⁺ có bao nhiêu electron ở phân lớp 3d?", ans: 9,
        x: "Các nguyên tử từ Sc đến Cu, khi tạo ion, mất electron 4s trước, sau đó mới đến electron 3d. Ion Cu²⁺ ứng với nguyên tử đồng mất 1 electron 4s và 1 electron 3d, nên có cấu hình [Ar]3d⁹, tức 9 electron ở phân lớp 3d.", lv: 2, pt: 0.25 }
    ]
  },
  "hoahoc12-tn-de4": {
    note: "Đề thi thử theo cấu trúc đề thi tốt nghiệp THPT từ năm 2025 (Quyết định 764/QĐ-BGDĐT). Năm 2027 thí điểm thi trên máy tính ở nơi đủ điều kiện, đề như thi giấy. Phạm vi: chương trình THPT, chủ yếu Hoá học 12 (sách Kết nối tri thức, cả năm học). Như đề tham khảo năm 2025 và đề chính thức năm 2026 (2 câu thuộc lớp 10, 2 câu thuộc lớp 11, còn lại thuộc lớp 12), đề có 24 câu Hoá học 12, 2 câu Hoá học 11 và 2 câu Hoá học 10. Đề có 28 câu, làm trong 50 phút: Phần I gồm 18 câu nhiều lựa chọn (4,5 điểm, mỗi câu 0,25 điểm), Phần II gồm 4 câu đúng/sai, mỗi câu 4 ý (4 điểm), Phần III gồm 6 câu trả lời ngắn (1,5 điểm, mỗi câu 0,25 điểm). App chấm tự động cả ba phần như đề thật: ở Phần II, đúng 1, 2, 3 hay cả 4 ý của một câu thì câu đó được 0,1; 0,25; 0,5 hay 1 điểm; ở Phần III, bạn ghi đáp số (không quá 4 kí tự), câu nào dặn làm tròn thì làm tròn đúng như dặn. Nguyên tử khối và các số liệu cần dùng được cho ngay trong câu. Đề không có câu tự chấm, nên điểm lưu ở mục Kết quả là điểm của cả đề.",
    questions: [
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Ester – Lipid", type: "mc", q: "Ester nào sau đây có mùi chuối chín, thường được dùng làm chất tạo hương cho bánh kẹo, nước giải khát?", o: ["Isoamyl acetate", "Ethyl propanoate", "Methyl formate", "Tristearin"],
        x: "Isoamyl acetate (CH₃COOCH₂CH₂CH(CH₃)₂) có mùi chuối chín, còn gọi là dầu chuối. Nhiều ester có mùi thơm của hoa, quả nên được dùng làm hương liệu. Tristearin là một chất béo, không có mùi thơm của quả chín.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Saccharose và maltose", type: "mc", q: "Maltose (có nhiều trong đường mạch nha) được dùng chủ yếu làm nguyên liệu để", o: ["sản xuất bia", "nấu xà phòng", "làm giấy in", "chế tạo phân đạm"],
        x: "Mạch nha giàu maltose là nguyên liệu chính để nấu bia; maltose còn làm chất tạo ngọt cho một số bánh kẹo. Xà phòng được nấu từ chất béo, giấy làm từ cellulose của gỗ, tre, nứa.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Tinh bột và cellulose", type: "mc", q: "Trong cơ thể người, glucose chưa dùng đến có thể được chuyển thành chất nào sau đây để dự trữ trong gan và cơ?", o: ["Glycogen", "Cellulose", "Saccharose", "Fructose"],
        x: "Tinh bột trong thức ăn bị thuỷ phân dần thành glucose, chất này đi vào máu; phần glucose chưa dùng đến được chuyển thành glycogen (một polysaccharide) để dự trữ trong gan và cơ. Cơ thể người không tổng hợp cellulose.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Amine", type: "mc", q: "Mùi tanh của cá chủ yếu do một số amine có trong cá gây nên. Trước khi chế biến, nên rửa cá bằng chất nào sau đây để làm giảm mùi tanh?", o: ["Giấm ăn", "Đường kính", "Nước vôi", "Nước xà phòng"],
        x: "Amine có tính base nên tác dụng với acid có trong giấm (acetic acid), tạo thành muối dễ tan, bị rửa trôi theo nước, nhờ đó mùi tanh giảm. Nước vôi, nước xà phòng có môi trường base, đường kính không có tính acid, nên không làm giảm mùi tanh theo cách này.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Amine", type: "mc", q: "Amine X (no, đơn chức, mạch hở) chứa 31,11% nitrogen về khối lượng. Ứng với X có bao nhiêu công thức cấu tạo? (Cho H = 1, C = 12, N = 14.)", o: ["2", "1", "3", "4"],
        x: "Công thức chung của amine no, đơn chức, mạch hở là CₙH₂ₙ₊₃N. Phần trăm khối lượng nitrogen: 14 : (14n + 17) = 31,11% nên n = 2, X là C₂H₇N. Các công thức cấu tạo: CH₃CH₂NH₂ (ethylamine) và CH₃NHCH₃ (dimethylamine), tổng cộng 2.", lv: 3, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Amino acid và peptide", type: "mc", q: "Liên kết peptide là liên kết –CO–NH– giữa hai đơn vị α-amino acid. Chất nào sau đây là một dipeptide?", o: ["H₂N–CH₂–CO–NH–CH₂–COOH", "H₂N–CH₂–COO–CH₂–COOH", "CH₃–CO–NH–CH₂–COOH", "H₂N–CH₂–CH₂–NH–CH₂–COOH"],
        x: "Dipeptide tạo từ hai đơn vị α-amino acid nối với nhau bằng một liên kết peptide –CO–NH–. H₂N–CH₂–CO–NH–CH₂–COOH tạo từ hai đơn vị glycine. Chất có nhóm –COO– là một ester; ở CH₃–CO–NH–CH₂–COOH, phần CH₃–CO– là gốc của acetic acid, không phải đơn vị amino acid; chất có đoạn –CH₂–NH–CH₂– không có nhóm –CO–NH–.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Protein và enzyme", type: "mc", q: "Nhỏ vài giọt dung dịch HNO₃ đặc vào ống nghiệm đựng dung dịch lòng trắng trứng. Hiện tượng quan sát được là", o: ["có kết tủa màu vàng", "có kết tủa màu đen", "có kết tủa màu trắng", "dung dịch hoá tím"],
        x: "Nitric acid đặc tác dụng với protein trong lòng trắng trứng tạo thành sản phẩm rắn màu vàng; đây là một phản ứng màu dùng để nhận biết protein. Màu tím là màu của phản ứng biuret (protein với Cu(OH)₂ trong môi trường kiềm).", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Đại cương về polymer", type: "mc", q: "Phân tử chất nào sau đây không trùng hợp được thành polymer?", o: ["Propane", "Ethylene", "Styrene", "Vinyl chloride"],
        x: "Monomer tham gia phản ứng trùng hợp phải có liên kết bội (như C=C) hoặc vòng kém bền. Propane (CH₃–CH₂–CH₃) chỉ có liên kết đơn nên không trùng hợp được; ethylene, styrene, vinyl chloride đều có liên kết C=C.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Vật liệu polymer", type: "mc", q: "Lốp xe, đế giày thường được làm từ cao su đã lưu hoá. So với cao su chưa lưu hoá, cao su lưu hoá bền hơn, đàn hồi tốt hơn và ít bị dính khi trời nóng, chủ yếu vì", o: ["giữa các mạch polymer có cầu nối –S–S–, tạo cấu trúc mạng không gian", "lưu huỳnh cắt các mạch polymer dài thành nhiều mạch ngắn, dễ sắp xếp hơn", "lưu huỳnh làm mất hết liên kết đôi, biến cao su thành polyethylene", "cao su lưu hoá có thêm nhiều nhóm –OH tạo liên kết hydrogen"],
        x: "Khi lưu hoá, lưu huỳnh tạo các cầu nối disulfide (–S–S–) giữa các mạch cao su, các mạch liên kết thành mạng không gian; nhờ vậy cao su lưu hoá bền, đàn hồi tốt hơn, khó tan trong dung môi hơn và ít bị dính khi nóng. Lưu huỳnh không cắt ngắn mạch polymer; cao su lưu hoá không có thêm nhóm –OH.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Lớp 10 · Nguyên tố nhóm halogen", type: "mc", q: "Nước Javel được dùng để tẩy màu vải sợi và khử trùng. Chất có tác dụng tẩy màu, khử trùng trong nước Javel là", o: ["NaClO", "NaCl", "NaOH", "KCl"],
        x: "Thành phần của nước Javel gồm NaCl, NaClO và một lượng nhỏ NaOH. NaClO (sodium hypochlorite) có tính oxi hoá mạnh nên tẩy được màu, diệt được vi khuẩn; NaCl, NaOH không có tác dụng này.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Lớp 11 · Đại cương về hoá học hữu cơ", type: "mc", q: "Dầu ăn không tan trong nước; đổ chung dầu ăn với nước rồi để yên thì hỗn hợp tách thành hai lớp. Dụng cụ nào sau đây thích hợp nhất để tách riêng lớp dầu ăn ra khỏi nước?", o: ["Phễu chiết", "Giấy lọc", "Bát sứ", "Ống sinh hàn"],
        x: "Hai chất lỏng không tan vào nhau, đã tách lớp, được tách riêng bằng phễu chiết: chờ hai lớp tách hẳn rồi mở van cho nước (lớp dưới) chảy xuống, dầu ăn (lớp trên) còn lại trong phễu. Giấy lọc dùng tách chất rắn ra khỏi chất lỏng, bát sứ dùng để cô cạn, ống sinh hàn dùng khi chưng cất.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Lớp 11 · Nitrogen – Sulfur", type: "mc", q: "Không nên bón phân đạm ammonium (như NH₄NO₃, (NH₄)₂SO₄) cùng lúc với vôi (Ca(OH)₂) vì", o: ["muối ammonium tác dụng với vôi giải phóng khí NH₃, làm mất đạm", "vôi oxi hoá muối ammonium thành khí N₂ bay vào không khí", "phân đạm làm vôi bị phân huỷ, giải phóng khí CO₂", "vôi làm muối ammonium kết tinh lại, cây khó hấp thụ"],
        x: "Muối ammonium tác dụng với base giải phóng khí ammonia, ví dụ: 2NH₄NO₃ + Ca(OH)₂ → Ca(NO₃)₂ + 2NH₃ + 2H₂O. Khí NH₃ bay đi làm mất một phần nitrogen của phân, giảm hiệu quả bón phân.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Điện phân", type: "mc", q: "Trong công nghiệp sản xuất nhôm, Al₂O₃ được trộn với cryolite (Na₃AlF₆) rồi mới điện phân nóng chảy. Mục đích chính của việc dùng cryolite là", o: ["hạ nhiệt độ nóng chảy của hỗn hợp, tiết kiệm năng lượng", "cung cấp thêm ion Al³⁺, làm tăng gấp đôi lượng nhôm", "giúp Al₂O₃ tan được trong nước để điện phân dung dịch", "bảo vệ anode than chì không bị oxygen đốt cháy"],
        x: "Al₂O₃ nóng chảy ở khoảng 2 050 °C; hỗn hợp Al₂O₃ với cryolite nóng chảy ở gần 1 000 °C, nên tiết kiệm được nhiều năng lượng. Hỗn hợp nóng chảy này còn dẫn điện tốt và nổi lên trên nhôm lỏng, ngăn nhôm tiếp xúc với không khí. Anode than chì vẫn bị oxygen sinh ra đốt cháy dần.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "mc", q: "Một kim loại mềm, dùng dao cắt được dễ dàng; để ngoài không khí, bề mặt vừa cắt sáng bóng nhanh chóng bị mờ đi. Kim loại đó là", o: ["Potassium (K)", "Sắt (Fe)", "Đồng (Cu)", "Nickel (Ni)"],
        x: "Kim loại kiềm (như sodium, potassium) rất mềm, dùng dao cắt được dễ dàng. Kim loại kiềm có tính khử rất mạnh nên bề mặt vừa cắt bị oxygen trong không khí oxi hoá nhanh, mất ánh kim. Sắt, đồng, nickel cứng hơn nhiều, không cắt được bằng dao.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Nguyên tố nhóm IA", type: "mc", q: "Soda (Na₂CO₃) được dùng trong xử lí nước chủ yếu để", o: ["làm mềm nước cứng", "khử trùng, diệt vi khuẩn", "tạo màu cho nước", "làm tăng độ cứng của nước"],
        x: "Ion CO₃²⁻ kết hợp với ion Ca²⁺, Mg²⁺ tạo kết tủa CaCO₃, MgCO₃, làm giảm nồng độ các ion này nên nước cứng trở thành nước mềm, ví dụ: Ca²⁺ + CO₃²⁻ → CaCO₃.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Nguyên tố nhóm IIA", type: "mc", q: "Sục từ từ khí CO₂ đến dư vào ống nghiệm đựng nước vôi trong (dung dịch Ca(OH)₂). Hiện tượng quan sát được là", o: ["có kết tủa trắng, rồi kết tủa tan dần đến hết", "có kết tủa trắng, sục thêm CO₂ thì kết tủa vẫn không tan", "không có kết tủa, dung dịch luôn trong suốt", "có kết tủa màu xanh lam, sau đó chuyển màu đen"],
        x: "Lúc đầu: CO₂ + Ca(OH)₂ → CaCO₃ + H₂O, kết tủa trắng CaCO₃ làm nước vôi vẩn đục. Khi CO₂ dư: CaCO₃ + CO₂ + H₂O → Ca(HCO₃)₂; calcium hydrogencarbonate tan nên kết tủa tan dần, dung dịch trong trở lại.", lv: 2, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Đại cương về kim loại chuyển tiếp dãy thứ nhất", type: "mc", q: "Kim loại chuyển tiếp nào sau đây cứng nhất, có thể dùng để cắt kính?", o: ["Chromium (Cr)", "Sắt (Fe)", "Nickel (Ni)", "Manganese (Mn)"],
        x: "Chromium là kim loại cứng nhất, cứng tới mức cắt được kính; vì vậy chromium được mạ lên bề mặt nhiều đồ vật để chống mài mòn, chống gỉ. Sắt, nickel, manganese đều mềm hơn chromium.", lv: 1, pt: 0.25 },
      { part: "Phần I. Trắc nghiệm nhiều lựa chọn", topic: "Đại cương về kim loại chuyển tiếp dãy thứ nhất", type: "mc", q: "Cho số hiệu nguyên tử: Mn (Z = 25), Fe (Z = 26), Ni (Z = 28). Cặp ion nào sau đây có cùng cấu hình electron [Ar]3d⁵?", o: ["Mn²⁺ và Fe³⁺", "Mn²⁺ và Fe²⁺", "Fe²⁺ và Ni²⁺", "Mn³⁺ và Fe³⁺"],
        x: "Mn: [Ar]3d⁵4s² nên Mn²⁺: [Ar]3d⁵, Mn³⁺: [Ar]3d⁴. Fe: [Ar]3d⁶4s² nên Fe²⁺: [Ar]3d⁶, Fe³⁺: [Ar]3d⁵. Ni: [Ar]3d⁸4s² nên Ni²⁺: [Ar]3d⁸. Khi tạo ion, nguyên tử mất electron 4s trước rồi mới mất electron 3d. Chỉ Mn²⁺ và Fe³⁺ cùng có cấu hình [Ar]3d⁵.", lv: 3, pt: 0.25 },
      { part: "Phần II. Trắc nghiệm đúng sai", topic: "Ester – Lipid", type: "tf4", q: "Mỗi ý sau về chất béo và acid béo đúng hay sai?", o: ["Phân tử acid béo omega-3 (có nhiều trong dầu cá biển) không có liên kết đôi C=C.", "Các vitamin A, D, E, K tan tốt trong chất béo nên được cơ thể hấp thụ cùng với chất béo.", "Với cùng một khối lượng, chất béo khi được chuyển hoá trong cơ thể cung cấp ít năng lượng hơn tinh bột.", "Có thể sản xuất bơ thực vật (dạng rắn) bằng cách cho dầu thực vật cộng hydrogen (có xúc tác, đun nóng)."], a: [false, true, false, true],
        x: "a) Sai: omega-3 là acid béo không no, trong mạch carbon có liên kết đôi C=C. b) Đúng. c) Sai: với cùng khối lượng, chất béo cung cấp năng lượng nhiều hơn tinh bột, đường. d) Đúng: phản ứng cộng H₂ làm giảm số liên kết đôi C=C trong phân tử, dầu lỏng chuyển thành chất béo rắn.", lv: 1, pt: 1 },
      { part: "Phần II. Trắc nghiệm đúng sai", topic: "Sự ăn mòn kim loại", type: "tf4", q: "Ngoài trời, một đoạn dây điện bằng nhôm được nối trực tiếp với một đoạn dây điện bằng đồng. Sau một thời gian trong không khí ẩm, chỗ nối bị hỏng. Cho E°(Al³⁺/Al) = −1,676 V; E°(Cu²⁺/Cu) = +0,340 V. Mỗi ý sau đúng hay sai?", o: ["Ở chỗ nối, đồng đóng vai trò anode và bị ăn mòn trước.", "Nhôm, đồng cùng lớp hơi ẩm có hoà tan chất điện li ở chỗ nối tạo thành một pin điện hoá.", "Ở chỗ nối, nhôm bị ăn mòn điện hoá: Al → Al³⁺ + 3e.", "Quấn kín chỗ nối bằng băng dính cách điện để ngăn hơi ẩm giúp chỗ nối bền hơn."], a: [false, true, true, true],
        x: "a) Sai: E°(Al³⁺/Al) nhỏ hơn E°(Cu²⁺/Cu) nên nhôm là anode, bị ăn mòn; đồng là cathode. b) Đúng: hai kim loại khác nhau tiếp xúc trực tiếp với nhau và cùng tiếp xúc với dung dịch chất điện li là điều kiện của ăn mòn điện hoá. c) Đúng. d) Đúng: không có hơi ẩm (dung dịch chất điện li) thì không xảy ra ăn mòn điện hoá.", lv: 2, pt: 1 },
      { part: "Phần II. Trắc nghiệm đúng sai", topic: "Nguyên tố nhóm IIA", type: "tf4", q: "Một học sinh làm thí nghiệm nhận biết ba dung dịch bão hoà mất nhãn: KCl, CaCl₂, BaCl₂. Học sinh nhúng đầu một sợi dây nickel sạch vào từng dung dịch rồi hơ trên ngọn lửa không màu của đèn khí, quan sát màu ngọn lửa. Mỗi ý sau đúng hay sai?", o: ["Dung dịch làm ngọn lửa có màu lục là dung dịch BaCl₂.", "Dung dịch CaCl₂ làm ngọn lửa có màu tím nhạt.", "Màu của ngọn lửa do ion Cl⁻ gây ra, nên ba dung dịch cho cùng một màu.", "Nếu thay dung dịch BaCl₂ bằng dung dịch Ba(NO₃)₂ thì ngọn lửa vẫn có màu lục."], a: [true, false, false, true],
        x: "a) Đúng: ion Ba²⁺ làm ngọn lửa có màu lục. b) Sai: ion Ca²⁺ cho màu đỏ cam; màu tím nhạt là của ion K⁺. c) Sai: màu ngọn lửa do ion kim loại gây ra, mỗi ion kim loại cho một màu đặc trưng. d) Đúng: màu lục là của ion Ba²⁺, không phụ thuộc vào anion.", lv: 2, pt: 1 },
      { part: "Phần II. Trắc nghiệm đúng sai", topic: "Một số tính chất và ứng dụng của phức chất", type: "tf4", q: "Dung dịch CoCl₂ loãng có màu hồng đỏ do chứa ion phức [Co(H₂O)₆]²⁺. Thêm từ từ dung dịch NH₃ đến dư vào dung dịch này, sau cùng thu được dung dịch màu vàng nâu chứa ion phức [Co(NH₃)₆]²⁺. Mỗi ý sau đúng hay sai?", o: ["Ion phức [Co(H₂O)₆]²⁺ có 6 phối tử H₂O bao quanh nguyên tử trung tâm Co²⁺.", "Phản ứng tạo thành [Co(NH₃)₆]²⁺ từ [Co(H₂O)₆]²⁺ là phản ứng thế phối tử: các phối tử H₂O bị thay bằng các phối tử NH₃.", "Ion phức [Co(NH₃)₆]²⁺ có dạng hình học tứ diện.", "Để chuyển hết 0,02 mol ion [Co(H₂O)₆]²⁺ thành [Co(NH₃)₆]²⁺ cần ít nhất 0,08 mol NH₃."], a: [true, true, false, false],
        x: "a) Đúng. b) Đúng: [Co(H₂O)₆]²⁺ + 6NH₃ → [Co(NH₃)₆]²⁺ + 6H₂O. c) Sai: phức chất có 6 phối tử thường có dạng hình học bát diện. d) Sai: theo phương trình, mỗi ion phức cần 6 phân tử NH₃, nên cần ít nhất 0,02 · 6 = 0,12 (mol) NH₃.", lv: 3, pt: 1 },
      { part: "Phần III. Trả lời ngắn", topic: "Amino acid và peptide", type: "num", q: "Cho 8,9 g alanine (CH₃CH(NH₂)COOH) phản ứng hết với lượng NaOH vừa đủ trong dung dịch. Khối lượng muối thu được bằng bao nhiêu gam? (Cho H = 1, C = 12, N = 14, O = 16, Na = 23.)", ans: 11.1, unit: "g",
        x: "CH₃CH(NH₂)COOH + NaOH → CH₃CH(NH₂)COONa + H₂O. n(alanine) = 8,9 : 89 = 0,1 (mol) nên n(muối) = 0,1 mol; khối lượng muối: 0,1 · 111 = 11,1 (g).", lv: 2, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Lớp 10 · Phản ứng oxi hoá – khử", type: "num", q: "Trong phòng thí nghiệm, khí chlorine được điều chế theo phản ứng: 2KMnO₄ + 16HCl → 2KCl + 2MnCl₂ + 5Cl₂ + 8H₂O. Trong 16 phân tử HCl tham gia phản ứng, có bao nhiêu phân tử đóng vai trò chất khử?", ans: 10,
        x: "Chất khử là chất nhường electron. Chỉ những nguyên tử Cl chuyển thành Cl₂ mới tăng số oxi hoá (từ −1 lên 0): 5 phân tử Cl₂ ứng với 10 nguyên tử Cl, tức 10 phân tử HCl đóng vai trò chất khử. 6 phân tử HCl còn lại tạo muối KCl, MnCl₂ (Cl giữ số oxi hoá −1), chỉ đóng vai trò môi trường.", lv: 2, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Đại cương về polymer", type: "num", q: "Trùng hợp 4,2 tấn propylene với hiệu suất 80%. Khối lượng polypropylene thu được bằng bao nhiêu tấn?", ans: 3.36, unit: "tấn",
        x: "Trong phản ứng trùng hợp, các phân tử monomer nối với nhau thành polymer, không tách ra chất nào khác, nên khối lượng polymer bằng khối lượng monomer đã phản ứng: 4,2 · 80% = 3,36 (tấn).", lv: 1, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Thế điện cực và nguồn điện hoá học", type: "num", q: "Một pin Galvani gồm hai điện cực chuẩn: kẽm (cặp Zn²⁺/Zn) và bạc (cặp Ag⁺/Ag). Cho E°(Zn²⁺/Zn) = −0,762 V; E°(Ag⁺/Ag) = +0,799 V. Sức điện động chuẩn của pin bằng bao nhiêu volt? (Làm tròn kết quả đến hàng phần trăm.)", ans: 1.56, tol: 0.005, unit: "V",
        x: "Bạc có thế điện cực chuẩn lớn hơn nên là cathode, kẽm là anode. E°pin = E°(Ag⁺/Ag) − E°(Zn²⁺/Zn) = 0,799 − (−0,762) = 1,561 ≈ 1,56 (V).", lv: 2, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Tính chất vật lí và tính chất hoá học của kim loại", type: "num", q: "Nhúng một lá sắt nặng 10 g vào dung dịch CuSO₄. Sau một thời gian, lấy lá sắt ra, rửa nhẹ, làm khô rồi cân thì thấy nặng 10,4 g. Coi toàn bộ đồng sinh ra đều bám trên lá sắt. Khối lượng đồng bám trên lá sắt bằng bao nhiêu gam? (Cho Fe = 56, Cu = 64.)", ans: 3.2, unit: "g",
        x: "Fe + CuSO₄ → FeSO₄ + Cu. Gọi số mol Fe phản ứng là x thì có x mol Cu bám vào; khối lượng lá tăng 64x − 56x = 8x = 10,4 − 10 = 0,4 (g), nên x = 0,05. Khối lượng đồng bám trên lá sắt: 0,05 · 64 = 3,2 (g).", lv: 3, pt: 0.25 },
      { part: "Phần III. Trả lời ngắn", topic: "Nguyên tố nhóm IIA", type: "num", q: "Nung 1 tấn đá vôi (chứa 80% CaCO₃ về khối lượng, tạp chất không bị phân huỷ) một thời gian, thu được 0,78 tấn chất rắn. Hiệu suất của phản ứng phân huỷ CaCO₃ bằng bao nhiêu phần trăm? (Cho C = 12, O = 16, Ca = 40.)", ans: 62.5, unit: "%",
        x: "CaCO₃ → CaO + CO₂. Khối lượng chất rắn giảm chính là khối lượng CO₂ thoát ra: 1 − 0,78 = 0,22 (tấn). Khối lượng CaCO₃ đã phân huỷ: 0,22 · 100 : 44 = 0,5 (tấn). Đá vôi chứa 1 · 80% = 0,8 (tấn) CaCO₃, nên hiệu suất là 0,5 : 0,8 · 100% = 62,5%.", lv: 3, pt: 0.25 }
    ]
  }
});
